/**
 * 16x16 crosshair: 2px white arms with a 1px dark halo so it stays
 * readable against both sky and stone.
 */
private int makeCrosshair() {
    int s = CROSSHAIR_SIZE;
    int[] p = new int[s * s];

    int c0 = s / 2 - 1;  // first of the two centre rows/columns
    int arm = 6;
    int gap = 1;

    // Halo first, then the bright arms on top
    for (int i = gap; i < arm; i++) {
        plotArm(p, s, c0, i, 0x90000000, true);
        plotArm(p, s, c0, i, 0x90000000, false);
    }
    for (int i = gap; i < arm; i++) {
        plotArm(p, s, c0, i, 0xFFFFFFFF, true);
        plotArm(p, s, c0, i, 0xFFFFFFFF, false);
    }
    return upload(p, s, s, false);
}

/** Draw one 2px-wide arm segment at distance i from the centre. */
private void plotArm(int[] p, int s, int c0, int i, int color, boolean horizontal) {
    int a = c0;
    int b = c0 + 1;
    if (horizontal) {
        set(p, s, c0 - i + 1, a, color); set(p, s, c0 - i + 1, b, color);
        set(p, s, c0 + i, a, color);     set(p, s, c0 + i, b, color);
    } else {
        set(p, s, a, c0 - i + 1, color); set(p, s, b, c0 - i + 1, color);
        set(p, s, a, c0 + i, color);     set(p, s, b, c0 + i, color);
    }
}

