    /** Spawn initial mobs around the player. */
    public void spawnInitialMobs(Vector3f playerPos) {
        if (!mobs.isEmpty()) return;

        // Spawn passive mobs during day
        for (int i = 0; i < 5; i++) {
            float x = playerPos.x + (float) (Math.random() - 0.5) * 30;
            float z = playerPos.z + (float) (Math.random() - 0.5) * 30;
            int groundY = getGroundHeight((int) x, (int) z);
            if (groundY > 0) {
                Mob.MobType type = switch ((int) (Math.random() * 4)) {
                    case 0 -> Mob.MobType.PIG;
                    case 1 -> Mob.MobType.COW;
                    case 2 -> Mob.MobType.SHEEP;
                    default -> Mob.MobType.CHICKEN;
                };
                mobs.add(new Mob(type, this, x, groundY + 1, z));
            }
        }
    }

    /** Update all mobs. */
    public void updateMobs(float dt, Vector3f playerPos) {
        for (Mob mob : mobs) {
            mob.update(dt);

            // Hostile mobs chase player
            if (mob.getType().isHostile()) {
                float dx = playerPos.x - mob.getPosition().x;
                float dz = playerPos.z - mob.getPosition().z;
                float dist = (float) Math.sqrt(dx * dx + dz * dz);
                if (dist < 15.0f) {
                    // Chase player
                    mob.velocity.x = (dx / dist) * mob.getType().speed;
                    mob.velocity.z = (dz / dist) * mob.getType().speed;
                }
            }
        }

        // Remove dead mobs
        mobs.removeIf(mob -> {
            if (mob.isDead()) {
                // Drop items
                spawnMobDrops(mob);
                return true;
            }
            return false;
        });
    }

