    public void spawnHostileMobs(Vector3f playerPos, boolean isNight) {
        if (!isNight) return;
        if (mobs.size() > 20) return; // Cap total mobs

        if (Math.random() < 0.01f) { // Low chance per frame
            float x = playerPos.x + (float) (Math.random() - 0.5) * 40;
            float z = playerPos.z + (float) (Math.random() - 0.5) * 40;
