/**
 * Attack a mob in front of the player. Returns true if a mob was hit.
 */
private boolean attackMob() {
    Vector3f eyePos = camera.getPosition();
    Vector3f front = camera.getFront();

    // Find closest mob within reach (4 blocks) and in front of player
    Mob closestMob = null;
    float closestDist = 4.0f;

    for (var mob : world.getMobs()) {
        Vector3f mobPos = mob.getPosition();
        mobPos.y += 0.9f; // Aim at body center

        // Direction to mob
        float dx = mobPos.x - eyePos.x;
        float dy = mobPos.y - eyePos.y;
        float dz = mobPos.z - eyePos.z;
        float dist = (float) java.lang.Math.sqrt(dx * dx + dy * dy + dz * dz);

        if (dist > 4.0f) continue;

        // Check if mob is in front of player (dot product)
        float dot = (dx * front.x + dy * front.y + dz * front.z) / dist;
        if (dot < 0.7f) continue; // Must be roughly in front

        // Check if close to crosshair (angle check)
        float angle = (float) java.lang.Math.acos(dot);
        if (angle > 0.5f) continue; // Within ~30 degrees of crosshair

        if (dist < closestDist) {
            closestDist = dist;
            closestMob = mob;
        }
    }

    if (closestMob != null) {
        // Deal damage based on held item
        float damage = player.getAttackDamage();
        closestMob.takeDamage((int) damage);

        // Damage the tool
        player.damageHeldTool();

        // Spawn hit particles
        Vector3f mobPos = closestMob.getPosition();
        particles.emitHit(mobPos.x, mobPos.y + 0.9f, mobPos.z);

        return true;
    }
    return false;
}

