package com.voxelgame.world.entity;

import org.joml.Matrix4f;
import org.joml.Vector3f;

/**
 * A renderable part of a mob model (head, body, limb, etc).
 */
public class MobPart {
    public final float offsetX, offsetY, offsetZ;
    public final float sizeX, sizeY, sizeZ;
    public final float rotationX, rotationY, rotationZ;

    public MobPart(float ox, float oy, float oz, float sx, float sy, float sz) {
        this(ox, oy, oz, sx, sy, sz, 0, 0, 0);
    }

    public MobPart(float ox, float oy, float oz, float sx, float sy, float sz,
                   float rx, float ry, float rz) {
        this.offsetX = ox; this.offsetY = oy; this.offsetZ = oz;
        this.sizeX = sx; this.sizeY = sy; this.sizeZ = sz;
        this.rotationX = rx; this.rotationY = ry; this.rotationZ = rz;
    }

    /**
     * Apply this part's transform to the matrix and render.
     */
    public void render(Matrix4f base, float swing, boolean isLeft) {
        Matrix4f m = new Matrix4f(base);

        // Position relative to body
        m.translate(offsetX, offsetY, offsetZ);

        // Limb swing animation (alternating)
        float swingAmount = swing * (isLeft ? 1.0f : -1.0f);
        if (offsetY < 0) { // Legs swing
            m.rotateX(swingAmount * 0.5f);
        }
        if (offsetY > 0.5f && offsetX != 0) { // Arms swing
            m.rotateX(swingAmount * 0.4f);
        }

        // Apply base rotation
        if (rotationX != 0) m.rotateX((float) Math.toRadians(rotationX));
        if (rotationY != 0) m.rotateY((float) Math.toRadians(rotationY));
        if (rotationZ != 0) m.rotateZ((float) Math.toRadians(rotationZ));

        // Scale for this part
        m.scale(sizeX, sizeY, sizeZ);

        // Set model matrix for rendering (will be uploaded by caller)
        base.set(m); // HACK: we use this to pass back the matrix
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.rendering.model.BlockCube;
import org.joml.Matrix4f;
import org.joml.Vector3f;

/**
 * Visual model for a mob - collection of box parts with Minecraft-like proportions.
 * Each mob type has a different configuration of parts.
 */
public class MobModel {

    public enum MobModelType {
        PIG, COW, SHEEP, CHICKEN, ZOMBIE, SKELETON, CREEPER, SPIDER
    }

    // Part colors (tints applied to white cube)
    private final int bodyColor;
    private final int headColor;
    private final int limbColor;
    private final int eyeColor;

    // Part offsets and sizes
    private final float bodyW, bodyH, bodyD;
    private final float headSize;
    private final float legW, legH, legD;
    private final float armW, armH, armD;

    // Animation state
    private float limbSwing = 0;
    private float limbSwingAmount = 0;

    // Mob dimensions for collision
    public final float width;
    public final float height;

    private MobModel(int bodyColor, int headColor, int limbColor, int eyeColor,
                     float bw, float bh, float bd, float hs,
                     float lw, float lh, float ld, float aw, float ah, float ad) {
        this.bodyColor = bodyColor;
        this.headColor = headColor;
        this.limbColor = limbColor;
        this.eyeColor = eyeColor;
        this.bodyW = bw; this.bodyH = bh; this.bodyD = bd;
        this.headSize = hs;
        this.legW = lw; this.legH = lh; this.legD = ld;
        this.armW = aw; this.armH = ah; this.ad = ad;
        this.width = Math.max(bw, bd) + 0.2f;
        this.height = bh + hs + lh;
    }

    private float ad; // armD alias

    public static MobModel create(MobModelType type) {
        return switch (type) {
            case PIG -> new MobModel(
                0xFFF0B0B0, 0xFFE8A0A0, 0xFFD09090, 0xFF303030,  // pink body
                0.7f, 0.6f, 1.0f, 0.6f,  // body + head
                0.25f, 0.4f, 0.25f, 0, 0, 0  // legs, no arms
            );
            case COW -> new MobModel(
                0xFF4A3020, 0xFF3A2010, 0xFF2A1000, 0xFF101010,  // brown body
                0.8f, 0.8f, 1.2f, 0.6f,
                0.3f, 0.5f, 0.3f, 0, 0, 0
            );
            case SHEEP -> new MobModel(
                0xFFE8E8E8, 0xFFD0D0D0, 0xFFC0C0C0, 0xFF202020,  // white wool
                0.7f, 0.7f, 1.0f, 0.5f,
                0.25f, 0.45f, 0.25f, 0, 0, 0
            );
            case CHICKEN -> new MobModel(
                0xFFFFFFFF, 0xFFE0E0E0, 0xFFF0A020, 0xFF101010,  // white with red comb
                0.4f, 0.4f, 0.5f, 0.3f,
                0.15f, 0.3f, 0.15f, 0, 0, 0
            );
            case ZOMBIE -> new MobModel(
                0xFF3A6050, 0xFF4A7060, 0xFF2A5040, 0xFF000000,  // green-gray
                0.6f, 0.9f, 0.3f, 0.5f,
                0.25f, 0.9f, 0.25f, 0.2f, 0.9f, 0.2f  // long arms
            );
            case SKELETON -> new MobModel(
                0xFFD0D0D0, 0xFFE0E0E0, 0xFFB0B0B0, 0xFF000000,  // white/bone
                0.5f, 0.9f, 0.25f, 0.45f,
                0.2f, 0.9f, 0.2f, 0.15f, 0.9f, 0.15f
            );
            case CREEPER -> new MobModel(
                0xFF3AA030, 0xFF4AB040, 0xFF2A9020, 0xFF000000,  // green
                0.5f, 1.0f, 0.35f, 0.5f,
                0.25f, 0.6f, 0.25f, 0, 0, 0
            );
            case SPIDER -> new MobModel(
                0xFF2A2020, 0xFF3A3030, 0xFF1A1010, 0xFFFF0000,  // dark brown, red eyes
                0.9f, 0.4f, 0.7f, 0.4f,
                0.15f, 0.3f, 0.15f, 0, 0, 0
            );
        };
    }

    /**
     * Update animation state.
     */
    public void update(float limbSwing, float limbSwingAmount) {
        this.limbSwing = limbSwing;
        this.limbSwingAmount = limbSwingAmount;
    }

    /**
     * Render the mob model at the given position.
     */
    public void render(Matrix4f view, Shader shader, TextureAtlas atlas, BlockCube cube,
                       float x, float y, float z, float yaw) {
        Matrix4f model = new Matrix4f();

        // Position the mob
        model.translate(x, y, z);
        model.rotateY((float) Math.toRadians(yaw));

        // Render body parts
        renderBodyPart(model, cube, shader, atlas, 0, bodyH/2 + legH, 0,
            bodyW, bodyH, bodyD, bodyColor, false, 0);

        // Head
        renderBodyPart(model, cube, shader, atlas, 0, bodyH + legH, bodyD/2 - headSize/2,
            headSize, headSize, headSize, headColor, false, 0);

        // Legs (4 for animals, 2 for humanoids)
        if (armH > 0) { // Humanoid - 2 legs
            renderBodyPart(model, cube, shader, atlas, -bodyW/4, legH/2, 0,
                legW, legH, legD, limbColor, true, limbSwing);
            renderBodyPart(model, cube, shader, atlas, bodyW/4, legH/2, 0,
                legW, legH, legD, limbColor, true, -limbSwing);
            // Arms
            renderBodyPart(model, cube, shader, atlas, -bodyW/2 - armW/2, bodyH * 0.7f, 0,
                armW, armH, armD, limbColor, false, -limbSwing * 0.8f);
            renderBodyPart(model, cube, shader, atlas, bodyW/2 + armW/2, bodyH * 0.7f, 0,
                armW, armH, armD, limbColor, false, limbSwing * 0.8f);
        } else { // Animal - 4 legs
            float legSpacingX = bodyW/2 - legW/2;
            float legSpacingZ = bodyD/2 - legD/2;
            renderBodyPart(model, cube, shader, atlas, -legSpacingX, legH/2, -legSpacingZ,
                legW, legH, legD, limbColor, true, limbSwing);
            renderBodyPart(model, cube, shader, atlas, legSpacingX, legH/2, -legSpacingZ,
                legW, legH, legD, limbColor, true, -limbSwing);
            renderBodyPart(model, cube, shader, atlas, -legSpacingX, legH/2, legSpacingZ,
                legW, legH, legD, limbColor, true, -limbSwing);
            renderBodyPart(model, cube, shader, atlas, legSpacingX, legH/2, legSpacingZ,
                legW, legH, legD, limbColor, true, limbSwing);
        }
    }

    private void renderBodyPart(Matrix4f baseModel, BlockCube cube, Shader shader,
                                TextureAtlas atlas, float ox, float oy, float oz,
                                float sx, float sy, float sz, int color,
                                boolean isLeg, float swing) {
        Matrix4f partModel = new Matrix4f(baseModel);

        // Position
        partModel.translate(ox, oy, oz);

        // Animation
        if (isLeg && swing != 0) {
            partModel.rotateX(swing * 0.5f);
        } else if (!isLeg && ox != 0 && swing != 0) {
            partModel.rotateX(swing * 0.4f);
        }

        // Scale
        partModel.scale(sx, sy, sz);

        shader.setUniformMat4("model", partModel);

        // Use a white block and tint it
        cube.render(atlas, getBlockTypeFromColor(color), shader);
    }

    /**
     * Get a block type that approximates the color for rendering.
     */
    private com.voxelgame.world.BlockType getBlockTypeFromColor(int color) {
        // Map colors to closest block types for textured rendering
        int r = (color >> 16) & 0xFF;
        int g = (color >> 8) & 0xFF;
        int b = color & 0xFF;

        // Find closest match
        if (r > 200 && g > 200 && b > 200) return com.voxelgame.world.BlockType.WHITE_WOOL;
        if (r > 150 && g > 150 && b < 100) return com.voxelgame.world.BlockType.SAND;
        if (r < 60 && g < 60 && b < 60) return com.voxelgame.world.BlockType.OBSIDIAN;
        if (r > 100 && g < 80 && b < 80) return com.voxelgame.world.BlockType.BRICK;
        if (r < 80 && g > 100 && b < 80) return com.voxelgame.world.BlockType.GRASS_BLOCK;
        if (r > 100 && g > 50 && b < 50) return com.voxelgame.world.BlockType.OAK_LOG;
        if (r > 150 && g > 150 && b > 100) return com.voxelgame.world.BlockType.SAND;

        return com.voxelgame.world.BlockType.STONE;
    }
}

#version 330 core

layout (location = 0) in vec3 aPos;
layout (location = 1) in vec2 aTexCoord;
layout (location = 2) in vec3 aNormal;
layout (location = 3) in vec3 aColor;
layout (location = 4) in float aLayer;
layout (location = 5) in float aAO;

uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;
uniform mat4 lightSpace;

out vec2 TexCoord;
out vec3 Normal;
out vec3 FragPos;
out vec3 VertexColor;
out vec4 LightSpacePos;
out float AmbientOcclusion;
flat out int Layer;

void main() {
    vec4 world = model * vec4(aPos, 1.0);
    gl_Position = projection * view * world;
    FragPos = world.xyz;
    LightSpacePos = lightSpace * world;
    TexCoord = aTexCoord;
    Normal = aNormal;
    VertexColor = aColor;
    AmbientOcclusion = aAO;
    Layer = int(aLayer + 0.5);
}

#version 330 core

in vec2 TexCoord;
in vec3 Normal;
in vec3 FragPos;
in vec3 VertexColor;
in vec4 LightSpacePos;
in float AmbientOcclusion;
flat in int Layer;

uniform sampler2DArray blockTextures;
uniform sampler2DShadow shadowMap;
uniform vec3 cameraPos;
uniform vec3 sunDirection;
uniform float fogStart;
uniform float fogEnd;
uniform vec3 skyColor;
uniform vec3 sunColor;
uniform float shadowTexelSize;
uniform int shadowsEnabled;
uniform float daylight;
uniform vec3 mobTint;

out vec4 FragColor;

float sampleShadow(vec3 normal) {
    if (shadowsEnabled == 0) return 1.0;
    vec3 proj = LightSpacePos.xyz / LightSpacePos.w;
    proj = proj * 0.5 + 0.5;
    if (proj.z > 1.0 || proj.x < 0.0 || proj.x > 1.0 || proj.y < 0.0 || proj.y > 1.0) return 1.0;
    float cosTheta = clamp(dot(normal, -sunDirection), 0.0, 1.0);
    float bias = mix(0.0035, 0.0006, cosTheta);
    float sum = 0.0;
    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            vec2 offset = vec2(x, y) * shadowTexelSize;
            sum += texture(shadowMap, vec3(proj.xy + offset, proj.z - bias));
        }
    }
    return sum / 9.0;
}

void main() {
    vec4 texColor = texture(blockTextures, vec3(TexCoord, float(Layer)));
    if (texColor.a < 0.5) discard;

    vec3 normal = normalize(Normal);
    float facingSun = step(0.001, dot(normal, -sunDirection));
    float shadow = mix(1.0, sampleShadow(normal), facingSun);

    float AMBIENT = mix(0.15, 0.45, daylight);
    float direct = 0.60 * shadow * facingSun * daylight;

    float baked = max(max(VertexColor.r, VertexColor.g), VertexColor.b);
    vec3 tint = (baked > 0.0001) ? VertexColor / baked : vec3(1.0);

    // Apply mob tint color
    tint *= mobTint;

    float intensity = AMBIENT + (1.0 - AMBIENT) * baked * (0.4 + 0.6 * direct);
    intensity *= clamp(AmbientOcclusion, 0.0, 1.0) * 0.65 + 0.35;

    vec3 result = texColor.rgb * tint * intensity * sunColor;

    float dist = length(cameraPos - FragPos);
    float fogFactor = clamp((dist - fogStart) / max(fogEnd - fogStart, 1.0), 0.0, 1.0);
    result = mix(result, skyColor, fogFactor);

    FragColor = vec4(result, texColor.a);
}

