package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.rendering.model.BlockCube;
import com.voxelgame.world.BlockType;
import org.joml.Matrix4f;
import org.joml.Vector3f;

/**
 * Visual model for a mob - collection of box parts with Minecraft-like proportions.
 */
public class MobModel {

    public enum MobModelType {
        PIG, COW, SHEEP, CHICKEN, ZOMBIE, SKELETON, CREEPER, SPIDER
    }

    private final int bodyColor;
    private final int headColor;
    private final int limbColor;

    // Dimensions
    private final float bodyW, bodyH, bodyD;
    private final float headSize;
    private final float legW, legH, legD;
    private final float armW, armH, armD;
    private final boolean isHumanoid;

    // Animation
    private float limbSwing = 0;
    private float limbSwingAmount = 0;

    public final float width;
    public final float height;

    private MobModel(int bodyColor, int headColor, int limbColor,
                     float bw, float bh, float bd, float hs,
                     float lw, float lh, float ld, float aw, float ah, float ad,
                     boolean isHumanoid) {
        this.bodyColor = bodyColor;
        this.headColor = headColor;
        this.limbColor = limbColor;
        this.bodyW = bw; this.bodyH = bh; this.bodyD = bd;
        this.headSize = hs;
        this.legW = lw; this.legH = lh; this.legD = ld;
        this.armW = aw; this.armH = ah; this.armD = ad;
        this.isHumanoid = isHumanoid;
        this.width = Math.max(Math.max(bw, bd), hs) + 0.2f;
        this.height = lh + bh + hs;
    }

    public static MobModel create(MobModelType type) {
        return switch (type) {
            case PIG -> new MobModel(
                0xFFE8A0A0, 0xFFD89090, 0xFFC08080,  // pink
                0.7f, 0.6f, 1.0f, 0.6f,  // body + head
                0.25f, 0.4f, 0.25f, 0, 0, 0, false
            );
            case COW -> new MobModel(
                0xFF5A4030, 0xFF4A3020, 0xFF3A2010,  // brown
                0.8f, 0.8f, 1.2f, 0.6f,
                0.3f, 0.5f, 0.3f, 0, 0, 0, false
            );
            case SHEEP -> new MobModel(
                0xFFF0F0F0, 0xFFE0E0E0, 0xFFD0D0D0,  // white wool
                0.7f, 0.7f, 1.0f, 0.5f,
                0.25f, 0.45f, 0.25f, 0, 0, 0, false
            );
            case CHICKEN -> new MobModel(
                0xFFF8F8F8, 0xFFE8E8E8, 0xFFF0C040,  // white
                0.4f, 0.4f, 0.5f, 0.3f,
                0.15f, 0.3f, 0.15f, 0, 0, 0, false
            );
            case ZOMBIE -> new MobModel(
                0xFF4A7060, 0xFF3A6050, 0xFF2A5040,  // green-gray
                0.6f, 0.9f, 0.3f, 0.5f,
                0.25f, 0.9f, 0.25f, 0.2f, 0.9f, 0.2f, true
            );
            case SKELETON -> new MobModel(
                0xFFD8D8D8, 0xFFE8E8E8, 0xFFC0C0C0,  // bone white
                0.5f, 0.9f, 0.25f, 0.45f,
                0.2f, 0.9f, 0.2f, 0.15f, 0.9f, 0.15f, true
            );
            case CREEPER -> new MobModel(
                0xFF4AB040, 0xFF3AA030, 0xFF2A9020,  // green
                0.5f, 1.0f, 0.35f, 0.5f,
                0.25f, 0.6f, 0.25f, 0, 0, 0, false
            );
            case SPIDER -> new MobModel(
                0xFF3A3030, 0xFF2A2020, 0xFF1A1010,  // dark brown
                0.9f, 0.4f, 0.7f, 0.4f,
                0.15f, 0.3f, 0.15f, 0, 0, 0, false
            );
        };
    }

    /**
     * Update animation state.
     */
    public void update(float limbSwing, float limbSwingAmount) {
        this.limbSwing = limbSwing;
        this.limbSwingAmount = limbSwingAmount;
    }

    /**
     * Render the mob model at the given position.
     */
    public void render(Matrix4f view, Shader shader, TextureAtlas atlas, BlockCube cube,
                       float x, float y, float z, float yaw) {
        Matrix4f baseModel = new Matrix4f();
        baseModel.translate(x, y, z);
        baseModel.rotateY((float) Math.toRadians(yaw));

        // Render body
        renderPart(baseModel, shader, atlas, cube,
            0, legH + bodyH / 2, 0,
            bodyW, bodyH, bodyD, bodyColor, 0, 0, 0);

        // Render head
        float headY = legH + bodyH;
        float headZ = isHumanoid ? 0 : bodyD / 2 - headSize / 2;
        renderPart(baseModel, shader, atlas, cube,
            0, headY, headZ,
            headSize, headSize, headSize, headColor, 0, 0, 0);

        if (isHumanoid) {
            // Humanoid legs
            float swing = limbSwing * limbSwingAmount;
            renderPart(baseModel, shader, atlas, cube,
                -bodyW / 4, legH / 2, 0,
                legW, legH, legD, limbColor, swing, 0, 0);
            renderPart(baseModel, shader, atlas, cube,
                bodyW / 4, legH / 2, 0,
                legW, legH, legD, limbColor, -swing, 0, 0);
            // Humanoid arms (extended forward like zombie)
            renderPart(baseModel, shader, atlas, cube,
                -bodyW / 2 - armW / 2, legH + bodyH * 0.7f, 0,
                armW, armH, armD, limbColor, -swing * 0.8f, 0, 0);
            renderPart(baseModel, shader, atlas, cube,
                bodyW / 2 + armW / 2, legH + bodyH * 0.7f, 0,
                armW, armH, armD, limbColor, swing * 0.8f, 0, 0);
        } else {
            // Animal 4 legs
            float swing = limbSwing * limbSwingAmount;
            float lx = bodyW / 2 - legW / 2;
            float lz = bodyD / 2 - legD / 2;
            renderPart(baseModel, shader, atlas, cube,
                -lx, legH / 2, -lz,
                legW, legH, legD, limbColor, swing, 0, 0);
            renderPart(baseModel, shader, atlas, cube,
                lx, legH / 2, -lz,
                legW, legH, legD, limbColor, -swing, 0, 0);
            renderPart(baseModel, shader, atlas, cube,
                -lx, legH / 2, lz,
                legW, legH, legD, limbColor, -swing, 0, 0);
            renderPart(baseModel, shader, atlas, cube,
                lx, legH / 2, lz,
                legW, legH, legD, limbColor, swing, 0, 0);
        }
    }

    private void renderPart(Matrix4f baseModel, Shader shader, TextureAtlas atlas,
                            BlockCube cube, float ox, float oy, float oz,
                            float sx, float sy, float sz, int color,
                            float rotX, float rotY, float rotZ) {
        Matrix4f partModel = new Matrix4f(baseModel);

        // Position
        partModel.translate(ox, oy, oz);

        // Animation rotation
        if (rotX != 0) partModel.rotateX(rotX);
        if (rotY != 0) partModel.rotateY(rotY);
        if (rotZ != 0) partModel.rotateZ(rotZ);

        // Scale
        partModel.scale(sx, sy, sz);

        shader.setUniformMat4("model", partModel);
        shader.setUniform3f("mobTint", colorToVec3(color));

        // Use stone block as base texture (will be tinted)
        cube.render(atlas, BlockType.STONE, shader);
    }

    private Vector3f colorToVec3(int color) {
        return new Vector3f(
            ((color >> 16) & 0xFF) / 255.0f,
            ((color >> 8) & 0xFF) / 255.0f,
            (color & 0xFF) / 255.0f
        );
    }
}

