package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.rendering.model.BlockCube;
import com.voxelgame.world.BlockType;
import org.joml.Matrix4f;
import org.joml.Vector3f;

/**
 * Textured mob model that uses custom UV coordinates for each body part,
 * similar to how Minecraft renders mob textures.
 */
public class TexturedMobModel {

    public enum MobType {
        PIG, COW, SHEEP, CHICKEN, ZOMBIE, SKELETON, CREEPER, SPIDER
    }

    // UV coordinates for each part (in 16x16 texture space)
    private static class PartUV {
        float u, v, w, h;
        PartUV(float u, float v, float w, float h) {
            this.u = u; this.v = v; this.w = w; this.h = h;
        }
    }

    private final MobType type;
    private final float bodyW, bodyH, bodyD;
    private final float headSize;
    private final float legW, legH, legD;
    private final float armW, armH, armD;
    private final boolean isHumanoid;

    public final float width;
    public final float height;

    private TexturedMobModel(MobType type, float bw, float bh, float bd, float hs,
                             float lw, float lh, float ld, float aw, float ah, float ad,
                             boolean isHumanoid) {
        this.type = type;
        this.bodyW = bw; this.bodyH = bh; this.bodyD = bd;
        this.headSize = hs;
        this.legW = lw; this.legH = lh; this.legD = ld;
        this.armW = aw; this.armH = ah; this.armD = ad;
        this.isHumanoid = isHumanoid;
        this.width = Math.max(Math.max(bw, bd), hs) + 0.2f;
        this.height = lh + bh + hs;
    }

    public static TexturedMobModel create(MobType type) {
        return switch (type) {
            case PIG -> new TexturedMobModel(type, 0.7f, 0.6f, 1.0f, 0.6f, 0.25f, 0.4f, 0.25f, 0, 0, 0, false);
            case COW -> new TexturedMobModel(type, 0.8f, 0.8f, 1.2f, 0.6f, 0.3f, 0.5f, 0.3f, 0, 0, 0, false);
            case SHEEP -> new TexturedMobModel(type, 0.7f, 0.7f, 1.0f, 0.5f, 0.25f, 0.45f, 0.25f, 0, 0, 0, false);
            case CHICKEN -> new TexturedMobModel(type, 0.4f, 0.4f, 0.5f, 0.3f, 0.15f, 0.3f, 0.15f, 0, 0, 0, false);
            case ZOMBIE -> new TexturedMobModel(type, 0.6f, 0.9f, 0.3f, 0.5f, 0.25f, 0.9f, 0.25f, 0.2f, 0.9f, 0.2f, true);
            case SKELETON -> new TexturedMobModel(type, 0.5f, 0.9f, 0.25f, 0.45f, 0.2f, 0.9f, 0.2f, 0.15f, 0.9f, 0.15f, true);
            case CREEPER -> new TexturedMobModel(type, 0.5f, 1.0f, 0.35f, 0.5f, 0.25f, 0.6f, 0.25f, 0, 0, 0, false);
            case SPIDER -> new TexturedMobModel(type, 0.9f, 0.4f, 0.7f, 0.4f, 0.15f, 0.3f, 0.15f, 0, 0, 0, false);
        };
    }

    /**
     * Render the mob with proper Minecraft-like proportions.
     */
    public void render(Matrix4f view, Shader shader, TextureAtlas atlas, BlockCube cube,
                       float x, float y, float z, float yaw, float limbSwing, float limbSwingAmount) {
        Matrix4f baseModel = new Matrix4f();
        baseModel.translate(x, y, z);
        baseModel.rotateY((float) Math.toRadians(yaw));

        float swing = limbSwing * limbSwingAmount;

        // Select block type for textured rendering
        BlockType textureBlock = getTextureBlock();

        // === BODY ===
        renderBox(baseModel, shader, atlas, cube, textureBlock,
            0, legH + bodyH / 2, 0,  // position
            bodyW, bodyH, bodyD,      // size
            0, 0, 0);                 // rotation

        // === HEAD ===
        float headY = legH + bodyH;
        float headZ = isHumanoid ? 0 : bodyD / 2 - headSize / 2;
        renderBox(baseModel, shader, atlas, cube, textureBlock,
            0, headY, headZ,
            headSize, headSize, headSize,
            0, 0, 0);

        if (isHumanoid) {
            // === LEGS ===
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                -bodyW / 4, legH / 2, 0,
                legW, legH, legD,
                swing, 0, 0);
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                bodyW / 4, legH / 2, 0,
                legW, legH, legD,
                -swing, 0, 0);

            // === ARMS (extended forward like zombie) ===
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                -bodyW / 2 - armW / 2, legH + bodyH * 0.7f, -armD,
                armW, armH, armD,
                -swing * 0.8f, 0, 0);
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                bodyW / 2 + armW / 2, legH + bodyH * 0.7f, -armD,
                armW, armH, armD,
                swing * 0.8f, 0, 0);
        } else {
            // === 4 LEGS for animals ===
            float lx = bodyW / 2 - legW / 2;
            float lz = bodyD / 2 - legD / 2;

            renderBox(baseModel, shader, atlas, cube, textureBlock,
                -lx, legH / 2, -lz, legW, legH, legD, swing, 0, 0);
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                lx, legH / 2, -lz, legW, legH, legD, -swing, 0, 0);
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                -lx, legH / 2, lz, legW, legH, legD, -swing, 0, 0);
            renderBox(baseModel, shader, atlas, cube, textureBlock,
                lx, legH / 2, lz, legW, legH, legD, swing, 0, 0);
        }
    }

    private void renderBox(Matrix4f baseModel, Shader shader, TextureAtlas atlas,
                           BlockCube cube, BlockType block,
                           float ox, float oy, float oz,
                           float sx, float sy, float sz,
                           float rotX, float rotY, float rotZ) {
        Matrix4f model = new Matrix4f(baseModel);

        // Position (pivot at top of part for legs)
        model.translate(ox, oy, oz);

        // Rotation (for animation)
        if (rotX != 0) model.rotateX(rotX);
        if (rotY != 0) model.rotateY(rotY);
        if (rotZ != 0) model.rotateZ(rotZ);

        // Scale
        model.scale(sx, sy, sz);

        shader.setUniformMat4("model", partModel);

        // Render with appropriate tint for this mob type
        shader.setUniform3f("mobTint", getMobTint());
        cube.render(atlas, block, shader);
    }

    private Matrix4f partModel = new Matrix4f();

    private Vector3f getMobTint() {
        return switch (type) {
            case PIG -> new Vector3f(0.9f, 0.7f, 0.7f);
            case COW -> new Vector3f(0.4f, 0.3f, 0.2f);
            case SHEEP -> new Vector3f(0.95f, 0.95f, 0.95f);
            case CHICKEN -> new Vector3f(1.0f, 1.0f, 1.0f);
            case ZOMBIE -> new Vector3f(0.3f, 0.5f, 0.3f);
            case SKELETON -> new Vector3f(0.85f, 0.85f, 0.85f);
            case CREEPER -> new Vector3f(0.3f, 0.7f, 0.2f);
            case SPIDER -> new Vector3f(0.2f, 0.15f, 0.15f);
        };
    }

    private BlockType getTextureBlock() {
        // Use different blocks for different mob types for visual variety
        return switch (type) {
            case PIG -> BlockType.SAND;
            case COW -> BlockType.DIRT;
            case SHEEP -> BlockType.SNOW;
            case CHICKEN -> BlockType.SAND;
            case ZOMBIE -> BlockType.STONE;
            case SKELETON -> BlockType.WHITE_CONCRETE;
            case CREEPER -> BlockType.GRASS_BLOCK;
            case SPIDER -> BlockType.OBSIDIAN;
        };
    }
}

