                1.0f, 1.8f, 1.0f, 1.0f, 1.0f);

            case SHEEP -> new MobModel(type,
                new float[][] {
                    {0, 0.45f, 0.35f, 0.5f, 0.5f, 0.5f},     // head
                    {0, 0.45f, 0, 0.7f, 0.7f, 1.0f},          // body (wool)
