                0.9f, 1.6f, 1.0f, 1.0f, 1.0f);

            case CHICKEN -> new MobModel(type,
                new float[][] {
                    {0, 0.7f, 0.2f, 0.3f, 0.3f, 0.3f},      // head
                    {0, 0.3f, 0, 0.4f, 0.4f, 0.5f},           // body
