                    {-0.18f, 0, -0.12f, 0.25f, 0.6f, 0.25f}, // leg FL
                    {0.18f, 0, -0.12f, 0.25f, 0.6f, 0.25f},  // leg FR
                    {-0.18f, 0, 0.12f, 0.25f, 0.6f, 0.25f},  // leg BL
                    {0.18f, 0, 0.12f, 0.25f, 0.6f, 0.25f},   // leg BR
                },
                new int[][] {
                    {8, 8, 16, 16}, {24, 16, 16, 20},
                    {4, 32, 6, 16}, {4, 32, 6, 16}, {4, 32, 6, 16}, {4, 32, 6, 16}
                },
                0.7f, 2.2f, 1.0f, 1.0f, 1.0f);

            case SPIDER -> new MobModel(type,
                new float[][] {
                    {0, 0.4f, 0.2f, 0.4f, 0.3f, 0.3f},      // head
                    {0, 0.3f, 0, 0.9f, 0.4f, 0.7f},           // body
                    {-0.3f, 0.1f, -0.15f, 0.15f, 0.3f, 0.15f}, // leg FL
                    {0.3f, 0.1f, -0.15f, 0.15f, 0.3f, 0.15f},  // leg FR
                    {-0.3f, 0.1f, 0.15f, 0.15f, 0.3f, 0.15f},  // leg BL
                    {0.3f, 0.1f, 0.15f, 0.15f, 0.3f, 0.15f},   // leg BR
                },
                new int[][] {
                    {8, 14, 12, 10}, {16, 16, 20, 12},
                    {4, 8, 2, 12}, {4, 8, 2, 12}, {4, 8, 2, 12}, {4, 8, 2, 12}
                },
                1.1f, 0.7f, 1.0f, 1.0f, 1.0f);
        };
    }

    public void update(float limbSwing, float limbSwingAmount) {
        this.limbSwing = limbSwing;
        this.limbSwingAmount = limbSwingAmount;
    }

    /**
     * Render the mob model with textures.
     */
    public void render(Matrix4f view, Shader shader, MobMesh mesh,
                       float x, float y, float z, float yaw, int textureId) {
        Matrix4f baseModel = new Matrix4f();
        baseModel.translate(x, y, z);
        baseModel.rotateY((float) Math.toRadians(yaw));

        float swing = limbSwing * limbSwingAmount;

        // Render each part
        for (int i = 0; i < parts.length; i++) {
            float[] p = parts[i];
            int[] uv = partUVs[i];

            renderPart(baseModel, shader, mesh, p, uv, i, swing, textureId);
        }
    }

    private void renderPart(Matrix4f baseModel, Shader shader, MobMesh mesh,
                            float[] part, int[] uv, int partIndex, float swing, int textureId) {
        Matrix4f model = new Matrix4f(baseModel);

        float ox = part[0], oy = part[1], oz = part[2];
        float sx = part[3], sy = part[4], sz = part[5];

        // Position
        model.translate(ox, oy, oz);

        // Animation
        boolean isLeg = partIndex >= 2;
        if (isLeg && swing != 0) {
            float dir = (partIndex % 2 == 0) ? 1.0f : -1.0f;
            if (partIndex >= 4) dir *= -1;
            model.rotateX(swing * 0.6f * dir);
        }
        // Arms
        if (partIndex >= 4 && parts.length > 6 && swing != 0) {
            float dir = (partIndex % 2 == 0) ? -1.0f : 1.0f;
            model.rotateX(swing * 0.4f * dir);
        }

        // Scale
        model.scale(sx, sy, sz);

        shader.setUniformMat4("model", model);
        shader.setUniform3f("tint", tintR, tintG, tintB);

        // Build mesh with proper UVs
        mesh.buildBox(-0.5f, -0.5f, -0.5f, 1, 1, 1,
            uv[0], uv[1], uv[2], uv[3], 64, 64);

        // Bind texture
        glBindTexture(GL_TEXTURE_2D, textureId);

        mesh.render();
    }

    public float getWidth() { return width; }
    public float getHeight() { return height; }
}

package com.voxelgame.world.entity;

import com.voxelgame.rendering.Camera;
import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.world.BlockType;
import org.joml.Vector3f;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL13.*;

/**
 * Renders all mobs in the world using textured models.
 */
public class MobRenderer {

    private Shader shader;
    private MobMesh mesh;

    public MobRenderer() {
        shader = new Shader("shaders/mobmodel.vert", "shaders/mobmodel.frag");
        mesh = new MobMesh();

        // Generate mob textures
        MobTextures.generateAll();
    }

    public void render(java.util.List<Mob> mobs, Camera camera) {
        if (mobs.isEmpty()) return;

        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glDisable(GL_BLEND);

        shader.bind();
        shader.setUniformMat4("projection", camera.getProjectionMatrix());
        shader.setUniformMat4("view", camera.getViewMatrix());
        shader.setUniform1i("mobTexture", 0);

        glActiveTexture(GL_TEXTURE0);

        for (Mob mob : mobs) {
            renderMob(mob, camera);
        }

        shader.unbind();
    }

    private void renderMob(Mob mob, Camera camera) {
        MobModel model = getMobModel(mob.getType());
        Vector3f pos = mob.getPosition();

        // Calculate yaw
        float yaw = 0;
        if (mob.getVelocity().lengthSquared() > 0.01f) {
            yaw = (float) java.lang.Math.toDegrees(java.lang.Math.atan2(mob.getVelocity().x, mob.getVelocity().z));
        } else {
            Vector3f toPlayer = new Vector3f(camera.getPosition()).sub(pos);
            yaw = (float) java.lang.Math.toDegrees(java.lang.Math.atan2(toPlayer.x, toPlayer.z));
        }

        // Update animations
        model.update(mob.getLimbSwing(), mob.getLimbSwingAmount());

        // Get texture for this mob type
        int textureId = MobTextures.getTexture(model.getType());

        model.render(new org.joml.Matrix4f(), shader, mesh,
            pos.x, pos.y, pos.z, yaw, textureId);
    }

    private MobModel getMobModel(Mob.MobType type) {
        return switch (type) {
            case PIG -> MobModel.create(MobModel.MobType.PIG);
            case COW -> MobModel.create(MobModel.MobType.COW);
            case SHEEP -> MobModel.create(MobModel.MobType.SHEEP);
            case CHICKEN -> MobModel.create(MobModel.MobType.CHICKEN);
            case ZOMBIE -> MobModel.create(MobModel.MobType.ZOMBIE);
            case SKELETON -> MobModel.create(MobModel.MobType.SKELETON);
            case CREEPER -> MobModel.create(MobModel.MobType.CREEPER);
            case SPIDER -> MobModel.create(MobModel.MobType.SPIDER);
        };
    }

    public void cleanup() {
        shader.cleanup();
        mesh.cleanup();
        MobTextures.cleanup();
    }
}

