package com.voxelgame.world.entity;

import com.voxelgame.world.World;
import org.joml.Vector3f;

/**
 * Mob AI behaviors - makes mobs act like they do in Minecraft.
 */
public class MobAI {

    // AI States
    public enum State {
        IDLE,           // Standing still
        WANDERING,      // Walking randomly
        FLEEING,        // Running from player (after being hit)
        FOLLOWING,      // Following player (with food)
        ATTACKING,      // Chasing to attack player
        EXPLODING,      // Creeper about to explode
        SWIMMING,       // In water
    }

    // AI memory
    private State state = State.IDLE;
    private float stateTimer = 0;
    private float wanderTimer = 0;
    private float targetX, targetZ;
    private boolean hasTarget = false;
    private float fleeTimer = 0;
    private float attackCooldown = 0;

    // Animation
    private float limbSwing = 0;

    /**
     * Update mob AI.
     */
    public void update(Mob mob, World world, Vector3f playerPos, float dt) {
        stateTimer += dt;
        wanderTimer -= dt;
        attackCooldown -= dt;

        Vector3f pos = mob.getPosition();
        boolean isHostile = mob.getType().isHostile();

        // Distance to player
        float dx = playerPos.x - pos.x;
        float dz = playerPos.z - pos.z;
        float distToPlayer = (float) Math.sqrt(dx * dx + dz * dz);

        // Update state machine
        if (isHostile) {
            updateHostileAI(mob, world, playerPos, distToPlayer, dx, dz, dt);
        } else {
            updatePassiveAI(mob, world, playerPos, distToPlayer, dx, dz, dt);
        }

        // Update animation
        limbSwing += dt * (state == State.WANDERING || state == State.FLEEING ? 6.0f : 3.0f);
    }

    private void updateHostileAI(Mob mob, World world, Vector3f playerPos,
                                  float dist, float dx, float dz, float dt) {
        switch (mob.getType()) {
            case ZOMBIE -> {
                // Zombie: slow, persistent chase
                if (dist < 20.0f) {
                    state = State.ATTACKING;
                    faceAndMove(mob, dx, dz, dist, 2.0f);
                    // Attack when close
                    if (dist < 2.0f && attackCooldown <= 0) {
                        // Deal damage to player (handled elsewhere)
                        attackCooldown = 1.0f;
                    }
                } else {
                    wander(mob, world, dt);
                }
            }
            case SKELETON -> {
                // Skeleton: keep distance, shoot
                if (dist < 15.0f) {
                    state = State.ATTACKING;
                    // Strafe around player
                    float strafeAngle = (float) Math.atan2(dz, dx) + (float) Math.PI / 2;
                    mob.setHorizontalVelocity(
                        (float) Math.cos(strafeAngle) * 1.5f,
                        (float) Math.sin(strafeAngle) * 1.5f
                    );
                    // Shoot arrow (handled elsewhere)
                    if (dist > 5.0f && attackCooldown <= 0) {
                        attackCooldown = 2.0f;
                    }
                } else {
                    wander(mob, world, dt);
                }
            }
            case CREEPER -> {
                // Creeper: approach silently, then explode
                if (dist < 10.0f) {
                    state = State.ATTACKING;
                    faceAndMove(mob, dx, dz, dist, 2.5f);
                    // Start hissing/exploding when very close
                    if (dist < 3.0f) {
                        state = State.EXPLODING;
                        // Explosion handled elsewhere
                    }
                } else {
                    wander(mob, world, dt);
                }
            }
            case SPIDER -> {
                // Spider: fast, climbs walls, attacks at night
                if (dist < 12.0f || world.isNight()) {
                    state = State.ATTACKING;
                    faceAndMove(mob, dx, dz, dist, 3.0f);
                    if (dist < 2.0f && attackCooldown <= 0) {
                        attackCooldown = 0.8f;
                    }
                } else {
                    wander(mob, world, dt);
                }
            }
        }
    }

    private void updatePassiveAI(Mob mob, World world, Vector3f playerPos,
                                  float dist, float dx, float dz, float dt) {
        // Check if recently hit (fleeing)
        if (state == State.FLEEING && fleeTimer > 0) {
            fleeTimer -= dt;
            // Run away from player
            mob.setHorizontalVelocity(-dx / dist * 3.0f, -dz / dist * 3.0f);
            if (fleeTimer <= 0) {
                state = State.IDLE;
            }
        } else {
            // Normal passive behavior
            if (wanderTimer <= 0) {
                // Pick new wander target
                targetX = mob.getPosition().x + (float) (Math.random() - 0.5) * 10;
                targetZ = mob.getPosition().z + (float) (Math.random() - 0.5) * 10;
                wanderTimer = 4.0f + (float) Math.random() * 6.0f;
                state = State.WANDERING;
            }

            if (state == State.WANDERING) {
                float tx = targetX - mob.getPosition().x;
                float tz = targetZ - mob.getPosition().z;
                float distTarget = (float) Math.sqrt(tx * tx + tz * tz);
                if (distTarget < 0.5f) {
                    state = State.IDLE;
                    mob.setHorizontalVelocity(0, 0);
                } else {
                    mob.setHorizontalVelocity(tx / distTarget * 2.0f, tz / distTarget * 2.0f);
                }
            }
        }
    }

    private void faceAndMove(Mob mob, float dx, float dz, float dist, float speed) {
        mob.setHorizontalVelocity(dx / dist * speed, dz / dist * speed);
    }

    private void wander(Mob mob, World world, float dt) {
        if (!hasTarget || wanderTimer <= 0) {
            targetX = mob.getPosition().x + (float) (Math.random() - 0.5) * 15;
            targetZ = mob.getPosition().z + (float) (Math.random() - 0.5) * 15;
            hasTarget = true;
            wanderTimer = 3.0f + (float) Math.random() * 5.0f;
            state = State.WANDERING;
        }

        float tx = targetX - mob.getPosition().x;
        float tz = targetZ - mob.getPosition().z;
        float distTarget = (float) Math.sqrt(tx * tx + tz * tz);

        if (distTarget < 0.5f) {
            hasTarget = false;
            state = State.IDLE;
            mob.setHorizontalVelocity(0, 0);
        } else {
            mob.setHorizontalVelocity(tx / distTarget * 1.5f, tz / distTarget * 1.5f);
        }
    }

    /**
     * Called when mob is hit by player.
     */
    public void onHit(Mob mob) {
        state = State.FLEEING;
        fleeTimer = 1.5f + (float) Math.random(); // Flee for 1.5-2.5 seconds
        wanderTimer = 0;
        hasTarget = false;
    }

    /**
     * Get current limb swing for animation.
     */
    public float getLimbSwing() { return limbSwing; }

    /**
     * Get current animation amount (0-1 based on speed).
     */
    public float getLimbSwingAmount() {
        return (state == State.WANDERING || state == State.FLEEING || state == State.ATTACKING) ? 1.0f : 0.3f;
    }
}

