                new Part(0.06f, 0.55f, 0.4f, 0.06f, 0.06f, 0.04f, 1.0f, 0.0f, 0.0f),
                // Body
                new Part(0, 0.3f, 0, 0.9f, 0.4f, 0.7f, 0.23f, 0.15f, 0.12f),
                // Abdomen
                new Part(0, 0.35f, -0.4f, 0.6f, 0.3f, 0.4f, 0.15f, 0.1f, 0.08f),
                // Legs (8 legs)
                new Part(-0.35f, 0.15f, -0.2f, 0.12f, 0.3f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(0.35f, 0.15f, -0.2f, 0.12f, 0.3f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(-0.4f, 0.15f, 0, 0.12f, 0.35f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(0.4f, 0.15f, 0, 0.12f, 0.35f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(-0.35f, 0.15f, 0.2f, 0.12f, 0.3f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(0.35f, 0.15f, 0.2f, 0.12f, 0.3f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(-0.3f, 0.15f, 0.4f, 0.12f, 0.25f, 0.12f, 0.18f, 0.12f, 0.1f),
                new Part(0.3f, 0.15f, 0.4f, 0.12f, 0.25f, 0.12f, 0.18f, 0.12f, 0.1f),
            }, 1.1f, 0.75f);
        };
    }

    /**
     * Render the mob model.
     */
    public void render(Matrix4f view, Shader shader, TextureAtlas atlas, BlockCube cube,
                       float x, float y, float z, float yaw, float limbSwing, float limbSwingAmount) {
        Matrix4f baseModel = new Matrix4f();
        baseModel.translate(x, y, z);
        baseModel.rotateY((float) Math.toRadians(yaw));

        float swing = limbSwing * limbSwingAmount;

        // Render each part
        for (int i = 0; i < parts.length; i++) {
            Part p = parts[i];
            renderPart(baseModel, shader, atlas, cube, p, i, swing);
        }
    }

    private void renderPart(Matrix4f baseModel, Shader shader, TextureAtlas atlas,
                            BlockCube cube, Part p, int index, float swing) {
        Matrix4f model = new Matrix4f(baseModel);

        // Position
        model.translate(p.ox, p.oy, p.oz);

        // Animation for legs (index 5+ for animals, 8+ for humanoids)
        boolean isLeg = isLegPart(index);
        if (isLeg && swing != 0) {
            float dir = (index % 2 == 0) ? 1.0f : -1.0f;
            if (index >= 8) dir *= -1; // Back legs opposite
            model.rotateX(swing * 0.6f * dir);
        }

        // Arms swing
        boolean isArm = isArmPart(index);
        if (isArm && swing != 0) {
            float dir = (index % 2 == 0) ? -1.0f : 1.0f;
            model.rotateX(swing * 0.5f * dir);
        }

        // Scale
        model.scale(p.sx, p.sy, p.sz);

        shader.setUniformMat4("model", model);
        shader.setUniform3f("mobTint", new Vector3f(p.r, p.g, p.b));

        // Use stone as base (will be tinted)
        cube.render(atlas, BlockType.STONE, shader);
    }

    private boolean isLegPart(int index) {
        // Legs come after head/body parts
        if (type == MobType.PIG || type == MobType.COW || type == MobType.SHEEP) {
            return index >= 5; // head + body parts first
        } else if (type == MobType.CHICKEN) {
            return index >= 7;
        } else if (type == MobType.CREEPER) {
            return index >= 8;
        } else if (type == MobType.SPIDER) {
            return index >= 8;
        } else { // ZOMBIE, SKELETON
            return index >= 9;
        }
    }

    private boolean isArmPart(int index) {
        if (type == MobType.ZOMBIE) return index >= 5 && index <= 8;
        if (type == MobType.SKELETON) return index >= 3 && index <= 4;
        return false;
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.rendering.Camera;
import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.rendering.model.BlockCube;
import org.joml.Vector3f;

import static org.lwjgl.opengl.GL11.*;

/**
 * Renders all mobs in the world using colored part models.
 */
public class MobRenderer {

    private Shader shader;
    private BlockCube cube;
    private TextureAtlas atlas;

    public MobRenderer(TextureAtlas atlas) {
        shader = new Shader("shaders/mobmodel.vert", "shaders/mobmodel.frag");
        cube = new BlockCube();
        this.atlas = atlas;
    }

    public void render(java.util.List<Mob> mobs, Camera camera) {
        if (mobs.isEmpty()) return;

        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glDisable(GL_BLEND);

        shader.bind();
        shader.setUniformMat4("projection", camera.getProjectionMatrix());
        shader.setUniformMat4("view", camera.getViewMatrix());

        for (Mob mob : mobs) {
            renderMob(mob, camera);
        }

        shader.unbind();
    }

    private void renderMob(Mob mob, Camera camera) {
        MobModel model = getMobModel(mob.getType());
        Vector3f pos = mob.getPosition();

        // Calculate yaw
        float yaw = 0;
        if (mob.getVelocity().lengthSquared() > 0.01f) {
            yaw = (float) java.lang.Math.toDegrees(java.lang.Math.atan2(mob.getVelocity().x, mob.getVelocity().z));
        } else {
            Vector3f toPlayer = new Vector3f(camera.getPosition()).sub(pos);
            yaw = (float) java.lang.Math.toDegrees(java.lang.Math.atan2(toPlayer.x, toPlayer.z));
        }

        model.render(new org.joml.Matrix4f(), shader, atlas, cube,
            pos.x, pos.y, pos.z, yaw, mob.getLimbSwing(), mob.getLimbSwingAmount());
    }

    private MobModel getMobModel(Mob.MobType type) {
        return switch (type) {
            case PIG -> MobModel.create(MobModel.MobType.PIG);
            case COW -> MobModel.create(MobModel.MobType.COW);
            case SHEEP -> MobModel.create(MobModel.MobType.SHEEP);
            case CHICKEN -> MobModel.create(MobModel.MobType.CHICKEN);
            case ZOMBIE -> MobModel.create(MobModel.MobType.ZOMBIE);
            case SKELETON -> MobModel.create(MobModel.MobType.SKELETON);
            case CREEPER -> MobModel.create(MobModel.MobType.CREEPER);
            case SPIDER -> MobModel.create(MobModel.MobType.SPIDER);
        };
    }

    public void cleanup() {
        shader.cleanup();
        cube.cleanup();
    }
}

package com.voxelgame.world.entity;

import org.lwjgl.system.MemoryUtil;

import java.nio.FloatBuffer;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL15.*;
import static org.lwjgl.opengl.GL20.*;
import static org.lwjgl.opengl.GL30.*;

/**
 * A textured box mesh for mob body parts.
 * Each face can have custom UV coordinates for texture atlases.
 * Vertex format: x, y, z, u, v, shade, r, g, b (9 floats)
 */
public class MobMesh {

    private static final int VERTEX_SIZE = 9; // x,y,z,u,v,shade,r,g,b
    private static final int VERTEX_COUNT = 36; // 6 faces * 2 triangles * 3 vertices

    private int vao;
    private int vbo;
    private boolean built = false;

    public MobMesh() {
        vao = glGenVertexArrays();
        vbo = glGenBuffers();

        glBindVertexArray(vao);
        glBindBuffer(GL_ARRAY_BUFFER, vbo);

        int stride = VERTEX_SIZE * Float.BYTES;
        glVertexAttribPointer(0, 3, GL_FLOAT, false, stride, 0); // position
        glEnableVertexAttribArray(0);
        glVertexAttribPointer(1, 2, GL_FLOAT, false, stride, 3 * Float.BYTES); // uv
        glEnableVertexAttribArray(1);
        glVertexAttribPointer(2, 1, GL_FLOAT, false, stride, 5 * Float.BYTES); // shade
        glEnableVertexAttribArray(2);
        glVertexAttribPointer(3, 3, GL_FLOAT, false, stride, 6 * Float.BYTES); // color
        glEnableVertexAttribArray(3);

        glBindVertexArray(0);
        built = true;
    }

    /**
     * Build a box with specific UV region and color.
     *
     * @param ox,oy,oz - center offset
     * @param sx,sy,sz - size
     * @param u0,v0 - top-left UV
     * @param u1,v1 - bottom-right UV
     * @param r,g,b - color tint
     */
    public void buildBox(float ox, float oy, float oz,
                        float sx, float sy, float sz,
                        float u0, float v0, float u1, float v1,
                        float r, float g, float b) {
        FloatBuffer buf = MemoryUtil.memAllocFloat(VERTEX_COUNT * VERTEX_SIZE);

        float x0 = ox - sx / 2, x1 = ox + sx / 2;
        float y0 = oy - sy / 2, y1 = oy + sy / 2;
        float z0 = oz - sz / 2, z1 = oz + sz / 2;

        // Front face (+Z)
        addQuad(buf, x0,y0,z1, x1,y0,z1, x1,y1,z1, x0,y1,z1, u0,v0,u1,v1, 0.85f, r,g,b);
        // Back face (-Z)
        addQuad(buf, x1,y0,z0, x0,y0,z0, x0,y1,z0, x1,y1,z0, u0,v0,u1,v1, 0.75f, r,g,b);
        // Top face (+Y)
        addQuad(buf, x0,y1,z1, x1,y1,z1, x1,y1,z0, x0,y1,z0, u0,v0,u1,v1, 1.0f, r,g,b);
        // Bottom face (-Y)
        addQuad(buf, x0,y0,z0, x1,y0,z0, x1,y0,z1, x0,y0,z1, u0,v0,u1,v1, 0.5f, r,g,b);
        // Right face (+X)
        addQuad(buf, x1,y0,z1, x1,y0,z0, x1,y1,z0, x1,y1,z1, u0,v0,u1,v1, 0.8f, r,g,b);
        // Left face (-X)
        addQuad(buf, x0,y0,z0, x0,y0,z1, x0,y1,z1, x0,y1,z0, u0,v0,u1,v1, 0.7f, r,g,b);

        buf.flip();

        glBindBuffer(GL_ARRAY_BUFFER, vbo);
        glBufferData(GL_ARRAY_BUFFER, buf, GL_DYNAMIC_DRAW);
        MemoryUtil.memFree(buf);
    }

    private void addQuad(FloatBuffer b,
                         float x1, float y1, float z1,
                         float x2, float y2, float z2,
                         float x3, float y3, float z3,
                         float x4, float y4, float z4,
                         float u0, float v0, float u1, float v1,
                         float shade, float r, float g, float bl) {
        // Triangle 1
        b.put(x1).put(y1).put(z1).put(u0).put(v0).put(shade).put(r).put(g).put(bl);
        b.put(x2).put(y2).put(z2).put(u1).put(v0).put(shade).put(r).put(g).put(bl);
        b.put(x3).put(y3).put(z3).put(u1).put(v1).put(shade).put(r).put(g).put(bl);
        // Triangle 2
        b.put(x1).put(y1).put(z1).put(u0).put(v0).put(shade).put(r).put(g).put(bl);
        b.put(x3).put(y3).put(z3).put(u1).put(v1).put(shade).put(r).put(g).put(bl);
        b.put(x4).put(y4).put(z4).put(u0).put(v1).put(shade).put(r).put(g).put(bl);
    }

    public void render() {
        if (!built) return;
        glBindVertexArray(vao);
        glDrawArrays(GL_TRIANGLES, 0, VERTEX_COUNT);
        glBindVertexArray(0);
    }

    public void cleanup() {
        glDeleteBuffers(vbo);
        glDeleteVertexArrays(vao);
    }
}

