        // Spawn passive mobs during day
        for (int i = 0; i < 5; i++) {
            float x = playerPos.x + (float) (java.lang.Math.random() - 0.5) * 30;
            float z = playerPos.z + (float) (java.lang.Math.random() - 0.5) * 30;
            int groundY = getGroundHeight((int) x, (int) z);
