package com.voxelgame.chat;

import java.util.ArrayList;
import java.util.List;

/**
 * Manages the chat input buffer, cursor position, command history, and the
 * message tape (recent messages that fade out over time).
 */
public class ChatManager {

    private static final int MAX_BUFFER = 100;
    private static final int MAX_HISTORY = 50;
    private static final int TAPE_SIZE = 12;
    private static final float MESSAGE_LIFETIME = 10.0f;
    private static final float FADE_DURATION = 2.0f;

    // Input buffer
    private final StringBuilder buffer = new StringBuilder();
    private int cursor = 0;

    // Command history (most recent at end)
    private final List<String> history = new ArrayList<>();
    private int historyIndex = -1;

    // Message tape
    private final List<Message> tape = new ArrayList<>();

    // State
    private boolean open = false;

    /** A single message in the tape. */
    private static class Message {
        String text;
        int color;
        float age = 0;

        Message(String text, int color) {
            this.text = text;
            this.color = color;
        }
    }

    // ------------------------------------------------------------------
    // Open / close
    // ------------------------------------------------------------------

    /** Open chat. If prefix is not null, it is pre-inserted into the buffer. */
    public void open(String prefix) {
        open = true;
        buffer.setLength(0);
        cursor = 0;
        if (prefix != null) {
            buffer.append(prefix);
            cursor = prefix.length();
        }
        historyIndex = -1;
    }

    public void close() {
        open = false;
    }

    public boolean isOpen() {
        return open;
    }

    // ------------------------------------------------------------------
    // Input handling
    // ------------------------------------------------------------------

    /** Insert a Unicode character at the cursor. */
    public void charTyped(char c) {
        if (buffer.length() >= MAX_BUFFER) return;
        if (cursor < 0) cursor = 0;
        if (cursor > buffer.length()) cursor = buffer.length();
        buffer.insert(cursor, c);
        cursor++;
    }

    /** Backspace deletes the character before the cursor. */
    public void backspace() {
        if (cursor > 0 && cursor <= buffer.length()) {
            buffer.deleteCharAt(cursor - 1);
            cursor--;
        }
    }

    /** Delete key removes the character at the cursor. */
    public void delete() {
        if (cursor < buffer.length()) {
            buffer.deleteCharAt(cursor);
        }
    }

    public void moveCursorLeft() {
        if (cursor > 0) cursor--;
    }

    public void moveCursorRight() {
        if (cursor < buffer.length()) cursor++;
    }

    public void moveCursorHome() {
        cursor = 0;
    }

    public void moveCursorEnd() {
        cursor = buffer.length();
    }

    /** Navigate history: -1 = older, +1 = newer. */
    public void historyNavigate(int dir) {
        if (history.isEmpty()) return;
        if (historyIndex == -1) {
            historyIndex = history.size() + dir;
        } else {
            historyIndex += dir;
        }
        if (historyIndex < 0) historyIndex = 0;
        if (historyIndex >= history.size()) {
            historyIndex = -1;
            buffer.setLength(0);
            cursor = 0;
            return;
        }
        buffer.setLength(0);
        buffer.append(history.get(historyIndex));
        cursor = buffer.length();
    }

    /** Paste text from clipboard into buffer at cursor. */
    public void paste(String text) {
        if (text == null) return;
        for (char c : text.toCharArray()) {
            if (buffer.length() >= MAX_BUFFER) break;
            if (c >= 32) {
                buffer.insert(cursor, c);
                cursor++;
            }
        }
    }

    // ------------------------------------------------------------------
    // Send / command processing
    // ------------------------------------------------------------------

    /**
     * Send the current buffer. Adds to history, processes as command or chat
     * message, then clears the buffer.
     *
     * @return true if the chat should stay open (never), false to close
     */
    public boolean send() {
        String text = buffer.toString().trim();
        if (text.isEmpty()) {
            buffer.setLength(0);
            cursor = 0;
            return false;
        }

        // Add to history
        history.add(text);
        if (history.size() > MAX_HISTORY) {
            history.remove(0);
        }

        // Echo to tape
        addMessage("<" + "Player" + "> " + text, 0xFFFFFFFF);

        // Process command
        if (text.startsWith("/")) {
            String result = CommandRegistry.execute(text);
            if (result != null) {
                addMessage(result, 0xFFFFAA00);
            }
        }

        buffer.setLength(0);
        cursor = 0;
        return false;
    }

    // ------------------------------------------------------------------
    // Message tape
    // ------------------------------------------------------------------

    /** Add a message to the tape (system messages, command results, etc). */
    public void addMessage(String text, int color) {
        tape.add(new Message(text, color));
        while (tape.size() > TAPE_SIZE) {
            tape.remove(0);
        }
    }

    /** Update message ages. Removes expired messages. */
    public void update(float dt) {
        tape.removeIf(m -> {
            m.age += dt;
            return m.age >= MESSAGE_LIFETIME;
        });
    }

    /**
     * Render the message tape and input line.
     *
     * @param ui     the UIRenderer
     * @param font   the FontRenderer
     * @param width  screen width in GUI pixels
     * @param height screen height in GUI pixels
     * @param time   current time for cursor blink
     */
    public void render(com.voxelgame.ui.UIRenderer ui, com.voxelgame.ui.FontRenderer font,
                       float width, float height, float time) {
        float lineHeight = 9;
        float inputHeight = 12;
        float tapeTop = height - inputHeight - 4;

        // --- Message tape (bottom to top) ---
        float y = tapeTop - lineHeight;
        for (int i = tape.size() - 1; i >= 0; i--) {
            Message m = tape.get(i);
            float alpha = 1.0f;
            float remaining = MESSAGE_LIFETIME - m.age;
            if (remaining < FADE_DURATION) {
                alpha = Math.max(0, remaining / FADE_DURATION);
            }
            if (alpha <= 0) continue;

            int color = m.color;
            int a = (int) (alpha * 255);
            int argb = (a << 24) | (color & 0xFFFFFF);

            // Background
            int bgAlpha = (int) (alpha * 128);
            ui.fillRect(4, y - 1, font.width(m.text) + 4, lineHeight, (bgAlpha << 24));

            font.draw(ui, m.text, 6, y, argb);
            y -= lineHeight;
        }

        // --- Input line ---
        if (open) {
            // Background bar
            ui.fillRect(0, height - inputHeight, width, inputHeight, 0x80000000);

            String display = "> " + buffer.toString();
            font.draw(ui, display, 4, height - inputHeight + 2, 0xFFFFFFFF);

            // Cursor (blink period ~0.5s)
            boolean cursorVisible = ((int) (time * 2)) % 2 == 0;
            if (cursorVisible) {
                int cx = 4 + font.width("> " + buffer.substring(0, cursor));
                ui.fillRect(cx, height - inputHeight + 2, 1, lineHeight, 0xFFFFFFFF);
            }
        }
    }

    // --- Getters ---
    public String getBuffer() { return buffer.toString(); }
    public int getCursor() { return cursor; }
}

package com.voxelgame.chat;

import com.voxelgame.chat.commands.Command;

import java.util.HashMap;
import java.util.Map;

/**
 * Registry for chat commands. Commands register themselves by name and are
 * dispatched via {@link #execute(String)}.
 */
public class CommandRegistry {

    private static final Map<String, Command> commands = new HashMap<>();

    /** Register a command. */
    public static void register(Command cmd) {
        commands.put(cmd.getName().toLowerCase(), cmd);
    }

    /**
     * Execute a command line (including the leading '/').
     *
     * @param input full command line e.g. "/spawn zoloy 10 20 30"
     * @return result message to display, or null for silent success
     */
    public static String execute(String input) {
        if (input == null || !input.startsWith("/")) return null;

        String[] parts = input.substring(1).trim().split("\\s+");
        if (parts.length == 0 || parts[0].isEmpty()) {
            return "Неизвестная команда. Введите /help";
        }

        String name = parts[0].toLowerCase();
        Command cmd = commands.get(name);
        if (cmd == null) {
            return "Неизвестная команда '" + name + "'. Введите /help";
        }

        String[] args;
        if (parts.length > 1) {
            args = new String[parts.length - 1];
            System.arraycopy(parts, 1, args, 0, parts.length - 1);
        } else {
            args = new String[0];
        }

        try {
            return cmd.execute(args);
        } catch (IllegalArgumentException e) {
            return "Ошибка: " + e.getMessage() + "\nИспользование: " + cmd.getUsage();
        } catch (Exception e) {
            return "Ошибка выполнения: " + e.getMessage();
        }
    }

    /** Get all registered commands (for /help). */
    public static Map<String, Command> getCommands() {
        return commands;
    }
}

package com.voxelgame.chat.commands;

/**
 * Base interface for chat commands.
 */
public interface Command {

    /** Command name without '/' (e.g. "spawn"). */
    String getName();

    /** Usage string e.g. "/spawn <mob> [count] [x y z]". */
    String getUsage();

    /** Short description for /help. */
    String getDescription();

    /**
     * Execute the command.
     *
     * @param args arguments after the command name
     * @return message to display (or null for silent)
     * @throws IllegalArgumentException if arguments are invalid
     */
    String execute(String[] args);
}

package com.voxelgame.chat.commands;

import com.voxelgame.chat.CommandRegistry;

import java.util.Map;

/**
 * /help — list all registered commands with descriptions.
 */
public class HelpCommand implements Command {

    @Override
    public String getName() {
        return "help";
    }

    @Override
    public String getUsage() {
        return "/help";
    }

    @Override
    public String getDescription() {
        return "показать список команд";
    }

    @Override
    public String execute(String[] args) {
        StringBuilder sb = new StringBuilder();
        sb.append("--- Команды ---\n");
        for (Map.Entry<String, Command> e : CommandRegistry.getCommands().entrySet()) {
            sb.append(e.getValue().getUsage()).append(" — ")
              .append(e.getValue().getDescription()).append("\n");
        }
        // Remove trailing newline
        return sb.toString().trim();
    }
}

package com.voxelgame.chat.commands;

import com.voxelgame.world.World;
import com.voxelgame.world.entity.Zoloy;
import org.joml.Vector3f;

import java.util.HashMap;
import java.util.Map;

/**
 * /spawn <mob> [count] [x y z] — spawn mobs.
 *
 * Without coordinates: 3 blocks in front of the player on the ground.
 * With coordinates: at the specified position.
 * Count: how many to spawn (1-10).
 *
 * Currently supported mob: zoloy
 */
public class SpawnCommand implements Command {

    /** Mob name → factory. */
    private interface MobFactory {
        Zoloy create(World world, float x, float y, float z);
    }

    private static final Map<String, MobFactory> MOBS = new HashMap<>();

    // Access to the current world — set by game initialization
    static World currentWorld;
    static Vector3f currentPlayerPos;
    static Vector3f currentPlayerFront;

    static {
        MOBS.put("zoloy", Zoloy::new);
    }

    @Override
    public String getName() {
        return "spawn";
    }

    @Override
    public String getUsage() {
        return "/spawn <mob> [count] [x y z]";
    }

    @Override
    public String getDescription() {
        return "призвать моба (zoloy)";
    }

    @Override
    public String execute(String[] args) {
        if (args.length < 1) {
            throw new IllegalArgumentException("укажи тип моба");
        }

        String mobName = args[0].toLowerCase();
        MobFactory factory = MOBS.get(mobName);
        if (factory == null) {
            throw new IllegalArgumentException("неизвестный моб '" + mobName + "'");
        }

        int count = 1;
        Float x = null, y = null, z = null;

        // Parse: [count] [x y z]
        if (args.length >= 2) {
            // Second arg could be count or x coordinate
            if (isNumber(args[1]) && args.length >= 4) {
                // args[1..3] are x y z
                x = parseCoord(args[1], currentPlayerPos.x);
                y = parseCoord(args[2], currentPlayerPos.y);
                z = parseCoord(args[3], currentPlayerPos.z);
            } else if (isInteger(args[1])) {
                count = parseInt(args[1]);
                if (args.length >= 5) {
                    x = parseCoord(args[2], currentPlayerPos.x);
                    y = parseCoord(args[3], currentPlayerPos.y);
                    z = parseCoord(args[4], currentPlayerPos.z);
                }
            } else {
                throw new IllegalArgumentException("неправильный аргумент: " + args[1]);
            }
        }

        // Clamp count
        if (count < 1) count = 1;
        if (count > 10) count = 10;

        // Determine spawn position
        if (x == null) {
            // 3 blocks in front of player
            x = currentPlayerPos.x + currentPlayerFront.x * 3.0f;
            z = currentPlayerPos.z + currentPlayerFront.z * 3.0f;
        }
        if (y == null) {
            y = currentPlayerPos.y;
        }

        // Find ground
        if (currentWorld != null) {
            int groundY = currentWorld.getGroundHeight((int) x, (int) z);
            if (groundY > 0) {
                y = groundY;
            }
        }

        // Spawn
        if (currentWorld != null) {
            for (int i = 0; i < count; i++) {
                float ox = x + (float) (Math.random() - 0.5) * 0.5f;
                float oz = z + (float) (Math.random() - 0.5) * 0.5f;
                currentWorld.getMobs().add(factory.create(currentWorld, ox, y + 0.01f, oz));
            }
        }

        return mobName + " заспавнен в (" + fmt(x) + ", " + fmt(y) + ", " + fmt(z) + ")";
    }

    private static String fmt(float v) {
        if (v == (int) v) return String.valueOf((int) v);
        return String.format("%.2f", v);
    }

    private static boolean isNumber(String s) {
        try {
            Float.parseFloat(s.replace('~', '0'));
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private static boolean isInteger(String s) {
        try {
            Integer.parseInt(s);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private static int parseInt(String s) {
        return Integer.parseInt(s);
    }

    /**
     * Parse a coordinate. Supports '~' relative to player: ~ = player pos,
     * ~5 = player pos + 5.
     */
    private static float parseCoord(String s, float playerCoord) {
        if (s.startsWith("~")) {
            if (s.length() == 1) return playerCoord;
            return playerCoord + Float.parseFloat(s.substring(1));
        }
        return Float.parseFloat(s);
    }
}

