package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.model.ModelBox;
import org.joml.Matrix4f;

/**
 * Zoloy — vanilla humanoid model (ModelBiped equivalent).
 *
 * Spec: Y points DOWN in model space, origin (0,0,0) = neck.
 * ModelBox uses Y UP, so we negate Y from spec coordinates.
 *
 * Verification table (spec → ModelBox):
 *   head: spec(-4,-8,-4)-(4,0,4) → box(-4,0,-4), 8x8x8
 *   body: spec(-4,0,-2)-(4,12,2)  → box(-4,0,-2), 8x12x4
 *   rArm: spec(-7,0,-2)-(-3,12,2) → box(-7,0,-2), 4x12x4
 *   lArm: spec(3,0,-2)-(7,12,2)   → box(3,0,-2), 4x12x4
 *   rLeg: spec(-5.9,12,-2)-(-1.9,24,2) → box(-5.9,12,-2), 4x12x4
 *   lLeg: spec(1.9,12,-2)-(5.9,24,2)   → box(1.9,12,-2), 4x12x4
 */
public class ZoloyModel {

    private final ModelBox head;
    private final ModelBox body;
    private final ModelBox rarm;
    private final ModelBox larm;
    private final ModelBox rleg;
    private final ModelBox lleg;
    private final ModelBox cloak;

    // Base posture
    private static final float BASE_BODY = 0.35f;
    private static final float BASE_RARM = 0.25f;
    private static final float BASE_LARM = 0.25f;
    private static final float BASE_HEAD = -0.15f;

    private final Matrix4f scratch = new Matrix4f();

    public ZoloyModel() {
        // Head: pivot(0,0,0), spec box(-4,-8,-4)-(4,0,4) → ModelBox(-4,0,-4), 8x8x8
        head = new ModelBox(0, 0, 8, 8, 8, -4, 0, -4);

        // Body: pivot(0,0,0), spec box(-4,0,-2)-(4,12,2) → ModelBox(-4,0,-2), 8x12x4
        body = new ModelBox(16, 16, 8, 12, 4, -4, 0, -2);

        // Right arm: pivot(-5,2,0), spec box(-7,0,-2)-(-3,12,2) → ModelBox(-7,0,-2), 4x12x4
        rarm = new ModelBox(40, 16, 4, 12, 4, -7, 0, -2);

        // Left arm: pivot(5,2,0), spec box(3,0,-2)-(7,12,2) → ModelBox(3,0,-2), 4x12x4
        larm = new ModelBox(32, 48, 4, 12, 4, 3, 0, -2);

        // Right leg: pivot(-1.9,12,0), spec box(-5.9,12,-2)-(-1.9,24,2)
        rleg = new ModelBox(0, 16, 4, 12, 4, -5.9f, 12, -2);

        // Left leg: pivot(1.9,12,0), spec box(1.9,12,-2)-(5.9,24,2)
        lleg = new ModelBox(16, 48, 4, 12, 4, 1.9f, 12, -2);

        // Cloak: overlay expanded 0.5px, behind body
        cloak = new ModelBox(16, 28, 8, 12, 4, -4.5f, -0.5f, -2.5f, 0.5f);
    }

    private void renderPart(ModelBox part, float rotX, Matrix4f base,
                           Matrix4f viewProj, Shader shader) {
        scratch.identity();
        scratch.rotateX(rotX);

        Matrix4f mvp = viewProj.mul(base, new Matrix4f()).mul(scratch);
        shader.setUniformMat4("mvp", mvp);
        part.render();
    }

    public void render(Matrix4f base, Matrix4f viewProj, Shader shader,
                       float limbSwing, float limbSwingAmount,
                       float attackPhase, boolean debugTpose) {

        float a = limbSwingAmount;

        float rLegRot = (float) Math.cos(limbSwing * 0.6662f) * 1.4f * a;
        float lLegRot = (float) Math.cos(limbSwing * 0.6662f + Math.PI) * 1.4f * a;
        float rArmRot = (float) Math.cos(limbSwing * 0.6662f + Math.PI) * 1.0f * a;
        float lArmRot = (float) Math.cos(limbSwing * 0.6662f) * 1.0f * a;

        if (attackPhase > 0f) {
            float arc = (float) Math.sin(attackPhase * Math.PI);
            rArmRot = -2.2f + 2.8f * arc;
        }

        if (debugTpose) {
            rLegRot = lLegRot = rArmRot = lArmRot = 0;
        }

        // Render all parts with base matrix (pivots baked into box origins)
        renderPart(rleg, rLegRot, base, viewProj, shader);
        renderPart(lleg, lLegRot, base, viewProj, shader);
        renderPart(body, debugTpose ? 0 : BASE_BODY, base, viewProj, shader);
        renderPart(rarm, (debugTpose ? 0 : BASE_RARM) + rArmRot, base, viewProj, shader);
        renderPart(larm, (debugTpose ? 0 : BASE_LARM) + lArmRot, base, viewProj, shader);
        renderPart(head, debugTpose ? 0 : BASE_HEAD, base, viewProj, shader);
        renderPart(cloak, debugTpose ? 0 : BASE_BODY * 0.5f, base, viewProj, shader);
    }

    public void cleanup() {
        head.cleanup();
        body.cleanup();
        rarm.cleanup();
        larm.cleanup();
        rleg.cleanup();
        lleg.cleanup();
        cloak.cleanup();
    }
}

package com.voxelgame.world.entity;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.model.ModelBox;
import org.joml.Matrix4f;

/**
 * Zoloy — vanilla humanoid model (ModelBiped).
 *
 * Model space: Y DOWN, origin = neck. World space: Y UP.
 * Base matrix includes Y-flip to convert between spaces.
 * Pivots per part (vanilla style). Culling disabled (spec).
 */
public class ZoloyModel {

    private final ModelBox head;
    private final ModelBox body;
    private final ModelBox rarm;
    private final ModelBox larm;
    private final ModelBox rleg;
    private final ModelBox lleg;
    private final ModelBox cloak;

    // Pivots in model space (Y down) — spec values
    private static final float[] P_HEAD = {0, 0, 0};
    private static final float[] P_BODY = {0, 0, 0};
    private static final float[] P_RARM = {-5, 2, 0};
    private static final float[] P_LARM = {5, 2, 0};
    private static final float[] P_RLEG = {-1.9f, 12, 0};
    private static final float[] P_LLEG = {1.9f, 12, 0};
    private static final float[] P_CLOAK = {0, 2, 0};

    // Base posture
    private static final float BASE_BODY = 0.35f;
    private static final float BASE_RARM = 0.25f;
    private static final float BASE_LARM = 0.25f;
    private static final float BASE_HEAD = -0.15f;

    private final Matrix4f scratch = new Matrix4f();

    public ZoloyModel() {
        // Boxes: ModelBox(u, v, w, h, d, minX, minY, minZ)
        // Converting from spec (Y down) to ModelBox (Y up) by negating Y
        // Spec head: (-4,-8,-4)-(4,0,4) → box origin(-4,0,-4), size(8,8,8)
        head  = new ModelBox(0, 0, 8, 8, 8, -4, 0, -4);
        body  = new ModelBox(16, 16, 8, 12, 4, -4, 0, -2);
        rarm  = new ModelBox(40, 16, 4, 12, 4, -7, 0, -2);
        larm  = new ModelBox(32, 48, 4, 12, 4, 3, 0, -2);
        rleg  = new ModelBox(0, 16, 4, 12, 4, -5.9f, 12, -2);
        lleg  = new ModelBox(16, 48, 4, 12, 4, 1.9f, 12, -2);
        cloak = new ModelBox(16, 28, 8, 12, 4, -4.5f, -0.5f, -2.5f, 0.5f);
    }

    /**
     * Render part with pivot rotation.
     * pivot in model space (Y down), rotX in radians.
     * Due to Y-flip in base matrix, negate rotX for correct direction.
     */
    private void renderPart(ModelBox part, float[] pivot, float rotX,
                           Matrix4f base, Matrix4f viewProj, Shader shader) {
        // Pivot transform: T(pivot) * Rx(rotX) * T(-pivot)
        // Note: pivot Y is negated because base already flips Y
        scratch.identity();
        scratch.translate(pivot[0], -pivot[1], pivot[2]);
        scratch.rotateX(-rotX); // negate due to Y-flip
        scratch.translate(-pivot[0], pivot[1], -pivot[2]);

        Matrix4f mvp = viewProj.mul(base, new Matrix4f()).mul(scratch);
        shader.setUniformMat4("mvp", mvp);
        part.render();
    }

    public void render(Matrix4f base, Matrix4f viewProj, Shader shader,
                       float limbSwing, float limbSwingAmount,
                       float attackPhase, boolean debugTpose) {

        float a = limbSwingAmount;

        // Vanilla formulas
        float rLegRot = (float) Math.cos(limbSwing * 0.6662f) * 1.4f * a;
        float lLegRot = (float) Math.cos(limbSwing * 0.6662f + Math.PI) * 1.4f * a;
        float rArmRot = (float) Math.cos(limbSwing * 0.6662f + Math.PI) * 1.0f * a;
        float lArmRot = (float) Math.cos(limbSwing * 0.6662f) * 1.0f * a;

        if (attackPhase > 0f) {
            rArmRot = -2.2f + 2.8f * (float) Math.sin(attackPhase * Math.PI);
        }

        if (debugTpose) {
            rLegRot = lLegRot = rArmRot = lArmRot = 0;
        }

        renderPart(rleg, P_RLEG, rLegRot, base, viewProj, shader);
        renderPart(lleg, P_LLEG, lLegRot, base, viewProj, shader);
        renderPart(body, P_BODY, debugTpose ? 0 : BASE_BODY, base, viewProj, shader);
        renderPart(rarm, P_RARM, (debugTpose ? 0 : BASE_RARM) + rArmRot, base, viewProj, shader);
        renderPart(larm, P_LARM, (debugTpose ? 0 : BASE_LARM) + lArmRot, base, viewProj, shader);
        renderPart(head, P_HEAD, debugTpose ? 0 : BASE_HEAD, base, viewProj, shader);
        renderPart(cloak, P_CLOAK, debugTpose ? 0 : BASE_BODY * 0.5f, base, viewProj, shader);
    }

    public void cleanup() {
        head.cleanup();
        body.cleanup();
        rarm.cleanup();
        larm.cleanup();
        rleg.cleanup();
        lleg.cleanup();
        cloak.cleanup();
    }
}

