package com.voxelgame.ui;

import com.voxelgame.rendering.Shader;
import com.voxelgame.rendering.TextureAtlas;
import com.voxelgame.rendering.model.BlockCube;
import com.voxelgame.world.BlockType;
import org.joml.Matrix4f;

import static org.lwjgl.opengl.GL11.*;
import static org.lwjgl.opengl.GL13.*;

/**
 * Renders block items in inventory as small 3D cubes (like Minecraft).
 * Uses an orthographic projection so cubes look correct in GUI space.
 */
public class InventoryItemRenderer {

    private static final Shader shader = new Shader("shaders/heldblock.vert", "shaders/heldblock.frag");
    private static final BlockCube cube = new BlockCube();
    private static final Matrix4f mvp = new Matrix4f();

    /**
     * Render a block as a 3D cube at screen position (x, y) with given size.
     *
     * @param atlas  block texture atlas
     * @param block  the block type to render
     * @param x      screen X (top-left)
     * @param y      screen Y (top-left)
     * @param size   width/height in pixels
     * @param daylight light level 0..1
     */
    public static void render(TextureAtlas atlas, BlockType block, float x, float y, float size, float daylight) {
        if (block == null || block == BlockType.AIR) return;

        float scale = size / 20f; // normalize so ~20px slot = unit cube

        // Orthographic projection matching UIRenderer: origin top-left, Y down
        // We render the cube centered at (x + size/2, y + size/2)
        float cx = x + size * 0.5f;
        float cy = y + size * 0.5f;

        // Build model matrix: translate to screen center, rotate for isometric look, scale
        mvp.identity();
        // Convert screen coords to normalized -1..1 range centered
        // For GUI we use a simple perspective trick: move cube back and project
        float dist = 2.5f; // camera distance

        // Simple ortho-like projection: scale to fit, offset from center
        float screenScale = scale * 1.6f; // visual size factor

        // Rotation for isometric view
        Matrix4f model = new Matrix4f()
            .translate(cx, cy, 0)
            .rotateX(-0.5f)              // tilt down
            .rotateY(0.8f)               // rotate to show 3 faces
            .scale(screenScale);

        // Simple perspective projection
        float fov = 1.2f; // field of view control
        Matrix4f proj = new Matrix4f().setPerspective(fov, 1f, 0.1f, 100f);
        Matrix4f view = new Matrix4f().translate(0, 0, -dist);

        mvp.set(proj).mul(view).mul(model);

        shader.bind();
        shader.setUniformMat4("projection", new Matrix4f().setPerspective(fov, 1f, 0.1f, 100f));
        shader.setUniformMat4("view", new Matrix4f().translate(0, 0, -dist));
        shader.setUniformMat4("model", model);
        shader.setUniform1i("blockTextures", 0);
        shader.setUniform1f("lightLevel", 0.6f + 0.4f * daylight);
        shader.setUniform3f("sunColor", new org.joml.Vector3f(1f, 1f, 1f));

        glActiveTexture(GL_TEXTURE0);
        atlas.bindArray();

        glEnable(GL_DEPTH_TEST);
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glFrontFace(GL_CCW);

        cube.render(atlas, block, shader);

        glDisable(GL_DEPTH_TEST);
        glDisable(GL_CULL_FACE);

        shader.unbind();
        atlas.unbindArray();
    }

    public static void cleanup() {
        shader.cleanup();
        cube.cleanup();
