/**
 * Surface height for a column. Blends the biome's own profile with the
 * shared fBm field so neighbouring biomes meet smoothly instead of on a
 * cliff, then carves rivers.
 */
public int getHeight(int x, int z) {
    // Use MC 1.18+ noise for terrain
    double c = biomeNoise.C(x, z);
    double e = biomeNoise.E(x, z);
    double pv = biomeNoise.PV(x, z);
    double w = biomeNoise.W(x, z);
    double t = biomeNoise.T(x, z);

    // Check for river (simplified: low PV + mid continentalness)
    boolean isRiver = pv < -0.3 && c > 0.3 && c < 0.6;

    int height = BiomeHeightGenerator.getHeight(c, e, pv, w, isRiver);

    // Add detail noise for variation
    double detail = heightNoise.fbm(x, z, 4, 0.01, 0.5);
    double eNorm = e;
    double hillAmp = 8 * (1 - eNorm) + 2;
    height += (int) (detail * hillAmp);

    // Desert dunes
    BiomeSelector.MCBiome biome = getMCBiome(x, z);
    if (biome == BiomeSelector.MCBiome.DESERT) {
        double dune = Math.sin(x * 0.1) * Math.cos(z * 0.1) * 3;
        height += (int) dune;
    }

    // Badlands terraces
    if (biome == BiomeSelector.MCBiome.BADLANDS || biome == BiomeSelector.MCBiome.WOODED_BADLANDS) {
        double terrace = Math.sin(height * 0.3) * 4;
        height += (int) terrace;
    }

    // Volcanic: cone-shaped mountains with crater
    if (biome == BiomeSelector.MCBiome.VOLCANO) {
        double dist = Math.sqrt((x % 256 - 128) * (x % 256 - 128) + (z % 256 - 128) * (z % 256 - 128));
        double cone = Math.max(0, 40 - dist * 0.8);
        height += (int) cone;
        // Crater depression at center
        if (dist < 15) {
            height -= (int) ((15 - dist) * 1.5);
        }
    }

    // Glacier: smooth ice caps — round off terrain
    if (biome == BiomeSelector.MCBiome.GLACIER) {
        double iceSmooth = heightNoise.fbm(x, z, 3, 0.005, 0.5) * 6;
        height = (int) (height * 0.7 + (height + iceSmooth) * 0.3);
    }

    // Crystal peaks: tall basalt pillars
    if (biome == BiomeSelector.MCBiome.CRYSTAL_PEAKS) {
        double pillar = Math.abs(Math.sin(x * 0.05) * Math.cos(z * 0.05)) * 20;
        height += (int) pillar;
    }

    // Beach smoothing: gradually lower terrain near sea level for natural shores
    if (height >= SEA_LEVEL - 3 && height <= SEA_LEVEL + 4) {
        double beachBlend = 1.0 - Math.abs(height - SEA_LEVEL) / 4.0;
        beachBlend = Math.max(0, Math.min(1, beachBlend));
        // Pull height toward sea level for gentle beach slopes
        height = (int) Math.round(height * (1 - beachBlend * 0.4) + SEA_LEVEL * beachBlend * 0.4);
    }

    // Clamp
    return Math.max(4, Math.min(Chunk.HEIGHT - 40, height));
}

