package com.voxelgame.world.structure;

import com.voxelgame.world.BlockType;
import com.voxelgame.world.Chunk;
import com.voxelgame.world.generator.TerrainGenerator;
import com.voxelgame.world.biome.BiomeSelector;

/**
 * Generates structures in the world.
 * Structures are placed deterministically based on chunk position and seed.
 * Each chunk checks a set of candidate positions for valid structure placements.
 */
public class StructureGenerator {

    private final long seed;
    private final TerrainGenerator terrainGenerator;

    /** Minimum distance between structures of the same type (in chunks) */
    private static final int MIN_SPACING = 3;

    /** Maximum structures per chunk */
    private static final int MAX_PER_CHUNK = 2;

    public StructureGenerator(long seed, TerrainGenerator terrainGenerator) {
        this.seed = seed;
        this.terrainGenerator = terrainGenerator;
    }

    /**
     * Generate structures for a chunk.
     * Called after terrain generation.
     */
    public void generate(Chunk chunk, java.util.Map<Long, Chunk> neighborChunks) {
        int cx = chunk.getChunkX();
        int cz = chunk.getChunkZ();

        // Check if structures are enabled (via terrain generator's flag)
        if (!terrainGenerator.isStructuresEnabled()) return;

        int placed = 0;

        // Try a few candidate positions in this chunk
        for (int i = 0; i < 3 && placed < MAX_PER_CHUNK; i++) {
            // Deterministic candidate position
            long hash = hashPos(cx, cz, i);
            int lx = (int) ((hash & 0xF) - 8) + 8; // 0..15
            int lz = (int) (((hash >> 4) & 0xF) - 8) + 8; // 0..15
            int wx = cx * Chunk.SIZE + lx;
            int wz = cz * Chunk.SIZE + lz;

            // Pick structure type based on biome and hash
            BiomeSelector.MCBiome biome = terrainGenerator.getMCBiome(wx, wz);
