package com.voxelgame.ui.screen;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.widget.Button;

import java.util.Random;

import static com.voxelgame.core.Language.tr;

/**
 * Main menu for your own game.
 *
 * Replace TITLE, SUBTITLE, COPYRIGHT, splash texts and colors
 * with your own game identity.
 */
public class MainMenuScreen extends Screen {

    public interface Callbacks {
        void onSingleplayer();
        void onOptions();
        void onLanguage();
        void onQuit();
        String versionString();
    }

    // TODO: replace with your own game name.
    private static final String TITLE = "YOUR GAME";

    // TODO: optional subtitle under the logo.
    private static final String SUBTITLE = "voxel adventure";

    // TODO: replace with your own studio/name.
    private static final String COPYRIGHT = "\u00A9 2026 Your Studio";

    private final Callbacks callbacks;
    private final String splashKey;
    private double time = 0;

    public MainMenuScreen(Callbacks callbacks) {
        this.callbacks = callbacks;

        // Splash lines still live in language files, but they should be yours.
        this.splashKey = "splash." + (1 + new Random().nextInt(6));
    }

    @Override
    public boolean rendersWorld() {
        return true;
    }

    /** Signals to Game that the orbit camera should drive the view. */
    public boolean usesPanorama() {
        return true;
    }

    @Override
    public boolean closableWithEscape() {
        return false;
    }

    @Override
    protected void layout() {
        int bw = 220;
        int bh = 22;
        int spacing = 26;

        int cx = (width - bw) / 2;
        int startY = Math.max(height / 2 - 20, 96);

        add(new Button(cx, startY, bw, bh, tr("menu.singleplayer"),
                b -> callbacks.onSingleplayer()));

        // If multiplayer is not ready yet, you can remove this button completely.
        // A disabled button is fine for prototypes, but for a cleaner menu
        // you may prefer to hide it until the feature exists.
        Button multiplayer = add(new Button(cx, startY + spacing, bw, bh,
                tr("menu.multiplayer"), b -> {}));
        multiplayer.enabled = false;

        add(new Button(cx, startY + spacing * 2, bw, bh, tr("menu.options"),
                b -> callbacks.onOptions()));

        add(new Button(cx, startY + spacing * 3, bw, bh, tr("menu.quit"),
                b -> callbacks.onQuit()));

        // Language button.
        // Later it is better to replace "L" with a proper globe icon texture.
        add(new Button(cx + bw + 6, startY + spacing * 2, 24, bh, "L",
                b -> callbacks.onLanguage()));
    }

    @Override
    public void update(double deltaTime) {
        time += deltaTime;
    }

    @Override
    protected void renderBackground(UIRenderer ui, FontRenderer font, GuiAssets tex) {
        // Slightly different color tone from the original version.
        ui.fillRect(0, 0, width, height, 0x7A10141C);

        int bandTop = Math.max(height / 2 - 30, 86);
        int bandHeight = 4 * 26 + 18;

        ui.fillRect(0, bandTop, width, bandHeight, 0x48000000);
        ui.fillRect(0, height - 18, width, 18, 0x60000000);
    }

    @Override
    protected void renderForeground(UIRenderer ui, FontRenderer font, GuiAssets tex,
                                    float mx, float my) {
        drawTitle(ui, font);
        drawSplash(ui, font);

        font.drawWithShadow(ui, callbacks.versionString(),
                2, height - FontRenderer.GLYPH_H - 3, 0xFFDDE5EE);

        font.drawRight(ui, COPYRIGHT,
                width - 2, height - FontRenderer.GLYPH_H - 3, 0xFFA8B0B8);
    }

    /** Main game title. Later you can replace this with a logo texture. */
    private void drawTitle(UIRenderer ui, FontRenderer font) {
        int scale = 3;
        int w = font.scaledWidth(TITLE, scale);
        float x = (width - w) / 2.0f;
        float y = Math.max(18, height / 2.0f - 88);

        font.drawScaledWithShadow(ui, TITLE, x, y, scale, 0xFFF2F6FF);

        if (!SUBTITLE.isEmpty()) {
            int subScale = 1;
            int sw = font.scaledWidth(SUBTITLE, subScale);
            float sx = (width - sw) / 2.0f;
            float sy = y + scale * FontRenderer.GLYPH_H + 6;

            font.drawScaledWithShadow(ui, SUBTITLE, sx, sy, subScale, 0xFF9FC6E8);
        }
    }

    /**
     * Splash text.
     *
     * This is still a pulsing line near the title, but the color,
     * angle and animation strength are different.
     *
     * If you want to be even more original, remove this completely
     * or replace it with a static "news line" / "tip line".
     */
    private void drawSplash(UIRenderer ui, FontRenderer font) {
        String splash = tr(splashKey);

        // If translation is missing, do not draw raw key text.
        if (splash == null || splash.isEmpty() || splash.equals(splashKey)) {
            return;
        }

        float pulse = 1.0f + 0.05f * (float) Math.abs(Math.sin(time * 2.2));
        int scale = Math.max(1, Math.round(pulse * 1.2f));

        int titleW = font.scaledWidth(TITLE, 3);
        float baseX = (width + titleW) / 2.0f - 24;
        float baseY = Math.max(18, height / 2.0f - 88) + 34;

        // Smaller tilt than before.
        final float rise = -0.18f;

        float penX = baseX - font.scaledWidth(splash, scale) * 0.5f;
        float penY = baseY;

        for (int i = 0; i < splash.length(); i++) {
            char c = splash.charAt(i);
            String s = String.valueOf(c);
            float advance = (font.charWidth(c) + 1) * scale;

            // Shadow.
            font.drawScaled(ui, s, penX + 1, penY + 1, scale, 0xFF173042);

            // Main splash color: cyan instead of yellow.
            font.drawScaled(ui, s, penX, penY, scale, 0xFF7EE0FF);

            penX += advance;
            penY += advance * rise;
        }
    }
}

