package com.voxelgame.ui.screen;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.widget.Button;
import com.voxelgame.ui.widget.Widget;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import static com.voxelgame.core.Language.tr;

public class MainMenuScreen extends Screen {

    public interface Callbacks {
        void onSingleplayer();
        void onOptions();
        void onLanguage();
        void onQuit();
        String versionString();
    }

    private static final String TITLE = "VOXELCRAFT";
    private static final String SUBTITLE = "VOXEL ENGINE";
    private static final String STUDIO = "VOXEL STUDIOS";
    private static final String COPYRIGHT = "\u00A9 2026 Voxel Studios";

    private static final int BACKGROUND_TOP = 0xFF05060F;
    private static final int BACKGROUND_BOTTOM = 0xFF120826;
    private static final int TEXT_PRIMARY = 0xFFFFFFFF;
    private static final int TEXT_SECONDARY = 0xFF9AA8CC;
    private static final int TEXT_DIM = 0xFF55607A;
    private static final int GLOW_COLOR = 0xFF00FFFF;

    private static final float ANIM_DURATION = 0.7f;
    private static final float ANIM_STAGGER = 0.12f;

    private static final String[] GLOBE = {
            "..######..",
            ".#..##..#.",
            "#...##...#",
            "#...##...#",
            "##########",
            "#...##...#",
            "#...##...#",
            ".#..##..#.",
            "..######..",
    };

    private final Callbacks callbacks;
    private double time = 0;
    private final List<Particle> particles = new ArrayList<>();
    private final Random rnd = new Random(42);
    private float[] buttonAnimProgress;
    private Button langButton;

    private static class Particle {
        float x, y, vx, vy, size, alpha, tw, phase;
        int color;
        Particle(float x, float y, float vx, float vy, float size, int color, float alpha, float tw, float phase) {
            this.x = x; this.y = y; this.vx = vx; this.vy = vy;
            this.size = size; this.color = color; this.alpha = alpha;
            this.tw = tw; this.phase = phase;
        }
    }

    public MainMenuScreen(Callbacks callbacks) {
        this.callbacks = callbacks;
    }

    @Override public boolean rendersWorld() { return false; }
    @Override public boolean closableWithEscape() { return false; }

    private static String label(String key, String fallback) {
        String s = tr(key);
        return (s == null || s.isEmpty()) ? fallback : s;
    }

    @Override
    protected void layout() {
        int bw = 260, bh = 32, spacing = 42;
        int cx = (width - bw) / 2;
        int startY = height / 2 + 30;
        widgets.clear();

        Button sp = add(new Button(cx, startY, bw, bh,
                label("menu.singleplayer", "Singleplayer"), b -> callbacks.onSingleplayer()));
        sp.animDelay = 0;

        Button opts = add(new Button(cx, startY + spacing, bw, bh,
                label("menu.options", "Options"), b -> callbacks.onOptions()));
        opts.animDelay = ANIM_STAGGER;

        Button quit = add(new Button(cx, startY + spacing * 2, bw, bh,
                label("menu.quit", "Quit"), b -> callbacks.onQuit()));
        quit.animDelay = ANIM_STAGGER * 2;

        langButton = add(new Button(width - 36, height - 36, 26, 26,
                "", b -> callbacks.onLanguage()));
        langButton.animDelay = ANIM_STAGGER * 3;

        buttonAnimProgress = new float[widgets.size()];
        initParticles();
    }

    private void initParticles() {
        particles.clear();
        for (int i = 0; i < 90; i++) {
            float x = rnd.nextFloat() * width;
            float y = rnd.nextFloat() * height;
            float vx = (rnd.nextFloat() - 0.5f) * 6;
            float vy = (rnd.nextFloat() - 0.5f) * 4 - 1.5f;
            float size = 1 + rnd.nextFloat() * 2;
            float r = rnd.nextFloat();
            int color = r > 0.8f ? 0x00FFFF : (r > 0.5f ? 0x4477CC : 0xAACCFF);
            float alpha = 0.15f + rnd.nextFloat() * 0.5f;
            particles.add(new Particle(x, y, vx, vy, size, color, alpha,
                    1 + rnd.nextFloat() * 3, rnd.nextFloat() * 6.28f));
        }
    }

    @Override
    public void update(double deltaTime) {
        time += deltaTime;
        for (int i = 0; i < buttonAnimProgress.length && i < widgets.size(); i++) {
            if (widgets.get(i) instanceof Button btn) {
                float t = (float) (time - btn.animDelay);
                float progress = Math.max(0, Math.min(1, t / ANIM_DURATION));
                buttonAnimProgress[i] = easeOutCubic(progress);
            }
        }
        for (Particle p : particles) {
            p.x += p.vx * (float) deltaTime * 20;
            p.y += p.vy * (float) deltaTime * 20;
            if (p.x < -10) p.x = width + 10;
            if (p.x > width + 10) p.x = -10;
            if (p.y < -10) p.y = height + 10;
            if (p.y > height + 10) p.y = -10;
        }
    }

    private float easeOutCubic(float t) {
        return 1.0f - (float) Math.pow(1.0f - t, 3);
    }

    @Override
    protected void renderBackground(UIRenderer ui, FontRenderer font, GuiAssets tex) {
        ui.fillGradientV(0, 0, width, height, BACKGROUND_TOP, BACKGROUND_BOTTOM);
        drawHorizonGlow(ui, (int) (height / 2f - 100));
        drawGrid(ui);
        for (Particle p : particles) {
            float twinkle = 0.55f + 0.45f * (float) Math.sin(time * p.tw + p.phase);
            int a = (int) (p.alpha * twinkle * 255);
            ui.drawParticle(p.x, p.y, p.size, (a << 24) | (p.color & 0xFFFFFF));
        }
        drawVignette(ui);
    }

    private void drawHorizonGlow(UIRenderer ui, int cy) {
        int range = 140;
        for (int i = 0; i < range; i += 4) {
            float f = 1 - i / (float) range;
            int a = (int) (f * f * 26);
            int c = (a << 24) | 0x00AAFF;
            ui.fillRect(0, cy - i - 4, width, 4, c);
            ui.fillRect(0, cy + i, width, 4, c);
        }
    }

    private void drawGrid(UIRenderer ui) {
        int cell = 48;
        int a = 5 + (int) (3 * (0.5 + 0.5 * Math.sin(time * 0.7)));
        int c = (a << 24) | GLOW_COLOR;
        for (int x = cell; x < width; x += cell) ui.fillRect(x, 0, 1, height, c);
        for (int y = cell; y < height; y += cell) ui.fillRect(0, y, width, 1, c);
    }

    private void drawVignette(UIRenderer ui) {
        int band = 8, range = 160;
        for (int i = 0; i < range; i += band) {
            float f = 1 - i / (float) range;
            ui.fillRect(0, i, width, band, (int) (f * f * 110) << 24);
            ui.fillRect(0, height - i - band, width, band, (int) (f * f * 110) << 24);
            ui.fillRect(i, 0, band, height, (int) (f * f * 90) << 24);
            ui.fillRect(width - i - band, 0, band, height, (int) (f * f * 90) << 24);
        }
    }

    @Override
    protected void renderForeground(UIRenderer ui, FontRenderer font, GuiAssets tex,
                                    float mx, float my) {
        drawStudioBadge(ui, font);
        drawLogo(ui, font);

        for (int i = 0; i < widgets.size(); i++) {
            Widget w = widgets.get(i);
            float pr = buttonAnimProgress[i];
            w.y = (int) (w.baseY + (1f - pr) * 30);
            w.alpha = (int) (pr * 255) << 24;
            w.updateHover(mx, my);
            w.render(ui, font, tex, mx, my);

            boolean hov = pr >= 1f && mx >= w.x && mx < w.x + w.width
                    && my >= w.y && my < w.y + w.height;

            if (i < 3) {
                int a = (int) (pr * 255) << 24;
                int ty = w.y + (w.height - FontRenderer.GLYPH_H) / 2;
                font.drawWithShadow(ui, String.format("%02d", i + 1), w.x - 28, ty,
                        a | (hov ? GLOW_COLOR : 0x55607A));
                if (hov) {
                    ui.fillRect(w.x - 8, w.y + 5, 3, w.height - 10, 0xFF00FFFF);
                    ui.fillRect(w.x - 12, w.y + 8, 2, w.height - 16, 0x5500FFFF);
                    font.drawWithShadow(ui, ">", w.x + w.width - 14, ty, 0xFF00FFFF);
                }
            }
            if (w == langButton) drawGlobe(ui, langButton, hov, pr);
        }

        int by = height - FontRenderer.GLYPH_H - 6;
        font.drawWithShadow(ui, callbacks.versionString(), 6, by, TEXT_DIM);
        int cw = font.scaledWidth(COPYRIGHT, 1);
        font.drawWithShadow(ui, COPYRIGHT, width - 48 - cw, by, TEXT_DIM);
    }

    private void drawStudioBadge(UIRenderer ui, FontRenderer font) {
        ui.fillRect(8, 11, 5, 5, 0xFF00FFFF);
        ui.fillRect(11, 14, 5, 5, 0x8800FFFF);
        drawSpaced(ui, font, STUDIO, 22, 10, 1, 2, TEXT_DIM);
    }

    private void drawLogo(UIRenderer ui, FontRenderer font) {
        float pulse = 0.6f + 0.4f * (float) Math.sin(time * 2.0);
        int scale = 4;
        float x = (width - font.scaledWidth(TITLE, scale)) / 2f;
        float y = Math.max(24, height / 2f - 130) + (float) Math.sin(time * 1.3) * 2;

        int glowBase = (int) (50 + 40 * pulse);
        for (int i = 5; i > 0; i--) {
            int glow = ((glowBase / i) << 24) | GLOW_COLOR;
            font.drawScaled(ui, TITLE, x - i, y, scale, glow);
            font.drawScaled(ui, TITLE, x + i, y, scale, glow);
            font.drawScaled(ui, TITLE, x, y - i, scale, glow);
            font.drawScaled(ui, TITLE, x, y + i, scale, glow);
        }
        font.drawScaledWithShadow(ui, TITLE, x, y, scale, TEXT_PRIMARY);

        int extra = 3;
        int subW = spacedWidth(font, SUBTITLE, 1, extra);
        float sx = (width - subW) / 2f;
        float sy = y + scale * FontRenderer.GLYPH_H + 10;
        drawSpaced(ui, font, SUBTITLE, sx, sy, 1, extra, TEXT_SECONDARY);

        float lineW = Math.max(220, subW + 60);
        float lineX = (width - lineW) / 2f;
        float lineY = sy + FontRenderer.GLYPH_H + 8;
        ui.fillRect(lineX, lineY, lineW, 1, 0x5500FFFF);
        float span = lineW + 60;
        float pos = (float) ((time * 160) % span) - 30;
        float s0 = Math.max(lineX, lineX + pos);
        float s1 = Math.min(lineX + lineW, lineX + pos + 26);
        if (s1 > s0) ui.fillRect(s0, lineY, s1 - s0, 1, 0xDD00FFFF);
        ui.fillRect(lineX - 2, lineY - 1, 2, 3, 0xAA00FFFF);
        ui.fillRect(lineX + lineW, lineY - 1, 2, 3, 0xAA00FFFF);
    }

    private void drawGlobe(UIRenderer ui, Button b, boolean hov, float pr) {
        int px = 2;
        int ox = b.x + (b.width - GLOBE[0].length() * px) / 2;
        int oy = b.y + (b.height - GLOBE.length * px) / 2;
        int color = ((int) (pr * 255) << 24) | (hov ? 0x00FFFF : 0xBBD4EE);
        for (int r = 0; r < GLOBE.length; r++) {
            String row = GLOBE[r];
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == '#') ui.fillRect(ox + c * px, oy + r * px, px, px, color);
            }
        }
    }

    private int spacedWidth(FontRenderer font, String text, int scale, int extra) {
        int w = -extra;
        for (int i = 0; i < text.length(); i++) {
            w += font.scaledWidth(String.valueOf(text.charAt(i)), scale) + extra;
        }
        return w;
    }

    private void drawSpaced(UIRenderer ui, FontRenderer font, String text,
                            float x, float y, int scale, int extra, int color) {
        float cx = x;
        for (int i = 0; i < text.length(); i++) {
            String ch = String.valueOf(text.charAt(i));
            font.drawScaled(ui, ch, cx, y, scale, color);
            cx += font.scaledWidth(ch, scale) + extra;
        }
    }
}

package com.voxelgame.ui.widget;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.GuiAssets;

public class Button extends Widget {

    public interface Action {
        void onPress(Button source);
    }

    private String label;
    private final Action action;

    private static final int TEXT_NORMAL = 0xFFE0E0E0;
    private static final int TEXT_HOVER = 0xFFFFFFFF;
    private static final int TEXT_DISABLED = 0xFF666666;

    private static final int BUTTON_FILL_NORMAL = 0x22FFFFFF;
    private static final int BUTTON_FILL_HOVER = 0x4400FFFF;
    private static final int BUTTON_BORDER_NORMAL = 0x66FFFFFF;
    private static final int BUTTON_BORDER_HOVER = 0xFF00FFFF;
    private static final int GLOW_COLOR = 0xFF00FFFF;

    public Button(int x, int y, int width, int height, String label, Action action) {
        super(x, y, width, height);
        this.label = label;
        this.action = action;
    }

    public void setLabel(String label) { this.label = label; }
    public String getLabel() { return label; }

    private float hoverProgress = 0;
    private float scaleProgress = 1.0f;

    @Override
    public void update(double deltaTime) {
        float target = hovered ? 1.0f : 0.0f;
        hoverProgress += (target - hoverProgress) * (float) Math.min(1.0, deltaTime * 12);
        scaleProgress += ((1.0f + hoverProgress * 0.03f) - scaleProgress) * (float) Math.min(1.0, deltaTime * 10);
    }

    @Override
    public void render(UIRenderer ui, FontRenderer font, GuiAssets tex, float mx, float my) {
        if (!visible) return;

        int fadeAlpha = (alpha >>> 24) & 0xFF;

        if (!enabled) {
            int a = (int) (fadeAlpha / 255.0f * 0x11);
            ui.fillRoundedRect(x, y, width, height, 5, (a << 24) | 0xFFFFFF);
            ui.drawNeonBorder(x, y, width, height, (int) (fadeAlpha / 255.0f * 0x33) << 24 | 0x333333);
            font.drawCenteredWithShadow(ui, label,
                    x + width / 2.0f, y + (height - FontRenderer.GLYPH_H) / 2.0f,
                    (int) (fadeAlpha / 255.0f * 0x66) << 24 | 0x666666);
            return;
        }

        float centerX = x + width / 2.0f;
        float centerY = y + height / 2.0f;
        float scaledW = width * scaleProgress;
        float scaledH = height * scaleProgress;
        float drawX = centerX - scaledW / 2;
        float drawY = centerY - scaledH / 2;

        if (hoverProgress > 0.01f) {
            float glowIntensity = hoverProgress * (0.7f + 0.3f * (float) Math.sin(System.currentTimeMillis() * 0.003));
            ui.drawGlow(drawX, drawY, scaledW, scaledH, GLOW_COLOR, glowIntensity * fadeAlpha / 255.0f);
        }

        int bgFill = lerpColor(BUTTON_FILL_NORMAL, BUTTON_FILL_HOVER, hoverProgress);
        int borderCol = lerpColor(BUTTON_BORDER_NORMAL, BUTTON_BORDER_HOVER, hoverProgress);

        bgFill = (int) ((bgFill >>> 24) / 255.0f * fadeAlpha) << 24 | (bgFill & 0xFFFFFF);
        borderCol = (int) ((borderCol >>> 24) / 255.0f * fadeAlpha) << 24 | (borderCol & 0xFFFFFF);

        ui.fillRoundedRect(drawX, drawY, scaledW, scaledH, 5, bgFill);
        ui.drawNeonBorder(drawX, drawY, scaledW, scaledH, borderCol);

        int textColor = lerpColor(TEXT_NORMAL, TEXT_HOVER, hoverProgress);
        textColor = (int) ((textColor >>> 24) / 255.0f * fadeAlpha) << 24 | (textColor & 0xFFFFFF);

        float textY = drawY + (scaledH - FontRenderer.GLYPH_H) / 2.0f;
        font.drawCenteredWithShadow(ui, label, drawX + scaledW / 2.0f, textY, textColor);
    }

    private int lerpColor(int c1, int c2, float t) {
        int a1 = (c1 >>> 24) & 0xFF;
        int r1 = (c1 >> 16) & 0xFF;
        int g1 = (c1 >> 8) & 0xFF;
        int b1 = c1 & 0xFF;

        int a2 = (c2 >>> 24) & 0xFF;
        int r2 = (c2 >> 16) & 0xFF;
        int g2 = (c2 >> 8) & 0xFF;
        int b2 = c2 & 0xFF;

        int a = (int) (a1 + (a2 - a1) * t);
        int r = (int) (r1 + (r2 - r1) * t);
        int g = (int) (g1 + (g2 - g1) * t);
        int b = (int) (b1 + (b2 - b1) * t);

        return (a << 24) | (r << 16) | (g << 8) | b;
    }

    @Override
    public boolean mouseClicked(float mx, float my, int button) {
        if (!visible || !enabled || button != 0 || !contains(mx, my)) return false;
        if (action != null) action.onPress(this);
        return true;
    }
}

package com.voxelgame.ui.screen;

import com.voxelgame.ui.FontRenderer;
import com.voxelgame.ui.GuiAssets;
import com.voxelgame.ui.UIRenderer;
import com.voxelgame.ui.widget.Button;
import com.voxelgame.ui.widget.Widget;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.function.Consumer;

import static com.voxelgame.core.Language.tr;

public class MainMenuScreen extends Screen {

    public interface Callbacks {
        void onSingleplayer();
        void onOptions();
        void onLanguage();
        void onQuit();
        String versionString();
    }

    private static final String TITLE = "VOXELCRAFT";
    private static final String SUBTITLE = "VOXEL ENGINE";
    private static final String STUDIO = "VOXEL STUDIOS";
    private static final String COPYRIGHT = "\u00A9 2026 Voxel Studios";

    private static final int BG_TOP = 0xFF070B14;
    private static final int BG_BOTTOM = 0xFF0E1726;
    private static final int ACCENT = 0x00E5FF;
    private static final int TEXT_PRIMARY = 0xFFFFFFFF;
    private static final int TEXT_LABEL = 0xFFC9D6EC;
    private static final int TEXT_SECONDARY = 0xFF8FA3BF;
    private static final int TEXT_DIM = 0xFF5A6B85;

    private static final float ANIM_DURATION = 0.6f;
    private static final float ANIM_STAGGER = 0.1f;

    private static final String[] GLOBE = {
            "..######..",
            ".#..##..#.",
            "#...##...#",
            "#...##...#",
            "##########",
            "#...##...#",
            "#...##...#",
            ".#..##..#.",
            "..######..",
    };

    private final Callbacks callbacks;
    private double time = 0;
    private final List<Particle> particles = new ArrayList<>();
    private final Random rnd = new Random(42);
    private float[] buttonAnimProgress;

    private static class Particle {
        float x, y, vx, vy, size, alpha, tw, phase;
        int color;
        Particle(float x, float y, float vx, float vy, float size, int color, float alpha, float tw, float phase) {
            this.x = x; this.y = y; this.vx = vx; this.vy = vy;
            this.size = size; this.color = color; this.alpha = alpha;
            this.tw = tw; this.phase = phase;
        }
    }

    public MainMenuScreen(Callbacks callbacks) {
        this.callbacks = callbacks;
    }

    @Override public boolean rendersWorld() { return false; }
    @Override public boolean closableWithEscape() { return false; }

    private static String label(String key, String fallback) {
        String s = tr(key);
        return (s == null || s.isEmpty()) ? fallback : s;
    }

    private static int col(int alpha, int base, int rgb) {
        int a = ((alpha >>> 24) * base) / 255;
        return (a << 24) | (rgb & 0xFFFFFF);
    }

    private class MenuButton extends Button {
        private final String text;
        private final String index;
        MenuButton(int x, int y, int w, int h, String text, String index, Consumer<Button> onClick) {
            super(x, y, w, h, text, onClick);
            this.text = text;
            this.index = index;
        }
        @Override
        public void render(UIRenderer ui, FontRenderer font, GuiAssets tex, float mx, float my) {
            boolean hov = mx >= x && mx < x + width && my >= y && my < y + height;
            drawPanel(ui, alpha, x, y, width, height, hov);
            int tw = font.scaledWidth(text, 1);
            int ty = y + (height - FontRenderer.GLYPH_H) / 2;
            font.drawWithShadow(ui, text, x + (width - tw) / 2, ty, hov ? TEXT_PRIMARY : TEXT_LABEL);
            if (hov) font.drawWithShadow(ui, ">", x + width - 16, ty, 0xFF000000 | ACCENT);
        }
    }

    private class IconButton extends Button {
        IconButton(int x, int y, int w, int h, Consumer<Button> onClick) {
            super(x, y, w, h, "", onClick);
        }
        @Override
        public void render(UIRenderer ui, FontRenderer font, GuiAssets tex, float mx, float my) {
            boolean hov = mx >= x && mx < x + width && my >= y && my < y + height;
            drawPanel(ui, alpha, x, y, width, height, hov);
            int px = 2;
            int ox = x + (width - GLOBE[0].length() * px) / 2;
            int oy = y + (height - GLOBE.length * px) / 2;
            int c = col(alpha, hov ? 255 : 200, hov ? ACCENT : 0x9FB4CE);
            for (int r = 0; r < GLOBE.length; r++) {
                String row = GLOBE[r];
                for (int i = 0; i < row.length(); i++) {
                    if (row.charAt(i) == '#') ui.fillRect(ox + i * px, oy + r * px, px, px, c);
                }
            }
        }
    }

    private static void drawPanel(UIRenderer ui, int alpha, int x, int y, int w, int h, boolean hov) {
        ui.fillRect(x, y, w, h, col(alpha, hov ? 235 : 205, hov ? 0x0E2430 : 0x0C121C));
        int bc = col(alpha, hov ? 200 : 90, hov ? ACCENT : 0x44566F);
        ui.fillRect(x, y, w, 1, bc);
        ui.fillRect(x, y + h - 1, w, 1, bc);
        ui.fillRect(x, y, 1, h, bc);
        ui.fillRect(x + w - 1, y, 1, h, bc);
        ui.fillRect(x + 1, y + 1, 3, h - 2, col(alpha, hov ? 255 : 110, ACCENT));
        ui.fillRect(x + 1, y + 1, w - 2, 1, col(alpha, hov ? 50 : 26, 0xFFFFFF));
    }

    @Override
    protected void layout() {
        int bw = 320, bh = 36, spacing = 46;
        int cx = (width - bw) / 2;
        int startY = height / 2 + 8;
        widgets.clear();

        add(new MenuButton(cx, startY, bw, bh,
                label("menu.singleplayer", "Singleplayer"), "01",
                b -> callbacks.onSingleplayer())).animDelay = 0;
        add(new MenuButton(cx, startY + spacing, bw, bh,
                label("menu.options", "Options"), "02",
                b -> callbacks.onOptions())).animDelay = ANIM_STAGGER;
        add(new MenuButton(cx, startY + spacing * 2, bw, bh,
                label("menu.quit", "Quit"), "03",
                b -> callbacks.onQuit())).animDelay = ANIM_STAGGER * 2;
        add(new IconButton(width - 40, height - 40, 28, 28,
                b -> callbacks.onLanguage())).animDelay = ANIM_STAGGER * 3;

        buttonAnimProgress = new float[widgets.size()];
        initParticles();
    }

    private void initParticles() {
        particles.clear();
        for (int i = 0; i < 80; i++) {
            float r = rnd.nextFloat();
            particles.add(new Particle(
                    rnd.nextFloat() * width, rnd.nextFloat() * height,
                    (rnd.nextFloat() - 0.5f) * 3, (rnd.nextFloat() - 0.5f) * 2 - 0.5f,
                    1 + rnd.nextFloat() * 1.5f,
                    r > 0.9f ? 0x66E0FF : (r > 0.5f ? 0x9FB8DD : 0xFFFFFF),
                    0.1f + rnd.nextFloat() * 0.45f,
                    0.5f + rnd.nextFloat() * 2.5f, rnd.nextFloat() * 6.28f));
        }
    }

    @Override
    public void update(double deltaTime) {
        time += deltaTime;
        for (int i = 0; i < buttonAnimProgress.length && i < widgets.size(); i++) {
            if (widgets.get(i) instanceof Button btn) {
                float t = (float) (time - btn.animDelay);
                buttonAnimProgress[i] = easeOutCubic(Math.max(0, Math.min(1, t / ANIM_DURATION)));
            }
        }
        for (Particle p : particles) {
            p.x += p.vx * (float) deltaTime * 12;
            p.y += p.vy * (float) deltaTime * 12;
            if (p.x < -10) p.x = width + 10;
            if (p.x > width + 10) p.x = -10;
            if (p.y < -10) p.y = height + 10;
            if (p.y > height + 10) p.y = -10;
        }
    }

    private float easeOutCubic(float t) {
        return 1.0f - (float) Math.pow(1.0f - t, 3);
    }

    private float logoY() {
        return Math.max(28, height / 2f - 160);
    }

    @Override
    protected void renderBackground(UIRenderer ui, FontRenderer font, GuiAssets tex) {
        ui.fillGradientV(0, 0, width, height, BG_TOP, BG_BOTTOM);

        int cy = (int) (logoY() + 20);
        for (int i = 0; i < 180; i += 6) {
            float f = 1 - i / 180f;
            int c = (int) (f * f * 12) << 24 | 0x0A66AA;
            ui.fillRect(0, cy - i - 6, width, 6, c);
            ui.fillRect(0, cy + i, width, 6, c);
        }

        for (Particle p : particles) {
            float twinkle = 0.55f + 0.45f * (float) Math.sin(time * p.tw + p.phase);
            ui.drawParticle(p.x, p.y, p.size, (int) (p.alpha * twinkle * 255) << 24 | (p.color & 0xFFFFFF));
        }

        int band = 8, range = 140;
        for (int i = 0; i < range; i += band) {
            float f = 1 - i / (float) range;
            ui.fillRect(0, i, width, band, (int) (f * f * 100) << 24);
            ui.fillRect(0, height - i - band, width, band, (int) (f * f * 100) << 24);
            ui.fillRect(i, 0, band, height, (int) (f * f * 80) << 24);
            ui.fillRect(width - i - band, 0, band, height, (int) (f * f * 80) << 24);
        }
    }

    @Override
    protected void renderForeground(UIRenderer ui, FontRenderer font, GuiAssets tex,
                                    float mx, float my) {
        ui.fillRect(10, 13, 5, 5, 0xFF000000 | ACCENT);
        ui.fillRect(13, 16, 5, 5, 0x88000000 | ACCENT);
        drawSpaced(ui, font, STUDIO, 24, 12, 1, 2, TEXT_DIM);

        drawLogo(ui, font);

        for (int i = 0; i < widgets.size(); i++) {
            Widget w = widgets.get(i);
            float pr = buttonAnimProgress[i];
            w.y = (int) (w.baseY + (1f - pr) * 24);
            w.alpha = (int) (pr * 255) << 24;
            w.updateHover(mx, my);
            w.render(ui, font, tex, mx, my);

            if (w instanceof MenuButton mb) {
                boolean hov = mx >= w.x && mx < w.x + w.width && my >= w.y && my < w.y + w.height;
                int a = (int) (pr * 255) << 24;
                font.drawWithShadow(ui, mb.index, w.x - 30,
                        w.y + (w.height - FontRenderer.GLYPH_H) / 2,
                        a | (hov ? ACCENT : 0x5A6B85));
            }
        }

        ui.fillRect(0, height - 48, width, 1, 0x1A8FA3BF);
        font.drawWithShadow(ui, callbacks.versionString(), 10, height - 30, TEXT_DIM);
        int cw = font.scaledWidth(COPYRIGHT, 1);
        font.drawWithShadow(ui, COPYRIGHT, width - 56 - cw, height - 30, TEXT_DIM);
    }

    private void drawLogo(UIRenderer ui, FontRenderer font) {
        int scale = 4;
        float x = (width - font.scaledWidth(TITLE, scale)) / 2f;
        float y = logoY();

        float pulse = 0.5f + 0.5f * (float) Math.sin(time * 1.6);
        int glowBase = (int) (18 + 10 * pulse);
        for (int i = 3; i > 0; i--) {
            int g = (glowBase / i << 24) | ACCENT;
            font.drawScaled(ui, TITLE, x - i, y, scale, g);
            font.drawScaled(ui, TITLE, x + i, y, scale, g);
            font.drawScaled(ui, TITLE, x, y - i, scale, g);
            font.drawScaled(ui, TITLE, x, y + i, scale, g);
        }
        font.drawScaledWithShadow(ui, TITLE, x, y, scale, TEXT_PRIMARY);

        int extra = 3;
        int subW = spacedWidth(font, SUBTITLE, 1, extra);
        float sx = (width - subW) / 2f;
        float sy = y + scale * FontRenderer.GLYPH_H + 12;
        drawSpaced(ui, font, SUBTITLE, sx, sy, 1, extra, TEXT_SECONDARY);

        float ly = sy + FontRenderer.GLYPH_H / 2f;
        ui.fillRect(sx - 46, ly, 32, 1, 0x55000000 | ACCENT);
        ui.fillRect(sx + subW + 14, ly, 32, 1, 0x55000000 | ACCENT);
        ui.fillRect(sx - 50, ly - 1, 2, 3, 0xAA000000 | ACCENT);
        ui.fillRect(sx + subW + 48, ly - 1, 2, 3, 0xAA000000 | ACCENT);
    }

    private int spacedWidth(FontRenderer font, String text, int scale, int extra) {
        int w = -extra;
        for (int i = 0; i < text.length(); i++) {
            w += font.scaledWidth(String.valueOf(text.charAt(i)), scale) + extra;
        }
        return w;
    }

    private void drawSpaced(UIRenderer ui, FontRenderer font, String text,
                            float x, float y, int scale, int extra, int color) {
        float cx = x;
        for (int i = 0; i < text.length(); i++) {
            String ch = String.valueOf(text.charAt(i));
            font.drawScaled(ui, ch, cx, y, scale, color);
            cx += font.scaledWidth(ch, scale) + extra;
        }
    }
}

