package com.voxelgame.audio;

import org.lwjgl.openal.AL;
import org.lwjgl.openal.ALC;
import org.lwjgl.openal.ALCCapabilities;

import java.nio.ByteBuffer;
import java.nio.IntBuffer;

import static org.lwjgl.openal.AL10.*;
import static org.lwjgl.openal.ALC10.*;

/**
 * OpenAL playback manager.
 *
 * A small pool of sources plays one-shot effects (currently footstep
 * variants). The listener sits at the player's head so future positional
 * effects get their volume/panning for free.
 */
public class AudioManager {

    private static long device;
    private static long context;
    private static boolean available = false;

    private static final int SOURCE_COUNT = 8;
    private static int[] sources;
    private static int nextSource = 0;

    /** Combined volume applied to every effect, set from the options screen. */
    private static float soundVolume = 1.0f;

    public static boolean isAvailable() { return available; }

    /** Open the default device and create the source pool. */
    public static void init() {
        try {
            device = alcOpenDevice((ByteBuffer) null);
            if (device == 0L) {
                System.err.println("AudioManager: no OpenAL device available, sound disabled");
                return;
            }

            ALCCapabilities alcCaps = ALC.createCapabilities(device);
            context = alcCreateContext(device, (IntBuffer) null);
            if (context == 0L) {
                System.err.println("AudioManager: could not create OpenAL context, sound disabled");
                alcCloseDevice(device);
                return;
            }
            if (!alcMakeContextCurrent(context)) {
                System.err.println("AudioManager: could not make context current, sound disabled");
                alcDestroyContext(context);
                alcCloseDevice(device);
                return;
            }

            AL.createCapabilities(alcCaps);

            sources = new int[SOURCE_COUNT];
            alGenSources(sources);
            for (int src : sources) {
                // Effects play at the head: no distance attenuation, no doppler
                alSourcei(src, AL_SOURCE_RELATIVE, AL_TRUE);
                alSource3f(src, AL_POSITION, 0, 0, 0);
                alSourcef(src, AL_ROLLOFF_FACTOR, 0.0f);
            }

            available = true;
            System.out.println("AudioManager: OpenAL ready, "
                + alGetString(AL_VERSION) + " / " + alcGetString(device, ALC_DEVICE_SPECIFIER));
        } catch (Throwable t) {
            System.err.println("AudioManager: init failed (" + t + "), sound disabled");
            available = false;
        }
    }

    /** Put the ears at the camera: position plus forward/up orientation. */
    public static void setListener(float px, float py, float pz,
                                   float fx, float fy, float fz,
                                   float ux, float uy, float uz) {
        if (!available) return;
        alListener3f(AL_POSITION, px, py, pz);
        alListenerfv(AL_ORIENTATION, new float[] { fx, fy, fz, ux, uy, uz });
    }

    public static void setSoundVolume(float volume) {
        soundVolume = volume;
    }

    /**
     * Play a random clip from the given resource folder.
     *
     * @param folder resource path like "sounds/steps/grass"
     * @param pitch  playback rate multiplier (1.0 = as recorded)
     * @param gain   relative loudness (already includes the master volume)
     */
    public static void play(String folder, float pitch, float gain) {
        if (!available || soundVolume <= 0.001f) return;

        int buffer = SoundLoader.randomBuffer(folder);
        if (buffer == 0) return;

        int src = sources[nextSource];
        nextSource = (nextSource + 1) % sources.length;

        // Restart the source even if it was still playing, so a fast walk
        // never loses a footstep to an occupied channel
        alSourceStop(src);
        alSourcei(src, AL_BUFFER, buffer);
        alSourcef(src, AL_PITCH, pitch);
        alSourcef(src, AL_GAIN, gain * soundVolume);
        alSourcePlay(src);
    }

    public static void destroy() {
        if (!available) return;
        alDeleteSources(sources);
        SoundLoader.cleanup();
        alcMakeContextCurrent(0L);
        alcDestroyContext(context);
        alcCloseDevice(device);
        available = false;
        System.out.println("AudioManager: closed");
    }
}

package com.voxelgame.audio;

import org.lwjgl.stb.STBVorbis;
import org.lwjgl.stb.STBVorbisInfo;
import org.lwjgl.system.MemoryUtil;

import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.IntBuffer;
import java.nio.ShortBuffer;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.lwjgl.openal.AL10.*;

/**
 * Decodes OGG Vorbis clips (via STB) into OpenAL buffers.
 *
 * Folders are scanned as "0.ogg", "1.ogg", ... until the first gap, so a
 * surface's variants only need a rename to 0..N. Buffers are cached, and
 * {@link #randomBuffer} picks a random variant every time it is called.
 */
public class SoundLoader {

    /** Folder -> buffer ids. */
    private static final Map<String, int[]> cache = new HashMap<>();

    public static int randomBuffer(String folder) {
        int[] buffers = cache.get(folder);
        if (buffers == null) {
            buffers = loadFolder(folder);
            cache.put(folder, buffers);
        }
        if (buffers.length == 0) return 0;
        return buffers[(int) (Math.random() * buffers.length)];
    }

    private static int[] loadFolder(String folder) {
        List<Integer> ids = new ArrayList<>();
        for (int i = 0; i < 16; i++) {
            int id = loadOgg(folder + "/" + i + ".ogg");
            if (id == 0) break;
            ids.add(id);
        }
        int[] out = new int[ids.size()];
        for (int i = 0; i < out.length; i++) out[i] = ids.get(i);
        if (out.length > 0) {
            System.out.println("SoundLoader: loaded " + out.length
                + " clip(s) from " + folder);
        }
        return out;
    }

    /** Decode one OGG file into a fresh OpenAL buffer. Returns 0 on failure. */
    private static int loadOgg(String path) {
        byte[] data = null;

        // Classpath first (runs from build/), then the filesystem
        try (InputStream is = SoundLoader.class.getClassLoader().getResourceAsStream(path)) {
            if (is != null) data = is.readAllBytes();
        } catch (IOException ignored) {}
        if (data == null) {
            try {
                data = Files.readAllBytes(Paths.get(path));
            } catch (IOException e) {
                System.err.println("SoundLoader: cannot read " + path);
                return 0;
            }
        }

        ByteBuffer input = MemoryUtil.memAlloc(data.length).put(data).flip();
        IntBuffer error = MemoryUtil.memAllocInt(1);
        STBVorbisInfo info = STBVorbisInfo.malloc();

        long handle = STBVorbis.stb_vorbis_open_memory(input, false, error);
        if (handle == 0L) {
            System.err.println("SoundLoader: STB failed to decode " + path
                + " (error " + (error.get(0) & 0xFFFFFFFFL) + ")");
            MemoryUtil.memFree(input);
            MemoryUtil.memFree(error);
            info.free();
            return 0;
        }

        try {
            STBVorbis.stb_vorbis_get_info(handle, info);
            int channels = info.channels();
            int sampleRate = info.sample_rate();
            int samplesPerChannel = STBVorbis.stb_vorbis_stream_length_in_samples(handle);

            ShortBuffer pcm = MemoryUtil.memAllocShort(samplesPerChannel * channels);
            int decoded = STBVorbis.stb_vorbis_get_samples_short_interleaved(
                handle, channels, pcm);
            if (decoded <= 0) {
                System.err.println("SoundLoader: no samples decoded from " + path);
                MemoryUtil.memFree(pcm);
                return 0;
            }
            pcm.limit(decoded * channels);

            int bufferId = alGenBuffers();
            alBufferData(bufferId,
                channels == 1 ? AL_FORMAT_MONO16 : AL_FORMAT_STEREO16,
                pcm, sampleRate);
            MemoryUtil.memFree(pcm);
            return bufferId;
        } finally {
            STBVorbis.stb_vorbis_close(handle);
            MemoryUtil.memFree(input);
            MemoryUtil.memFree(error);
            info.free();
        }
    }

    /** Release every cached buffer; called once at shutdown. */
    public static void cleanup() {
        for (int[] buffers : cache.values()) {
            if (buffers.length > 0) alDeleteBuffers(buffers);
        }
        cache.clear();
    }
}

