        // 1-block step-up: if the cell above the obstacle is free, climb
        if (tryStepUp(dx, dz)) {
            position.y += STEP_UP;
        } else {
            velocity.x = 0;
            velocity.z = 0;
        }
    }

    /** The cell the mob is trying to enter, one block higher. */
    private boolean tryStepUp(float dx, float dz) {
        int cx = (int) Math.floor(position.x + (dx > 0.001f ? HALF_WIDTH + 0.1f : dx < -0.001f ? -HALF_WIDTH - 0.1f : 0));
        int cz = (int) Math.floor(position.z + (dz > 0.001f ? HALF_WIDTH + 0.1f : dz < -0.001f ? -HALF_WIDTH - 0.1f : 0));
        int stepY = (int) Math.floor(position.y) + 1;
        if (world.isSolid(cx, stepY, cz)) return false;
        if (world.isSolid(cx, stepY + 1, cz)) return false;
        if (!world.isSolid(cx, stepY - 1, cz)) return false;
        return true;
    }

    private void resolveVertical() {
        float minX = position.x - HALF_WIDTH;
        float maxX = position.x + HALF_WIDTH;
        float minZ = position.z - HALF_WIDTH;
        float maxZ = position.z + HALF_WIDTH;

        int x0 = (int) Math.floor(minX), x1 = (int) Math.floor(maxX);
        int z0 = (int) Math.floor(minZ), z1 = (int) Math.floor(maxZ);
        int y0 = (int) Math.floor(position.y);
        int y1 = (int) Math.floor(position.y + HEIGHT);

        if (velocity.y <= 0) {
            // Falling: land on the highest block the body overlaps
            int landY = Integer.MIN_VALUE;
            for (int bx = x0; bx <= x1; bx++) {
                for (int bz = z0; bz <= z1; bz++) {
                    for (int by = y0; by <= y1; by++) {
                        if (!isBlockSolid(bx, by, bz)) continue;
                        landY = Math.max(landY, by + 1);
                    }
                }
            }
            if (landY != Integer.MIN_VALUE && position.y <= landY) {
                position.y = landY;
                velocity.y = 0;
                onGround = true;
            }
        } else {
            // Rising: bump the head
            for (int bx = x0; bx <= x1; bx++) {
                for (int bz = z0; bz <= z1; bz++) {
                    for (int by = y0; by <= y1; by++) {
                        if (!isBlockSolid(bx, by, bz)) continue;
                        position.y = by - HEIGHT - 0.001f;
                        velocity.y = 0;
                        return;
                    }
                }
            }
        }
    }

