/**
     * Face visibility at cross-chunk seams.
     *
     * {@code neighborId} comes from a direct block lookup that already crosses
     * chunk borders, so it is authoritative: a solid neighbour hides the face,
     * an air cell (or an unloaded neighbour chunk, which reads as air) keeps it
     * visible. When the neighbour chunk later loads, markNeighboursDirty()
     * rebuilds this mesh with the real blocks.
     *
     * @param wx world x of the face position
     * @param wy world y of the face position
     * @param wz world z of the face position
     * @param face 0..5 per FACE_OFFSETS
     * @param blockId this block's ID
     * @param neighborId neighbour's block ID (may be 0 if air or not loaded)
     */
    public static boolean facePassesCrossChunk(World world, int wx, int wy, int wz,
                                                int face, byte blockId, byte neighborId) {
        // Air or unloaded neighbour: the face is visible from this side.
        // The old heightmap shortcut used to cull it whenever the neighbour
        // column's top sat above the face - but neighbourId == 0 also means
        // "genuinely air" in a loaded chunk (cave, overhang, slab), so it
        // punched real holes through cliff walls at chunk borders.
        if (neighborId == 0) return true;

