    /**
     * [AMOLED] True-black backdrop for OLED screens: no sky gradient, no sun,
     * no clouds - every pixel off except faint stars, near-black hills and a
     * whisper of fireflies. Pure black reads as a completely dark pixel.
     */
    private void renderAmoledBackground(UIRenderer ui) {
        ui.fillRect(0, 0, width, height, 0xFF000000);

        // Faint stars - the only "sky" element
        for (Star s : stars) {
            float tw = 0.5f + 0.5f * (float) Math.sin(time * s.tw + s.phase);
            int a = (int) (tw * 56) << 24;
            ui.fillRect(s.x, s.y, s.size, s.size, a | 0xB8C4DC);
        }

        // Near-black hills with just enough separation to read depth
        drawHills(ui, hillFar, 0.4f, 0xFF05060C, 0);
        drawHills(ui, hillMid, 1.0f, 0xFF080A14, 0xFF0C1020);
        drawHills(ui, hillNear, 2.0f, 0xFF0B0E1A, 0xFF131A2E);

        // Dying embers of fireflies
        for (Mote m : fireflies) {
            float tw = 0.5f + 0.5f * (float) Math.sin(time * m.tw + m.phase);
            int a = (int) (tw * tw * 40) << 24;
            ui.drawParticle(m.x, m.y, m.size, a | MenuTheme.SUNSET_CORE);
        }

        // Deep black vignette, true AMOLED corners
        int band = 8, range = 140;
        for (int i = 0; i < range; i += band) {
            float f = 1 - i / (float) range;
            ui.fillRect(0, i, width, band, (int) (f * f * 110) << 24);
            ui.fillRect(0, height - i - band, width, band, (int) (f * f * 110) << 24);
            ui.fillRect(i, 0, band, height, (int) (f * f * 80) << 24);
            ui.fillRect(width - i - band, 0, band, height, (int) (f * f * 80) << 24);
        }
    }

    private void drawSun(UIRenderer ui) {
        int sx = (int) (width * 0.74f);
        int sy = height - 200;
        float pulse = 0.5f + 0.5f * (float) Math.sin(time * 1.2);
        for (int r = 5; r >= 1; r--) {
            int a = (int) ((8 + 4 * pulse) / r) << 24;
            ui.fillRect(sx - r * 7, sy - r * 7, r * 14, r * 14, a | MenuTheme.SUNSET_GLOW);
        }
        ui.fillRect(sx - 12, sy - 12, 24, 24, 0xFF000000 | MenuTheme.SUNSET_CORE);
        ui.fillRect(sx - 12, sy - 12, 24, 5, 0xFF000000 | MenuTheme.SUNSET_HI);
    }

