    public static StructureTemplate createDesertTemple() {
        StructureTemplate t = new StructureTemplate("desert_temple", 9, 6, 9);
        for (int y = 0; y < 5; y++) {
            int inset = Math.min(3, y);
            for (int x = inset; x < 9 - inset; x++) {
