        // Hull
        for (int x = 0; x < 9; x++) {
            for (int z = 0; z < 5; z++) {
                boolean hull = z == 0 || z == 4 || x == 0 || x == 8;
                t.setBlock(x, 0, z, BlockType.OAK_LOG);
                t.setBlock(x, 1, z, hull ? BlockType.OAK_PLANKS : BlockType.AIR);
