    print('='*42)
    print(title)
    for row in grid:
        print(''.join(row))
    print()

# Side view columns: z -> x axis (front at left)
def side_view(pose):
    grid = [['.' for _ in range(40)] for _ in range(40)]
    base = np.diag([0.8,-0.8,0.8,1.0])
    for name, rot in pose.items():
        s = scratch(-rot, PIV[name])
        m = base @ s
        for v in corners(BOXES[name]).T:
            w = (m @ v)
            if w[3] != 0: w = w/w[3]
            gx = round(w[2]/0.05)+20   # z axis horizontally (front=-Z -> left)
            gy = round(w[1]/0.05)+20
            if 0 <= gx < 40 and 0 <= gy < 40:
                grid[gy][gx] = {'head':'H','body':'B','rarm':'R','larm':'L','rleg':'l','lleg':'l','nose':'N'}[name]
    return grid

