ZOLOY = {'head': -0.15, 'body': 0.35, 'rarm': 0.25, 'larm': 0.25, 'rleg': 0, 'lleg': 0}

print("NOTE: front of model = -Z (face/nose side). Side view: LEFT is front, RIGHT is back.")
