CH = {'head':'H','body':'B','rarm':'R','larm':'L','rleg':'l','lleg':'l','nose':'N'}
P = 1/16.0

def box_verts(box):
    u,v,w,h,d,ox,oy,oz = box
    pts = []
    for dx in (0,w):
        for dy in (0,h):
            for dz in (0,d):
                pts.append([(ox+dx)*P,(oy+dy)*P,(oz+dz)*P,1])
    return np.array(pts).T

FACES = [(0,1,3,2),(4,5,7,6),(0,1,5,4),(2,3,7,6),(0,2,6,4),(1,3,7,5)]

def scratch(rot_x, pivot):
    px,py,pz = pivot
    return T([px,-py,pz]) @ rx(rot_x) @ T([-px,py,-pz])

def project(m, v):
    w = m @ v
    if abs(w[3]) < 1e-9: return None
    return w[:3]/w[3]

def fill(grid, poly, ch):
    xs = [round(p[0]) for p in poly]; ys = [round(p[1]) for p in poly]
    for y in range(min(ys), max(ys)+1):
        hits = []
        for i in range(len(poly)):
            x1,y1 = poly[i]; x2,y2 = poly[(i+1)%len(poly)]
            if y1 == y2: continue
            if (y1 <= y < y2) or (y2 <= y < y1):
                t = (y - y1)/(y2 - y1)
                hits.append(x1 + t*(x2 - x1))
        if hits:
            for x in range(round(min(hits)), round(max(hits))+1):
                if 0 <= x < 60 and 0 <= y < 60:
                    grid[y][x] = ch

def render(pose, neck_offset, scale):
    grid = [['.' for _ in range(60)] for _ in range(60)]
    base = T([0, neck_offset, 0]) @ np.diag([scale,-scale,scale,1.0])
    for name, rot in pose.items():
        s = scratch(-rot, PIV[name])
        m = base @ s
        vv = box_verts(BOXES[name])
        for f in FACES:
            pts = [project(m, vv[:, i]) for i in f]
            if any(p is None for p in pts): continue
            poly = [(round(p[0]/0.05)+30, round(-p[1]/0.05)+36) for p in pts]
            fill(grid, poly, CH[name])
    for x in range(60): grid[36][x] = '='   # ground at y=0
    return grid

def draw(title, grid):
    print('='*60); print(title)
    for row in grid:
        print(''.join(row))
    print()

