 * Radeon RX 580). Each villager is drawn with its own model matrix:
 * translate(pos) * rotateY(yaw) * scale, and the mob shader offsets the UVs
 * by the profession tile + variant row so a single texture bind covers every
 * profession.
 */
public class VillagerRenderer {

    /** Number of profession tiles across the atlas (matches Profession.ordinal). */
    private static final int ATLAS_TILES = 16;
    /** Skin variants per profession (rows in the 16384x2048 atlas). */
    private static final int ATLAS_VARIANTS = 2;
    /**
     * Tile size as a fraction of the atlas. Only fractions matter here, so
     * the same values work at 1024px tiles (16384x2048) and at the legacy
     * 64px tiles (1024x64).
     */
    private static final float TILE_U = 1.0f / ATLAS_TILES;
    private static final float TILE_V = 1.0f / ATLAS_VARIANTS;

