/** [AST] Drop an asteroid and check it carves a crater with fire. */
private static void testAsteroidImpact(World world) throws Exception {
    log("-- test: asteroid fall + crater");
    int gx = 20, gz = 20;
    world.preloadChunks(new Vector3f(gx + 0.5f, 70f, gz + 0.5f), 3);
    boolean loaded = waitForChunks(world, new Vector3f(gx + 0.5f, 70f, gz + 0.5f), 120_000);
    check(loaded, "asteroid test area loaded", "");

    int ground = world.getGroundHeight(gx, gz);
    world.spawnAsteroidAt(gx, gz, 2);

    for (int i = 0; i < 900; i++) {
        world.updateAsteroids(1.0f / 60.0f, null);
        if (world.getAsteroids().isEmpty()) break;
    }
    check(world.getAsteroids().isEmpty(), "asteroid impacts and despawns", "");

    // The rock drifts a little while falling, so scan a window around
    // the target: a crater shows as air at the old surface level and
    // the raised rim as cobblestone
    int changed = 0;
    for (int dx = -8; dx <= 8; dx++) {
        for (int dz = -8; dz <= 8; dz++) {
            int gy = world.getGroundHeight(gx + dx, gz + dz);
            byte b = world.getBlock(gx + dx, gy, gz + dz);
            if (b == BlockType.AIR.id || b == BlockType.COBBLESTONE.id) changed++;
        }
    }
    check(changed > 8, "crater carved into the terrain", "changed=" + changed
        + " ground@target=" + ground);

    check(!world.getFireBlocks().isEmpty(), "fire burns in the crater",
        "fires=" + world.getFireBlocks().size());
}

