// --- [ROCKET-FX] animation state -------------------------------------
/** Seconds spent in any flight state; drives body sway and camera rumble. */
private float flightTime = 0;
/** Orbit bookkeeping for the cruise leg: centre + phase. */
private float launchX = 0, launchZ = 0, orbitAngle = 0;
/** Current distance from the orbit centre; grows as the ship spirals out. */
private float orbitRadial = 0;
private static final float ORBIT_RADIUS = 22.0f;
private static final float ORBIT_SPEED = 0.22f;

// --- [ROCKET] attitude control ---------------------------------------
/**
 * Current lean of the ship away from vertical, smoothly animated between
 * flight legs so pitch-over and pitch-back read as a real gravity turn:
 * 0 = vertical nose-up (takeoff / vertical landing), PI/2 = flying flat
 * and level along the cruise path in space.
 */
private float attitude = 0f;
/** Yaw (radians) the nose leans toward — the direction of travel. */
private float heading = 0f;
/** Speed of the pitch-over / pitch-back easing. */
private static final float ATTITUDE_RATE = 2.2f;
/** Orbit altitude the ship holds once in space (reached by climb end). */
private static final float CRUISE_ALT = 420.0f;

this.flightTime = 0;
this.launchX = position.x;
this.launchZ = position.z;
this.orbitAngle = 0;
this.orbitRadial = 0;
this.attitude = 0;
this.heading = 0;
this.state = State.READY;

