/** Called once per game frame. */
public void update(float dt, Player player) {
    if (dead) return;
    if (state != State.PAD && state != State.READY && state != State.LANDED) flightTime += dt;

    // Ease the ship's lean toward the attitude wanted by the current leg.
    // 0 = vertical (takeoff / landing straight up), PI/2 = flat in space.
    float want = (state == State.CRUISE) ? (float) (Math.PI / 2.0) : 0f;
    float blend = 1f - (float) Math.exp(-ATTITUDE_RATE * dt);
    attitude += (want - attitude) * blend;

    switch (state) {
        case PAD -> { /* waiting on the pad */ }
        case READY -> { /* seated; SPACE to take off */ }
        case LIFTOFF -> updateLiftoff(dt);
        case CRUISE -> updateCruise(dt);
        case WARP -> updateWarp(dt);
        case DESCENT -> updateDescent(dt);
        case LANDED -> { /* parked at its destination */ }
    }
}

private void updateLiftoff(float dt) {
    phaseTimer += dt;
    // Vertical climb straight off the pad: throttled acceleration, capped
    // speed. The ship stays perfectly upright (no lean) until it clears
    // the atmosphere, then pitches over into orbit.
    vy = Math.min(vy + 42.0f * dt, 55.0f);
    position.y += vy * dt;
    exhaust(dt, -vy);

    if (phaseTimer < 1.0f) {
        // Rumbling start, ground shake
        AudioManager.play("sounds/explosion", 0.35f, 0.3f);
    }
    if (position.y >= CRUISE_ALT) {
        state = State.CRUISE;
        phaseTimer = 0;
        vy = 0;
        // Above the atmosphere: the player has truly reached space.
        com.voxelgame.achievement.AchievementRegistry.trigger("space_reach");
    }
}

