args.newString:
private void updateCruise(float dt) {
    phaseTimer += dt;
    // In space the engines go dark and the ship flies level along its
    // orbit: a smooth gravity turn has already pitched it over, so here it
    // sweeps in a widening arc out to the orbit ring, then holds the ring
    // while its nose stays pointed along the path of travel.
    if (orbitRadial < ORBIT_RADIUS) {
        orbitRadial = Math.min(ORBIT_RADIUS, orbitRadial + 26.0f * dt);
    }
    orbitAngle += ORBIT_SPEED * dt;

    float c = (float) Math.cos(orbitAngle), s = (float) Math.sin(orbitAngle);
    position.x = launchX + c * orbitRadial;
    position.z = launchZ + s * orbitRadial;
    // Hold cruise altitude (a touch of vertical coast is kept so the ride
    // never looks static).
    vy = 1.5f;
    position.y += vy * dt;

    // The nose leans in the direction of travel along the orbit.
    heading = orbitAngle + (float) (Math.PI / 2.0);

    if (phaseTimer >= 2.8f) {
        // Fold across the void toward the landing planet
        state = State.WARP;
        phaseTimer = 0;
        vy = 0;
        AudioManager.play("sounds/explosion", 0.9f, 0.8f);
    }
}

