/**
 * Nose-up tilt in radians for the current flight state — a gravity-turn
 * style pitch-over: the ship climbs vertically off the pad, leans toward
 * its heading as it gains speed, holds the lean in space, and comes in
 * retro-first during descent. Upright when parked.
 */
public float getFlightTilt() {
    return switch (state) {
        case LIFTOFF -> Math.min(0.32f, flightTime * 0.10f);
        case CRUISE -> 0.32f;
        case WARP -> 0.32f;
        case DESCENT -> -0.12f;
        default -> 0f;
    };
}

