args.newString:
private void attachRocketPassenger() {
    if (world == null) return;
    boolean riding = false;
    for (RocketEntity ship : world.getRockets()) {
        if (ship.getPassenger() == player
                && (ship.isFlying() || ship.getState() == RocketEntity.State.READY)) {
            Vector3f p = ship.getPosition();
            // The seat rides the ship's hull, so it tilts with the ship as
            // it pitches over: keep the passenger pinned to the seat (and
            // the camera inside the cabin) through the whole gravity turn.
            float seat = ship.getSeatHeight();
            float lean = ship.getFlightTilt();
            float h = ship.getHeading();
            float sinA = (float) Math.sin(lean), cosA = (float) Math.cos(lean);
            float ox = -seat * sinA * (float) Math.cos(h);
            float oz =  seat * sinA * (float) Math.sin(h);
            float oy =  seat * cosA;
            player.getPosition().set(p.x + ox, p.y + oy, p.z + oz);
            player.setVerticalVelocity(0);
            player.setHorizontalVelocity(0, 0);
            riding = true;
            break;
        }
    }
    player.setRiding(riding);
}

