private void exhaust(float dt, float fallSpeed) {
        // Engine goes dark the moment the ship reaches its cruising leg —
        // it coasts flat through space (no plume), firing retro only during
        // the vertical descent.
        if (state == State.CRUISE || state == State.WARP) return;
        if (particles == null) return;
        exhaustTimer -= dt;
        if (exhaustTimer > 0) return;
        exhaustTimer = 0.035f;
        // Louder, denser plume while throttling hard; a light idle stream in
        // orbit and a wide one during retro-thrust descent.
        float intensity = switch (state) {
            case LIFTOFF -> 1.6f;
            case DESCENT -> 1.2f;
            default -> 1.0f;
        };
        particles.emitRocketExhaust(
            position.x, position.y - 0.6f, position.z, fallSpeed, intensity);
    }

