/** Point the next leg somewhere new: every landing is randomised, so no
     *  two flights put down in the same place — on the alien planet or back
     *  home. Water is avoided; spot falls back to the classic landing spot. */
    private void setupDestination() {
        if (destinationIsPlanet) {
            int lx = world.getGenerator().planetLandingX();
            int lz = world.getGenerator().planetLandingZ();
            for (int i = 0; i < 20; i++) {
                double a = Math.random() * (Math.PI * 2);
                float r = (float) (Math.random() * 140.0);
                int cx = lx + (int) Math.round(Math.cos(a) * r);
                int cz = lz + (int) Math.round(Math.sin(a) * r);
                if (!world.getGenerator().planetChunk(cx, cz)) continue;
                if (world.getGroundHeight(cx, cz) < Chunk.SEA_LEVEL - 1) continue;
                target.set(cx, 0, cz);
                return;
            }
            target.set(lx, 0, lz);
        } else {
            int px = com.voxelgame.world.generator.TerrainGenerator.launchPadX();
            int pz = com.voxelgame.world.generator.TerrainGenerator.launchPadZ();
            for (int i = 0; i < 30; i++) {
                double a = Math.random() * (Math.PI * 2);
                float r = 90.0f + (float) (Math.random() * 180.0);
                int hx = px + (int) Math.round(Math.cos(a) * r);
                int hz = pz + (int) Math.round(Math.sin(a) * r);
                if (world.getGroundHeight(hx, hz) < Chunk.SEA_LEVEL - 1) continue;
                target.set(hx, 0, hz);
                return;
            }
            target.set(px + 6, 0, pz + 6);
        }
    }

