        shakeRoll = roll;
    }

    /** Lock the view into a rigid frame (passenger view riding a craft). */
    public void setRiderOrientation(Vector3f front, Vector3f up) {
        riderFront.set(front.normalize());
        riderUp.set(up);
        riderActive = true;
    }

    /** Release the passenger frame; revert to mouse-look orientation. */
    public void clearRiderOrientation() {
        riderActive = false;
    }

    public Matrix4f getViewMatrix() {
        Vector3f lookFront = riderActive ? riderFront : front;
        Vector3f lookUp = riderActive ? riderUp : up;
        _lookTarget.set(position).add(lookFront);
        viewMatrix.identity().lookAt(position, _lookTarget, lookUp);
        if (shakeRoll != 0
                || shakeOffset.x != 0 || shakeOffset.y != 0 || shakeOffset.z != 0) {
            shakeEye.set(position);
            shakeEye.x += right.x * shakeOffset.x + up.x * shakeOffset.y
                + front.x * shakeOffset.z;
            shakeEye.y += right.y * shakeOffset.x + up.y * shakeOffset.y
                + front.y * shakeOffset.z;
            shakeEye.z += right.z * shakeOffset.x + up.z * shakeOffset.y
                + front.z * shakeOffset.z;
            _lookTarget.set(shakeEye).add(lookFront);
            viewMatrix.identity().lookAt(shakeEye, _lookTarget, lookUp);
            viewMatrix.rotateZ(shakeRoll);
        }
        return viewMatrix;
    }

