/** [ROCKET] Passenger look captured at boarding (in the hull's local
     *  frame) so the camera can roll and pitch along with the craft. */
    private final Vector3f rocketRiderLocalFront = new Vector3f(0, 0, -1);
    private final Vector3f rocketRiderLocalUp = new Vector3f(0, 1, 0);
    private boolean rocketRiderInit = false;

    /**
     * [ROCKET] A seated passenger rides the rocket: feet pinned to the seat,
     * velocities cleared, camera follows through the normal eye calculation.
     * The look frame is locked to the hull, so when the ship pitches over the
     * player flips along with it instead of staying level.
     */
    private void attachRocketPassenger() {
        if (world == null) return;
        RocketEntity ridingShip = null;
        for (RocketEntity ship : world.getRockets()) {
            if (ship.getPassenger() == player
                    && (ship.isFlying() || ship.getState() == RocketEntity.State.READY)) {
                ridingShip = ship;
                break;
            }
        }
        if (ridingShip != null) {
            Vector3f p = ridingShip.getPosition();
            float seat = ridingShip.getSeatHeight();
            float lean = ridingShip.getFlightTilt();
            float h = ridingShip.getHeading();
            // Pin the feet to the seat — the seat offset is rotated with the
            // hull so the passenger stays inside the cabin through the turn.
            Vector3f seatOff = tmpSeat.set(0, seat, 0);
            rotateHull(seatOff, seatOff, h, lean);
            player.getPosition().set(p.x + seatOff.x, p.y + seatOff.y, p.z + seatOff.z);
            player.setVerticalVelocity(0);
            player.setHorizontalVelocity(0, 0);

            // Lock the camera into the hull frame. The look captured on the
            // very first riding frame is the local orientation at boarding
            // (hull = identity on the pad), so rotating it by the hull each
            // frame makes the player roll/pitch exactly like the ship.
            if (!rocketRiderInit) {
                rocketRiderLocalFront.set(camera.getFront());
                rocketRiderLocalUp.set(camera.getUp());
                rocketRiderInit = true;
            }
            Vector3f wFront = tmpFront.set(rocketRiderLocalFront);
            rotateHull(wFront, wFront, h, lean);
            Vector3f wUp = tmpUp.set(rocketRiderLocalUp);
            rotateHull(wUp, wUp, h, lean);
            camera.setRiderOrientation(wFront, wUp);
            player.setRiding(true);
            return;
        }
        rocketRiderInit = false;
        camera.clearRiderOrientation();
        player.setRiding(false);
    }

    /** Apply the craft's hull rotation (yaw {@code h} then tilt {@code a}) to
     *  a vector. Matches the transform the renderer uses for the hull, so the
     *  passenger frame, the seat and the rendered ship all move together. */
    private void rotateHull(Vector3f out, Vector3f v, float h, float a) {
        float ca = (float) java.lang.Math.cos(a), sa = (float) java.lang.Math.sin(a);
        float ch = (float) java.lang.Math.cos(h), sh = (float) java.lang.Math.sin(h);
        float x1 = v.x * ca - v.y * sa;
        float y1 = v.x * sa + v.y * ca;
        float z1 = v.z;
        out.x = x1 * ch + z1 * sh;
        out.y = y1;
        out.z = -x1 * sh + z1 * ch;
    }

