args.newString:
/**
     * Build a full-sized spacecraft hull rather than a bare rocket: a stubby
     * plated fuselage standing on a five-jet engine cluster, swept delta
     * wings with running lights, a glazed bridge the passenger sits in, a
     * radar mast and a beacon-tipped nose. Lying flat it reads as a space
     * cruiser; standing on its tail (takeoff/landing) as a vertical lander.
     */
    private void buildRocket() {
        // ---- Engine cluster (tail, underside): main nozzle + four gimbal
        // pods ringed with rim lights, then a heat-shield skirt above. ----
        parts.add(new Part(0, 0.35f, 0, BlockType.GLOWSTONE, "rocket_nozzle", 1.9f));
        parts.add(new Part(0, 0.5f, 0, BlockType.IRON_BLOCK, "rocket_engine", 1.35f));
        float[][] pods = {{1.9f, 0}, {-1.9f, 0}, {0, 1.9f}, {0, -1.9f}};
        for (float[] pp : pods) {
            parts.add(new Part(pp[0], 0.45f, pp[1], BlockType.GLOWSTONE, "rocket_nozzle", 0.6f));
            parts.add(new Part(pp[0], 0.8f, pp[1], BlockType.IRON_BLOCK, "rocket_engine", 0.5f));
        }
        ring(2.55f, 0.75f, BlockType.GLOWSTONE, "rocket_nozzle", 0.42f, false);

        // ---- Flared wing skirt keeping the heat shield clear of the pad ----
        ring(2.8f, 0.95f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        ring(2.8f, 1.4f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        // Landing struts peeking out under the skirt
        float[][] str = {{2.3f, 0}, {-2.3f, 0}, {0, 2.3f}, {0, -2.3f}};
        for (float[] s : str) {
            parts.add(new Part(s[0], 1.62f, s[1], BlockType.IRON_BLOCK, "rocket_engine", 0.42f));
        }

        // ---- Swept delta wings + trailing stabilisers ----
        sweptWings();

        // ---- Main hull: a sturdy plated fuselage ----
        ring(1.55f, 1.85f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        ring(1.5f, 2.5f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        ring(1.45f, 3.1f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        ring(1.45f, 3.7f, BlockType.RED_CONCRETE, "rocket_hull_red", 1.0f, true);
        for (int y = 4; y < 9; y++) {
            boolean band = (y == 5 || y == 8);
            BlockType block = band ? BlockType.RED_CONCRETE : BlockType.WHITE_CONCRETE;
            String tile = band ? "rocket_hull_red" : "rocket_hull_white";
            ring(1.4f, y, block, tile, 1.0f, true);
        }
        ring(1.4f, 9.0f, BlockType.RED_CONCRETE, "rocket_hull_red", 1.0f, true);

        // ---- Bridge / crew cabin: floor, seat facing the nose, console ----
        ring(1.45f, 10.0f, BlockType.IRON_BLOCK, "rocket_engine", 1.4f, true);
        parts.add(new Part(0, 10.35f, 0.25f, BlockType.IRON_BLOCK, "rocket_door", 0.6f));
        parts.add(new Part(0, 11.0f, 0.55f, BlockType.IRON_BLOCK, "rocket_door", 0.6f));
        parts.add(new Part(0, 10.4f, -0.8f, BlockType.IRON_BLOCK, "rocket_engine", 0.6f));
        parts.add(new Part(0, 10.75f, -0.85f, BlockType.GLOWSTONE, "rocket_nozzle", 0.36f));
        // Canopy: two levels of real block-glass panes hung OUTSIDE the frame
        // radius, so their inward faces are front faces — the seated pilot
        // sees glazing with frames instead of backface chaos.
        cabinBand(11.2f);
        cabinBand(12.0f);
        rail(11.6f);
        ring(1.35f, 12.6f, BlockType.RED_CONCRETE, "rocket_hull_red", 1.0f, true);
        parts.add(new Part(0, 12.75f, 0, BlockType.RED_CONCRETE, "rocket_hull_red", 0.9f));

        // ---- Radar mast and nav light on the flank ----
        parts.add(new Part(1.8f, 6.3f, 1.8f, BlockType.IRON_BLOCK, "rocket_engine", 0.34f));
        parts.add(new Part(1.9f, 6.8f, 1.9f, BlockType.GLOWSTONE, "rocket_nozzle", 0.2f));

        // ---- Tapering nose with a beacon tip ----
        nose(13.1f, 0.88f);
        nose(13.6f, 0.68f);
        nose(14.1f, 0.5f);
        nose(14.5f, 0.33f);
        nose(14.85f, 0.18f);
        parts.add(new Part(0, 15.2f, 0, BlockType.GLOWSTONE, "rocket_nozzle", 0.15f));
    }

    /**
     * Big swept delta wings spreading in the XZ plane (they read as broad
     * fins while the ship stands on its tail and level out with the hull when
     * it pitches into a level cruise), plus two trailing stabilisers rising
     * out of the wing roots.
     */
    private void sweptWings() {
        float[] hy = {1.85f, 2.45f, 3.05f, 3.65f};
        float[] span = {2.7f, 3.3f, 3.7f, 3.95f};
        for (int i = 0; i < hy.length; i++) {
            float y = hy[i], s = span[i];
            for (float x = 1.55f; x <= s; x += 0.78f) {
                parts.add(new Part( x, y, 0f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 0.8f));
                parts.add(new Part(-x, y, 0f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 0.8f));
            }
            // Swept red leading chine along the wing
            for (float x = 1.7f; x <= s - 0.6f; x += 1.15f) {
                parts.add(new Part( x, y, 0.55f, BlockType.RED_CONCRETE, "rocket_fin", 0.55f));
                parts.add(new Part(-x, y, -0.55f, BlockType.RED_CONCRETE, "rocket_fin", 0.55f));
            }
        }
        // Wingtip running lights at the outer spans
        parts.add(new Part( 3.9f, 3.05f, 0f, BlockType.GLOWSTONE, "rocket_nozzle", 0.28f));
        parts.add(new Part(-3.9f, 3.05f, 0f, BlockType.GLOWSTONE, "rocket_nozzle", 0.28f));

        // Two trailing stabiliser fins up out of the wing roots (these stand
        // vertical once the ship pitches level into its cruise).
        float[] fy = {2.9f, 3.7f, 4.5f};
        float[] fz = {2.7f, 3.05f, 3.25f};
        for (int i = 0; i < fy.length; i++) {
            parts.add(new Part(0f, fy[i],  fz[i], BlockType.RED_CONCRETE, "rocket_fin", 0.7f));
            parts.add(new Part(0f, fy[i], -fz[i], BlockType.RED_CONCRETE, "rocket_fin", 0.7f));
            if (i == 2) {
                parts.add(new Part(0f, fy[i] + 0.4f,  fz[i], BlockType.GLOWSTONE, "rocket_nozzle", 0.22f));
                parts.add(new Part(0f, fy[i] + 0.4f, -fz[i], BlockType.GLOWSTONE, "rocket_nozzle", 0.22f));
            }
        }
    }

