/**
     * Build the block hull as stacked rings so it reads as a tall, sleek
     * rocket: a flared white base skirt, a slim white hull with red bands,
     * a glazed crew cabin with a furnished interior (floor, seat, console)
     * and a stepped red nose cone with an amber beacon. Four large swept
     * fins flare out from beyond the skirt so they always read from afar.
     */
    private void buildRocket() {
        // Engine: glowing amber nozzle under the skirt + lights round the rim
        parts.add(new Part(0, 0.35f, 0, BlockType.GLOWSTONE, "rocket_nozzle", 1.9f));
        ring(2.2f, 0.35f, BlockType.GLOWSTONE, "rocket_nozzle", 0.6f, true);

        // Flared base skirt (radius 2) with a red collar where it meets the hull
        ring(2.0f, 0.6f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        ring(2.0f, 1.2f, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f, true);
        parts.add(new Part(0, 1.2f, 0, BlockType.WHITE_CONCRETE, "rocket_hull_white", 1.0f));
        ring(2.0f, 1.8f, BlockType.RED_CONCRETE, "rocket_hull_red", 1.0f, true);

        // Hull: radius-1 solid tube with red marker bands
        for (int y = 2; y < 10; y++) {
            boolean band = (y == 3 || y == 9);
            BlockType block = band ? BlockType.RED_CONCRETE : BlockType.WHITE_CONCRETE;
            String tile = band ? "rocket_hull_red" : "rocket_hull_white";
            parts.add(new Part(0, y, 0, block, tile, 1.0f));
            ring(1.0f, y, block, tile, 1.0f, true);
        }
        ring(1.0f, 10.0f, BlockType.RED_CONCRETE, "rocket_hull_red", 1.0f, true);

        // --- crew cabin: a glazed cockpit the passenger actually sits in ---
        // Floor plate the seat stands on
        parts.add(new Part(0, 10.1f, 0, BlockType.IRON_BLOCK, "rocket_engine", 1.4f));
        // Seat cushion + backrest at the centre of the cabin
        parts.add(new Part(0, 10.55f, 0.25f, BlockType.IRON_BLOCK, "rocket_door", 0.5f));
        parts.add(new Part(0, 11.05f, 0.62f, BlockType.IRON_BLOCK, "rocket_door", 0.5f));
        // Control console ahead of the seat with an amber screen
        parts.add(new Part(0, 10.55f, -0.72f, BlockType.IRON_BLOCK, "rocket_engine", 0.55f));
        parts.add(new Part(0, 10.8f, -0.78f, BlockType.GLOWSTONE, "rocket_nozzle", 0.34f));
        // Window band: two levels of real block-glass panes hung OUTSIDE the
        // frame radius, so their inward faces are front faces — the seated
        // passenger sees glazing with frames instead of backface chaos.
        cabinBand(11.2f);
        cabinBand(12.0f);
        // Waist rail between the two window levels
        rail(11.6f);
        // Red roof over the cockpit (its underside reads as the cabin ceiling)
        ring(1.0f, 12.9f, BlockType.RED_CONCRETE, "rocket_hull_red", 1.0f, true);
        parts.add(new Part(0, 12.9f, 0, BlockType.RED_CONCRETE, "rocket_hull_red", 0.9f));

        // Access door proud of the hull skin, with an amber call button and
        // ladder rungs. Right-clicking any hull part sits the player down.
        parts.add(new Part(1.55f, 2.8f, 0, BlockType.IRON_BLOCK, "rocket_door", 0.7f));
        parts.add(new Part(1.55f, 3.6f, 0, BlockType.IRON_BLOCK, "rocket_door", 0.7f));
        parts.add(new Part(1.55f, 3.2f, 0, BlockType.GLOWSTONE, "rocket_nozzle", 0.24f));
        parts.add(new Part(1.55f, 1.6f, 0, BlockType.IRON_BLOCK, "rocket_engine", 0.3f));
        parts.add(new Part(1.55f, 2.2f, 0, BlockType.IRON_BLOCK, "rocket_engine", 0.3f));

        // Nose cone: shrinking caps tapering to an amber beacon tip
        nose(13.2f, 0.85f);
        nose(13.8f, 0.66f);
        nose(14.3f, 0.48f);
        nose(14.7f, 0.32f);
        nose(15.0f, 0.18f);
        parts.add(new Part(0, 15.35f, 0, BlockType.GLOWSTONE, "rocket_nozzle", 0.16f));

        // Four large swept stabiliser fins flaring out past the skirt so
        // they never hide inside the base
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : dirs) {
            for (int i = 0; i < 7; i++) {
                float t = i / 6.0f;
                float yy = 0.5f + i * 0.7f;
                float off = 2.35f + t * 1.05f;      // sweep outward going up
                float s = 0.75f - t * 0.2f;
                parts.add(new Part(d[0] * off, yy, d[1] * off,
                        BlockType.RED_CONCRETE, "rocket_fin", s));
            }
        }
    }

