param([string]$path = "D:\VoxelCraft\shot.png")
Add-Type -AssemblyName System.Drawing
$bmp = New-Object System.Drawing.Bitmap($path)
$w = $bmp.Width; $h = $bmp.Height
$white = 0; $red = 0; $amber = 0; $dark = 0; $total = 0
$redC = 0
# Bounding boxes (colored = non-sky non-plant pixels we care about)
$minx = 99999; $miny = 99999; $maxx = -1; $maxy = -1
for ($y = 0; $y -lt $h; $y += 2) {
  for ($x = 0; $x -lt $w; $x += 2) {
    $c = $bmp.GetPixel($x, $y)
    $r = [int]$c.R; $g = [int]$c.G; $b = [int]$c.B
    $total++
    # white concrete hull: bright, near-neutral
    if ($r -ge 185 -and $g -ge 185 -and $b -ge 185) { $white++ }
    # red concrete / fins: strong red, weak green&blue
    if ($r -ge 120 -and ($r - $g) -ge 30 -and ($r - $b) -ge 30) { $red++ }
    # amber glowstone: warm bright
    if ($r -ge 200 -and $g -ge 140 -and $b -le 150) { $amber++ }
    # dark iron / mixed
    if ($r -ge 90 -and $r -le 190 -and [Math]::Abs($r - $g) -le 25 -and [Math]::Abs($g - $b) -le 25) { $dark++ }
    # colored ship pixels = red or amber or bright white; track their bbox
    if (($r -ge 120 -and ($r - $g) -ge 30 -and ($r - $b) -ge 30) -or
        ($r -ge 200 -and $g -ge 140 -and $b -le 150) -or
        ($r -ge 185 -and $g -ge 185 -and $b -ge 185)) {
      if ($x -lt $minx) { $minx = $x }
      if ($x -gt $maxx) { $maxx = $x }
      if ($y -lt $miny) { $miny = $y }
      if ($y -gt $maxy) { $maxy = $y }
    }
  }
}
$bmp.Dispose()
$bx = if ($maxx -ge $minx) { "$minx..$maxx (w=$($maxx-$minx))" } else { "none" }
$by = if ($maxy -ge $miny) { "$miny..$maxy (h=$($maxy-$miny))" } else { "none" }
Write-Output ("file={0} {1}x{2}" -f (Split-Path $path -Leaf), $w, $h)
Write-Output ("sampled={0}  white={1}  red={2}  amber={3}  darkgray={4}" -f $total, $white, $red, $amber, $dark)
Write-Output ("colored bbox X: {0}" -f $bx)
Write-Output ("colored bbox Y: {0}" -f $by)

