    elseif ($r -ge 200 -and $g -ge 140 -and $b -le 150) { $amber.Add(@($x,$y)) }
    elseif ($r -ge 185 -and $g -ge 185 -and $b -ge 185) { $white.Add(@($x,$y)) }
  }
}
$bmp.Dispose()
function BBox($list, $name) {
  if ($list.Count -lt 4) { Write-Output ("  {0}: count={1}" -f $name, $list.Count); return }
  $minx = 99999; $miny = 99999; $maxx = -1; $maxy = -1
  foreach ($p in $list) { if ($p[0] -lt $minx) {$minx=$p[0]}; if ($p[0] -gt $maxx) {$maxx=$p[0]}; if ($p[1] -lt $miny) {$miny=$p[1]}; if ($p[1] -gt $maxy) {$maxy=$p[1]} }
  Write-Output ("  {0}: n={1} x[{2}..{3}] w={4} y[{5}..{6}] h={7}" -f $name, $list.Count, $minx, $maxx, ($maxx-$minx), $miny, $maxy, ($maxy-$miny))
}
Write-Output ("file={0} {1}x{2}" -f (Split-Path $path -Leaf), $w, $h)
BBox $red "red"
