BBox $white "white"

param([string]$path = "D:\VoxelCraft\shot.png")
Add-Type -AssemblyName System.Drawing
$bmp = New-Object System.Drawing.Bitmap($path)
$w = $bmp.Width; $h = $bmp.Height
$cols = 80; $rows = 40
$idxX = [int]([Math]::Ceiling($cols / [double]$w))
$chars = for ($r = 0; $r -lt $rows; $r++) {
  $line = ""
  for ($c = 0; $c -lt $cols; $c++) {
    $x0 = [int]([Math]::Floor($c * $w / $cols)); $x1 = [int]([Math]::Floor(($c+1) * $w / $cols)) - 1
    $y0 = [int]([Math]::Floor($r * $h / $rows)); $y1 = [int]([Math]::Floor(($r+1) * $h / $rows)) - 1
    if ($x1 -lt $x0) { $x1 = $x0 }
    if ($y1 -lt $y0) { $y1 = $y0 }
    $nRed = 0; $nAmber = 0; $nWhite = 0; $nTotal = 0
    for ($y = $y0; $y -le $y1; $y += 2) {
      for ($x = $x0; $x -le $x1; $x += 2) {
        $cbit = $bmp.GetPixel($x, $y)
        $r = [int]$cbit.R; $g = [int]$cbit.G; $b = [int]$cbit.B
        $nTotal++
        if ($r -ge 120 -and ($r - $g) -ge 25 -and ($r - $b) -ge 25) { $nRed++ }
        if ($r -ge 200 -and $g -ge 140 -and $b -le 150) { $nAmber++ }
        if ($r -ge 185 -and $g -ge 185 -and $b -ge 185) { $nWhite++ }
      }
    }
    if (($nRed + $nAmber + $nWhite) -ge [Math]::Max(2, $nTotal / 8)) {
      if ($nRed -ge $nWhite -and $nRed -ge $nAmber) { $line += "R" }
      elseif ($nAmber -gt $nRed -and $nAmber -gt $nWhite) { $line += "A" }
      else { $line += "W" }
    } else { $line += "." }
  }
  $line
}
$bmp.Dispose()
Write-Output ("== {0} ==" -f (Split-Path $path -Leaf))
$chars

