case WATER:       return waterPixel(x, y, noise);
            case LAVA:        return lavaPixel(x, y, noise);
            case ACID:        return acidPixel(x, y, noise);

private int lavaPixel(int x, int y, int noise) {
        int r = 220 + noise, g = 80 + noise / 2, b = 20;
        if ((x * 7 + y * 11) % 13 == 0) { r = 255; g = 180; b = 50; }
        if ((x + y * 3) % 17 == 0) { r = 180; g = 40; b = 10; }
        return clamp(r, g, b);
    }

    /** [ACID] Toxic green ooze: dark acid veins with rising bright bubbles
     *  and a hotter rim so the sheet reads as a liquid meniscus. */
    private int acidPixel(int x, int y, int noise) {
        int r = 118 + noise / 2, g = 206 + noise, b = 46 + noise / 3;
        // Darker veins: channels of concentrated dissolved rock
        if ((x * 7 + y * 3) % 9 == 0) { r -= 30; g -= 52; b -= 18; }
        if ((x * 3 + y * 11) % 23 == 0) { g -= 26; }
        // Rising bubbles: undersaturated bright specks
        if ((x * 13 + y * 29) % 61 == 0) { r = 210; g = 255; b = 168; }
        if ((x * 5 + y * 11) % 97 == 0) { r = 176; g = 246; b = 138; }
        // Hot rim glow at the tile edge, like light catching the surface curve
        if (x == 0 || x == 15 || y == 0 || y == 15) { r += 30; g += 8; b += 4; }
        r = Math.max(0, Math.min(255, r));
        g = Math.max(0, Math.min(255, g));
        b = Math.max(0, Math.min(255, b));
        // ~95% opaque: the bed stays a dark liquid hint, never a clear view
        return (0xF2 << 24) | (r << 16) | (g << 8) | b;
    }

