private static void emitWaterSurfaces(Ctx c, Buffers transparent) {
        for (int y = 0; y < Chunk.HEIGHT; y++) {
            for (int x = 0; x < Chunk.SIZE; x++) {
                for (int z = 0; z < Chunk.SIZE; z++) {
                    int wx = c.baseX + x, wz = c.baseZ + z;
                    if (c.env.block(wx, y, wz) != BlockType.WATER.id) continue;
                    // Surface sits 2px below the block top like vanilla,
                    // so water reads as a liquid rather than solid glass.
                    // Colour comes from the biome's water tint.
                    emitBox(transparent, c, x, y, z, BlockType.WATER.id, 0.875f, 0, 0,
                            BiomeColors.waterTintFor(c.env, wx, wz));
                }
            }
        }
    }

