private static final int PLANET_R  = 12;      // walkable radius, chunks
    private static final int PLANET_BASE_Y = 100; // central plateau elevation
    /** [ACID] Planet "sea level": columns carved below this fill with acid. */
    public static final int PLANET_ACID_LEVEL = 76;

/**
     * [SPACE] Height of the alien planet surface: a flat central landing
     * plateau rising toward hilly, cratered rims. Uses large coordinate
     * offsets so the noise is visibly different from the main world.
     * Impact craters and acid rivers are layered on top, but never touch
     * the landing pad: a 24-block clear zone (plus a ~20-block fade apron)
     * keeps the rocket's touchdown spot exactly as smooth as before.
     */
    private int planetHeight(int wx, int wz) {
        int cx = Math.floorDiv(wx, Chunk.SIZE), cz = Math.floorDiv(wz, Chunk.SIZE);
        long dx = (long) cx - planetChunkX, dz = (long) cz - planetChunkZ;
        double radial = Math.sqrt(dx * dx + dz * dz) / (double) PLANET_R;
        double n = heightNoise.fbm(wx * 0.045 + 500_000.0, wz * 0.045, 4, 0.5, 0.8);
        double base = PLANET_BASE_Y + n * 6.0;
        double blend = Math.min(1.0, Math.max(0.0, (radial - 0.30) / 0.40));
        double h = base + 14.0 * blend * blend;
        double cr = heightNoise.noise2D(wx * 0.03 + 900_000.0, wz * 0.03);
        if (cr > 0.45) h -= (cr - 0.45) * 9.0;   // shallow crater bowl

        // [ACID] Craters and rivers fade out around the landing pad.
        double ldx = wx - planetLandingX(), ldz = wz - planetLandingZ();
        double padDist = Math.sqrt(ldx * ldx + ldz * ldz);
        double padFade = Math.min(1.0, Math.max(0.0, (padDist - 24.0) / 20.0));

        // Impact craters first, so a crater floor cuts into any river that
        // crosses it and the two blend into one basin.
        h += craterDelta(wx, wz) * padFade;

        // Acid rivers carve toward the planet's acid level, so their beds
        // sit just below the surface and stay flooded wall to wall.
        double river = heightNoise.fbm(wx * 0.0035 + 2_200_000.0, wz * 0.0035, 2, 0.5, 0.5);
        double bend  = heightNoise.fbm(wx * 0.017 + 3_100_000.0, wz * 0.017, 2, 0.5, 0.7);
        double rr = river * 0.62 + bend * 0.38;
        double dist = Math.abs(rr);
        double edge = 0.042;
        if (dist < edge) {
            double v = 1.0 - dist / edge;
            double smooth = v * v * (3.0 - 2.0 * v);      // flat bed, steep banks
            double floor = PLANET_ACID_LEVEL - 3.0 - 5.0 * smooth;
            h += (floor - h) * padFade;
        }

        h = Math.max(40.0, Math.min(140.0, h));
        return (int) Math.round(h);
    }

    /**
     * [ACID] Broad impact crater on a hash grid (~1 crater per 14 cells):
     * a wide flat bowl with a raised rim. Returns 0 away from a crater, a
     * negative drop inside the bowl and a small positive swell on the rim.
     * Skipped entirely under the icy caps.
     */
    private double craterDelta(int wx, int wz) {
        if (planetZone(wx, wz) == 2) return 0;              // no craters under the ice
        int gx = Math.floorDiv(wx, 40), gz = Math.floorDiv(wz, 40);
        if (hash2i(gx * 3 + 1, gz * 7 + 2) >= 0.055f) return 0;
        double cxj = gx * 40 + 20 + (hash2i(gx * 7 + 3, gz * 13 + 5) - 0.5) * 26.0;
        double czj = gz * 40 + 20 + (hash2i(gx * 11 + 7, gz * 5 + 11) - 0.5) * 26.0;
        double r = 9.0 + hash2i(gx * 5 + 9, gz * 3 + 4) * 10.0;  // 9..19 blocks
        double d = 10.0 + hash2i(gx + 1, gz + 3) * 20.0;         // 10..30 deep
        double dist = Math.hypot(wx - cxj, wz - czj);
        if (dist >= r * 1.7) return 0;
        if (dist <= r) {
            double t = dist / r;
            double bowl = (1.0 - t) * (1.0 - t) * (1.0 + 0.8 * t); // broad floor
            return -d * bowl;
        }
        double rim = (r * 1.7 - dist) / (r * 0.7);                // 1 at rim -> 0 outside
        double u = Math.max(0.0, rim);
        return d * 0.22 * u * u;                                  // swell just outside the bowl
    }

