     *  specks, ~95% opaque so the bed stays a dark hint like water. */
    private static int[] acid(int variant) {
        int[] out = new int[SIZE * SIZE];
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double n = hash(x, y, variant * 7);
                int r = 116 + (int) (n * 26);
                int g = 196 + (int) (n * 50);
                int b = 40 + (int) (n * 22);
                if ((x * 7 + y * 3) % 9 == 0) { r -= 30; g -= 52; b -= 18; }
                if ((x * 13 + y * 29) % 61 == 0) { r = 210; g = 255; b = 168; }
                out[y * SIZE + x] = 0xF2000000 | (clamp(r) << 16) | (clamp(g) << 8) | clamp(b);
            }
        }
        return out;
    }

