import com.voxelgame.world.generator.TerrainGenerator;

public class PlanetProbe {
    public static void main(String[] args) {
        long seed = args.length > 0 ? Long.parseLong(args[0]) : 12345L;
        TerrainGenerator g = new TerrainGenerator(seed);
        int lx = g.planetLandingX(), lz = g.planetLandingZ();
        System.out.println("seed=" + seed + " landing=(" + lx + "," + lz + ")");

        int padMin = 9999, padMax = -1, padSum = 0, padN = 0;
        for (int dz = -10; dz <= 10; dz++) {
            for (int dx = -10; dx <= 10; dx++) {
                int h = g.getHeight(lx + dx, lz + dz);
                padMin = Math.min(padMin, h); padMax = Math.max(padMax, h);
                padSum += h; padN++;
            }
        }
        System.out.println("PAD 21x21: min=" + padMin + " max=" + padMax
            + " avg=" + (padSum / (double) padN));

        System.out.println("PLANET_ACID_LEVEL=" + TerrainGenerator.PLANET_ACID_LEVEL);
        int min = 9999, max = -1, under = 0, total = 0;
        for (int z = lz - 200; z <= lz + 200; z++) {
            for (int x = lx - 200; x <= lx + 200; x++) {
                if (!g.planetChunk(x, z)) continue;
                int h = g.getHeight(x, z);
                total++;
                min = Math.min(min, h); max = Math.max(max, h);
                if (h < TerrainGenerator.PLANET_ACID_LEVEL) under++;
            }
        }
        System.out.println("planet blocks=" + total + " min=" + min + " max=" + max
            + " under-acid=" + under + " (" + String.format("%.1f", 100.0 * under / total) + "%)");

        int pits = 0, flatRiver = 0;
        for (int z = lz - 200; z <= lz + 200; z += 3) {
            for (int x = lx - 200; x <= lx + 200; x += 3) {
                if (!g.planetChunk(x, z)) continue;
                int h = g.getHeight(x, z);
                if (h <= 62) pits++;
                if (h >= TerrainGenerator.PLANET_ACID_LEVEL - 5
                    && h <= TerrainGenerator.PLANET_ACID_LEVEL + 6) flatRiver++;
            }
        }
        System.out.println("deep craters h<=62: " + pits + " | near-acid-band cells: " + flatRiver);

        StringBuilder sb = new StringBuilder();
        for (int dx = 0; dx <= 190; dx += 5) {
            sb.append(dx).append(':').append(g.getHeight(lx + dx, lz)).append(' ');
        }
        System.out.println("EAST transect (pad +190): " + sb);

        StringBuilder sb2 = new StringBuilder();
        for (int dz = 0; dz <= 190; dz += 5) {
            sb2.append(dz).append(':').append(g.getHeight(lx, lz + dz)).append(' ');
        }
        System.out.println("SOUTH transect (pad +190): " + sb2);
    }
}

