    /**
     * [VEG] Ground cover on the landable planet: grass tufts, star-flowers
     * and sparse alien trees. Skipped on the ice caps, next to acid pools
     * and inside the landing apron so the pad stays clean. Deterministic
     * per world position, so neighbouring chunks line up.
     */
    private void placePlanetVegetation(Chunk chunk, int ox, int oz) {
        int lpx = planetLandingX(), lpz = planetLandingZ();
        for (int x = 0; x < Chunk.SIZE; x++) {
            for (int z = 0; z < Chunk.SIZE; z++) {
                int wx = ox + x, wz = oz + z;
                int h = planetHeight(wx, wz);
                if (h <= PLANET_ACID_LEVEL + 2) continue;  // acid pool / baked bed
                int zone = planetZone(wx, wz);
                if (zone == 2) continue;                   // icy caps stay bare
                double padDist = Math.hypot(wx - lpx, wz - lpz);
                if (padDist < 44.0) continue;              // landing apron
                double r = hashNoise(wx, 3, wz, 23);

                // Sparse alien trees on the basalt plains, away from the pad.
                if (padDist >= 56.0 && zone == 1 && r > 0.972 && h < 118) {
                    placePlanetTree(chunk, ox, oz, wx, h + 1, wz);
                    continue;
                }
                if (r > 0.55) {                            // grass tufts
                    chunk.setBlock(x, h + 1, z, BlockType.GRASS_PLANT.id);
                } else if (r > 0.546) {                    // rare star-flowers
                    int f = hashNoise(wx, 4, wz, 29) > 0.5
                        ? BlockType.LAVENDER.id : BlockType.DANDELION.id;
                    chunk.setBlock(x, h + 1, z, f);
                }
            }
        }
    }

    /** [VEG] Small alien tree: dark trunk topped with a flat toxic canopy. */
    private void placePlanetTree(Chunk chunk, int ox, int oz, int wx, int baseY, int wz) {
        int lx = wx - ox, lz = wz - oz;
        if (lx - 2 < 0 || lx + 2 >= Chunk.SIZE || lz - 2 < 0 || lz + 2 >= Chunk.SIZE) return;
        int th = 3 + (int) (hashNoise(wx, 2, wz, 41) * 3); // 3..5 trunk
        for (int y = 0; y < th; y++) {
            setWorld(chunk, ox, oz, wx, baseY + y, wz, BlockType.OAK_LOG.id, false);
