                if (Math.abs(dx) + Math.abs(dz) > 4) continue;
                setWorld(chunk, ox, oz, wx + dx, top, wz + dz, BlockType.SPRUCE_LEAVES.id, false);
            }
        }
        setWorld(chunk, ox, oz, wx, top + 1, wz, BlockType.SPRUCE_LEAVES.id, false);
    }

