import com.voxelgame.world.BlockType;
import com.voxelgame.world.Chunk;
import com.voxelgame.world.generator.TerrainGenerator;

public class VegProbe {
    public static void main(String[] a) {
        long seed = Long.parseLong(a[0]);
        TerrainGenerator tg = new TerrainGenerator(seed);
        int lx = tg.planetLandingX(), lz = tg.planetLandingZ();
        int ccx = Math.floorDiv(lx, Chunk.SIZE), ccz = Math.floorDiv(lz, Chunk.SIZE);
        System.out.printf("seed=%d center=chunk(%d,%d) landing=(%d,%d)%n", seed, ccx, ccz, lx, lz);
        int total = 0, flowers = 0, trunks = 0, apron = 0, GRASS_LV = 0;
        java.util.List<String> ice = new java.util.ArrayList<>();
        int[] ring = new int[4]; // padDist buckets: <44, 44-55, 56-79, >=80
        for (int ddx = -3; ddx <= 3; ddx++) {
            for (int ddz = -3; ddz <= 3; ddz++) {
                int cx = ccx + ddx, cz = ccz + ddz;
                Chunk c = new Chunk(cx, cz);
                tg.generate(c);
                int p = 0, fl = 0, tr = 0;
                int[] cr = new int[4];
                for (int x = 0; x < Chunk.SIZE; x++) {
                    for (int z = 0; z < Chunk.SIZE; z++) {
                        int wx = c.getWorldX() + x, wz = c.getWorldZ() + z;
                        double pd = Math.hypot(wx - lx, wz - lz);
                        for (int y = 0; y < Chunk.HEIGHT; y++) {
                            int id = c.getBlock(x, y, z);
                            if (id == BlockType.OAK_LOG.id) { tr++; continue; }
                            if (id == BlockType.GRASS_PLANT.id || id == BlockType.DANDELION.id
                                    || id == BlockType.POPPY.id || id == BlockType.LAVENDER.id) {
                                p++;
                                if (id != BlockType.GRASS_PLANT.id) fl++;
                                int b = pd < 44 ? 0 : pd < 56 ? 1 : pd < 80 ? 2 : 3;
                                cr[b]++; ring[b]++;
                            }
                        }
                    }
                }
                total += p; flowers += fl; trunks += tr;
                if (p == 0 && tr == 0) ice.add(cx + "," + cz);
                System.out.printf("chunk(%d,%d) plants=%d flowers=%d trunks=%d%n", cx, cz, p, fl, tr);
            }
        }
        System.out.printf("TOTAL plants=%d flowers=%d trunks=%d apron(<44)=%d ring([44,56)=%d [56,80)=%d >=80=%d iceChunks=%s%n",
            total, flowers, trunks, ring[0], ring[1], ring[2], ring[3], ice);
    }
}

