                drawItem(ui, stack, sx + 1, hotbarY + 1);
                drawCount(ui, font, stack.getCount(), sx, hotbarY);
                if (inside(mx, my, sx, hotbarY, SLOT, SLOT)) hovered = stack;
            }
        }

