        if (!mouse.isEmpty()) {
            drawItem(ui, mouse, (int) mx - ICON / 2, (int) my - ICON / 2);
            if (mouse.getCount() > 1) {
                drawCount(ui, font, mouse.getCount(),
                    (int) mx - ICON / 2, (int) my - ICON / 2);
            }
