        if (hovered != null) {
            List<String> lines = new ArrayList<>();
            if (hovered.isBlock()) {
                lines.add(tr("block." + hovered.getBlockType().name));
            } else if (hovered.getItem() != null) {
                lines.add(hovered.getItem().displayName);
            }
            if (!lines.isEmpty()) {
                GlassTooltip.draw(ui, font, lines, (int) mx, (int) my, width, height);
            }
        }
