/**
 * Top-down block map in the top-right corner.  Each GUI pixel maps one
 * block of the surface; the column's surface block colours the cell and
 * any canopy above it is layered on top so forests read as green.
 */
private void drawMinimap(UIRenderer ui, DebugInfo d, World world) {
    int w = ui.getWidth();
    int px = (int) java.lang.Math.floor(d.x);
    int pz = (int) java.lang.Math.floor(d.z);

    // Rebuild the cached raster when the player steps to a new block
    if (px != mapCenterX || pz != mapCenterZ) {
        mapCenterX = px;
        mapCenterZ = pz;
        rebuildMap(world, px, pz);
    }

    int mapX = w - MINIMAP_SIZE - MINIMAP_PAD;
    int mapY = MINIMAP_PAD;

    // Panel background + border
    ui.useSolidColor();
    ui.fillRect(mapX - 2, mapY - 2, MINIMAP_SIZE + 4, MINIMAP_SIZE + 4, 0x660A0E18);
    ui.drawRectOutline(mapX - 1, mapY - 1, MINIMAP_SIZE + 2, MINIMAP_SIZE + 2, 0xFF2A3450);

    // Blit cached cells
    for (int i = 0; i < mapPixels.length; i++) {
        int x = mapX + (i % MINIMAP_STRIDE) * MINIMAP_CELL;
        int y = mapY + (i / MINIMAP_STRIDE) * MINIMAP_CELL;
        ui.fillRect(x, y, MINIMAP_CELL, MINIMAP_CELL, mapPixels[i]);
    }

    // Player dot + heading tick
    int cx = mapX + MINIMAP_SIZE / 2;
    int cy = mapY + MINIMAP_SIZE / 2;
    ui.fillRect(cx - 2, cy - 2, 5, 5, 0xFF000000);
    ui.fillRect(cx - 1, cy - 1, 3, 3, 0xFFFFFFFF);
    float yawRad = (float) java.lang.Math.toRadians(d.yaw);
    int tx = cx + java.lang.Math.round((float) java.lang.Math.cos(yawRad) * 7);
    int ty = cy + java.lang.Math.round((float) java.lang.Math.sin(yawRad) * 7);
    ui.fillRect(tx - 1, ty - 1, 3, 3, 0xFFFFFFFF);
}

private void rebuildMap(World world, int px, int pz) {
    int idx = 0;
    for (int dz = -MINIMAP_RADIUS; dz <= MINIMAP_RADIUS; dz++) {
        for (int dx = -MINIMAP_RADIUS; dx <= MINIMAP_RADIUS; dx++) {
            mapPixels[idx++] = minimapBlockColor(world, px + dx, pz + dz);
        }
    }
}

/** Surface colour of a minimap cell: ground block, then canopy above. */
private static int minimapBlockColor(World world, int wx, int wz) {
    int gy = world.getGroundHeight(wx, wz);
    if (gy < 0 || gy >= Chunk.HEIGHT) return MAP_TRANSPARENT;

    int b = world.getBlock(wx, gy, wz);
    int color = blockMapColor(b);

    // Layer tree canopy on top so forests read as green
    for (int y = gy + 1; y <= gy + 6 && y < Chunk.HEIGHT; y++) {
        int above = world.getBlock(wx, y, wz);
        if (above == 0) break;
        if (BlockType.isTransparentFast(above)) continue;
        if (isLeafBlock(above)) return MAP_LEAF_COLOR;
        if (isLogBlock(above))  return MAP_LOG_COLOR;
    }
    return color;
}

private static boolean isLeafBlock(int id) {
    return id == BlockType.OAK_LEAVES.id
        || id == BlockType.SPRUCE_LEAVES.id
        || id == BlockType.BIRCH_LEAVES.id
        || id == BlockType.JUNGLE_LEAVES.id
        || id == BlockType.AUTUMN_LEAVES.id
        || id == BlockType.CHERRY_LEAVES.id;
}

private static boolean isLogBlock(int id) {
    return id == BlockType.OAK_LOG.id
        || id == BlockType.SPRUCE_LOG.id
        || id == BlockType.BIRCH_LOG.id
        || id == BlockType.JUNGLE_LOG.id;
}

private static int blockMapColor(int blockId) {
    if (blockId == 0) return MAP_TRANSPARENT;
    BlockType t = BlockType.fromId(blockId);
    if (t == null) return MAP_TRANSPARENT;
    return 0xFF000000 | (t.color & 0xFFFFFF);
}

