                    float strength = 5.0f;
                    velocity.x += (fromDir.x / len) * strength;
                    velocity.z += (fromDir.z / len) * strength;
                    velocity.y = 5.0f;
                }
            }
            state = State.FLEE;
            fleeTimer = 3.0f;
            fleeToHome = false;
            hasTarget = false;
            socialBuddy = null;
