            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 3),
                new ItemStack(ItemRegistry.POTION_HEALING, 1), LOW),
        });

        TABLES.put(Villager.Profession.MASON, new TradeOffer[]{
            TradeOffer.buy(new ItemStack(BlockType.COBBLESTONE, 8), 1, HIGH),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 1),
                new ItemStack(BlockType.STONE_BRICKS, 1), HIGH),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 2),
                new ItemStack(BlockType.CHISELED_SANDSTONE, 1), MED),
        });

        TABLES.put(Villager.Profession.WARRIOR, new TradeOffer[]{
            TradeOffer.buy(new ItemStack(ItemRegistry.ARROW, 6), 1, HIGH),
            TradeOffer.buy(new ItemStack(ItemRegistry.IRON_INGOT, 4), 1, HIGH),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 4),
                new ItemStack(ItemRegistry.IRON_SWORD, 1), MED),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 5),
                new ItemStack(BlockType.TNT, 1), LOW),
        });

        // NITWIT: no trades
        TABLES.put(Villager.Profession.NITWIT, new TradeOffer[]{});

        // ------------------------------------------------------------------
        // Wandering trader / Emerald Vault (exclusives + meteors)
        // ------------------------------------------------------------------
        TABLES.put(null, new TradeOffer[]{
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 5),
                new ItemStack(BlockType.METEORITE_ORE, 1), LOW),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 6),
                new ItemStack(BlockType.ROCKET_FUEL, 1), LOW),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 4),
                new ItemStack(ItemRegistry.POTION_FIRE_RESISTANCE, 1), LOW),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 3),
                new ItemStack(ItemRegistry.SLIME_BALL, 4), MED),
            TradeOffer.sell(new ItemStack(ItemRegistry.EMERALD, 6),
                new ItemStack(BlockType.ROCKET_BODY, 1), LOW),
        });
    }

    /** Offers for a village profession, or an empty array for NITWIT. */
    public static TradeOffer[] offersFor(Villager.Profession p) {
        TradeOffer[] offers = TABLES.get(p);
        return offers != null ? offers : new TradeOffer[0];
    }

    /** Wandering-trader / vault catalogue (keyed by null profession). */
    public static TradeOffer[] wanderingOffers() {
        return offersFor(null);
    }

    private TradeRegistry() {}
}

package com.voxelgame.economy;

/**
 * [ECO] Village reputation.
 *
 * Reputation grows by +1 on every completed trade. It drives the price
 * discount villagers give the player: higher tiers mean friendlier prices.
 *
 *   Нейтрал      (0-4)     0% discount
 *   Дружелюбный  (5-14)    5%  discount
 *   Доверенный   (15-29)   15% discount
 *   Герой        (30+)     30% discount   (also unlocks hero perks)
 */
public final class Reputation {

    public static final int FRIENDLY_TIER  = 5;
    public static final int TRUSTED_TIER   = 15;
    public static final int HERO_TIER      = 30;

    /** 0..3 tier index, used to look up "reputation.neutral/friendly/...". */
    public static int tier(int reputation) {
        if (reputation >= HERO_TIER) return 3;
        if (reputation >= TRUSTED_TIER) return 2;
        if (reputation >= FRIENDLY_TIER) return 1;
        return 0;
    }

    /** Language key for the current tier ("reputation.neutral", ...). */
    public static String tierKey(int reputation) {
        return switch (tier(reputation)) {
            case 1 -> "reputation.friendly";
            case 2 -> "reputation.trusted";
            case 3 -> "reputation.hero";
            default -> "reputation.neutral";
        };
    }

    public static boolean isHero(int reputation) {
        return reputation >= HERO_TIER;
    }

    /** Percentage discount (5 / 15 / 30) for the given reputation. */
    public static int discountPercent(int reputation) {
        return switch (tier(reputation)) {
            case 1 -> 5;
            case 2 -> 15;
            case 3 -> 30;
            default -> 0;
        };
    }

    /** Emerald payment after the reputation discount, at least 1. */
    public static int discountedPrice(int reputation, int baseEmeralds) {
        if (baseEmeralds <= 1) return baseEmeralds;
        int cut = Math.floorDiv(baseEmeralds * discountPercent(reputation), 100);
        return Math.max(1, baseEmeralds - cut);
    }

    private Reputation() {}
}

package com.voxelgame.economy;

import com.voxelgame.item.Inventory;
import com.voxelgame.item.ItemStack;

/**
 * [ECO] Trade execution engine.
 *
 * Reads the player's inventory, applies the reputation discount to any
 * emerald payment, consumes the required goods, hands out the reward and
 * reports back the outcome. All item matching is by canonical name so that
 * both registry items and BlockType pseudo-block stacks are accepted.
 */
public final class TradeManager {

    public enum Result {
        SUCCESS,          // trade went through (+1 reputation)
        OUT_OF_STOCK,     // this villager has already sold all of them
        CANNOT_PAY,       // the player does not own the required goods
        NO_SPACE          // the reward did not fit in the inventory
    }

    /**
     * Execute one offer against the given inventory using the player's
     * current reputation.
     *
     * @param stockRemaining how many of this offer the villager still has
     * @return the outcome; stockRemaining is NOT touched here (the caller
     *         owns the villager's counters)
     */
    public static Result execute(Inventory inv, TradeOffer offer, int reputation, int stockRemaining) {
        if (offer == null) return Result.CANNOT_PAY;
        if (stockRemaining <= 0) return Result.OUT_OF_STOCK;

        int payA = offer.costA.getCount();
        if (isEmerald(offer.costA)) {
            payA = Reputation.discountedPrice(reputation, payA);
        }
        if (inv.countByName(Inventory.canonicalName(offer.costA)) < payA) return Result.CANNOT_PAY;
        if (offer.costB != null && !offer.costB.isEmpty()) {
            if (inv.countByName(Inventory.canonicalName(offer.costB)) < offer.costB.getCount()) {
                return Result.CANNOT_PAY;
            }
        }

        // Consume the payment, then try to place the reward.
        inv.removeByName(Inventory.canonicalName(offer.costA), payA);
        if (offer.costB != null && !offer.costB.isEmpty()) {
            inv.removeByName(Inventory.canonicalName(offer.costB), offer.costB.getCount());
        }

        if (!isEmerald(offer.give) && !inv.addStack(offer.give.copy()).isEmpty()) {
            // Reward did not fit — refund the payment.
            inv.addStack(offer.costA.copyWithCount(payA));
            if (offer.costB != null && !offer.costB.isEmpty()) {
                inv.addStack(offer.costB.copy());
            }
            return Result.NO_SPACE;
        }
        // Gem payments always fit (emeralds merge into any stack).
        if (isEmerald(offer.give)) {
            inv.addStack(offer.give.copy());
        }

        return Result.SUCCESS;
    }

    private static boolean isEmerald(ItemStack s) {
        return s != null && !s.isEmpty()
            && "emerald".equals(Inventory.canonicalName(s));
    }

    private TradeManager() {}
}

