    def line(self, x0, y0, x1, y1, role, second=None):
        """45-deg diagonal helpers: step along the dominant axis."""
        dx = 1 if x1 >= x0 else -1
        dy = 1 if y1 >= y0 else -1
        steps = max(abs(x1 - x0), abs(y1 - y0))
        cx, cy = x0, y0
        for _ in range(steps + 1):
            self.put(cx, cy, role)
            if second is not None:
                self.put(cx + second[0], cy + second[1], role)
            rx = cx + (x1 - x0)
            ry = cy + (y1 - y0)
            if abs(rx) == abs(ry) or rx == 0 or ry == 0:
                pass
            if cx < x1 and (abs(rx) >= abs(ry) or rx == 0):
                pass
            cx += dx if cx != x1 else 0
            cy += dy if cy != y1 else 0

    def diagonal(self, x0, y0, x1, y1, role, thickness=1, second_char=None):
        """Draw a 1px diagonal then stack thickness along one side."""
        dx = 1 if x1 >= x0 else -1
        dy = 1 if y1 >= y0 else -1
        steps = max(abs(x1 - x0), abs(y1 - y0))
        cx, cy = x0, y0
        for _ in range(steps + 1):
            for t in range(thickness):
                if second_char is not None and t % 2 == 0:
                    self.put(cx, cy + t, second_char)
                elif second_char is None:
                    self.put(cx, cy, role)
                else:
                    self.put(cx, cy + t, role)
            cx += dx
            cy += dy

